'use client';

import { CardStackProvider, CardStackViewport } from '@/components/ui/stack';
import { MotionConfig } from 'motion/react';

import { SchemaBuilderProvider } from '../core/context';
import type { SchemaBuilderProps } from '../types';
import { cn } from '../lib/utils';
import { ClientOnly } from '../schema/schema-builder/components/client-only';
import { SchemasRoute } from '../schema/schema-builder/components/schemas/schemas-route';
import { SchemaBuilderDataProvider } from '../schema/schema-builder-core/lib/gql/hooks/schema-builder';

function assertDataStateMatchesScope(props: SchemaBuilderProps): void {
  if (!props.dataState) return;

  const matchesOrganization = props.dataState.routeOrgId === props.scope.orgId;
  const matchesDatabase = props.dataState.routeDatabaseId === props.scope.databaseId;
  if (!matchesOrganization || !matchesDatabase) {
    throw new Error('SchemaBuilder dataState must match the configured organization and database scope');
  }
}

export function SchemaBuilder(props: SchemaBuilderProps) {
  assertDataStateMatchesScope(props);

  return (
    <MotionConfig reducedMotion='user'>
      <SchemaBuilderProvider
        adapter={props.adapter}
        scope={props.scope}
        colorMode={props.colorMode}
        preferences={props.preferences}
        onPreferencesChange={props.onPreferencesChange}
        activeTab={props.activeTab}
        onActiveTabChange={props.onActiveTabChange}
        selectedTableId={props.selectedTableId}
        onSelectedTableChange={props.onSelectedTableChange}
        onNavigate={props.onNavigate}
        onInvalidate={props.onInvalidate}
        tabs={props.tabs}
      >
        <CardStackProvider layoutMode='side-by-side' defaultPeekOffset={48}>
          <SchemaBuilderDataProvider value={props.dataState}>
            <div
              className={cn('relative flex h-full min-h-0 w-full flex-col', props.className)}
              data-color-mode={props.colorMode}
              data-schema-builder='root'
            >
              <SchemasRoute emptyState={props.emptyState} />
              <ClientOnly>
                <CardStackViewport peekDepth={3} />
              </ClientOnly>
            </div>
          </SchemaBuilderDataProvider>
        </CardStackProvider>
      </SchemaBuilderProvider>
    </MotionConfig>
  );
}

'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode
} from 'react';
import { useStore } from 'zustand';
import type { StoreApi } from 'zustand/vanilla';

import { createSchemaBuilderStore, type SchemaBuilderStoreState } from './store';
import type {
  SchemaBuilderHostOptions,
  SchemaBuilderPreferences,
  SchemaBuilderTab
} from '../types';

const CORE_TAB_IDS = new Set(['editor', 'relationships', 'indexes', 'security']);
const EMPTY_TABS: readonly SchemaBuilderTab[] = [];

export interface SchemaBuilderContextValue extends SchemaBuilderHostOptions {
  store: StoreApi<SchemaBuilderStoreState>;
  setActiveTab: (tabId: string) => void;
  setPreferences: (
    preferences:
      | SchemaBuilderPreferences
      | ((current: SchemaBuilderPreferences) => SchemaBuilderPreferences)
  ) => void;
  selectTable: (tableId: string | null, tableName?: string | null) => void;
  selectField: (fieldId: string | null) => void;
}

const SchemaBuilderContext = createContext<SchemaBuilderContextValue | null>(null);

function validateExtensionTabs(tabs: readonly SchemaBuilderTab[]): void {
  const seen = new Set(CORE_TAB_IDS);

  for (const tab of tabs) {
    if (!tab.id.trim()) throw new Error('SchemaBuilder extension tab ids cannot be empty');
    if (seen.has(tab.id)) {
      throw new Error(`Duplicate SchemaBuilder tab id: ${tab.id}`);
    }
    seen.add(tab.id);
  }
}

export interface SchemaBuilderProviderProps extends SchemaBuilderHostOptions {
  children: ReactNode;
}

export function SchemaBuilderProvider(props: SchemaBuilderProviderProps) {
  const { children, tabs = EMPTY_TABS } = props;
  const [store] = useState(() =>
    createSchemaBuilderStore(
      props.scope,
      props.preferences,
      props.activeTab,
      props.selectedTableId ?? null
    )
  );

  const validatedTabs = useMemo(() => {
    validateExtensionTabs(tabs);
    return tabs;
  }, [tabs]);

  useEffect(() => {
    store.getState().replaceScope(props.scope);
  }, [props.scope, store]);

  useEffect(() => {
    store.getState().replacePreferences(props.preferences);
  }, [props.preferences, store]);

  useEffect(() => {
    store.getState().replaceActiveTab(props.activeTab);
  }, [props.activeTab, store]);

  useEffect(() => {
    if (props.selectedTableId !== undefined) {
      store.getState().setSelectedTableId(props.selectedTableId);
    }
  }, [props.scope, props.selectedTableId, store]);

  const setActiveTab = useCallback(
    (tabId: string) => {
      const extension = validatedTabs.find((tab) => tab.id === tabId);
      if (!CORE_TAB_IDS.has(tabId) && !extension) {
        throw new Error(`Unknown SchemaBuilder tab id: ${tabId}`);
      }
      void extension?.preload?.();
      store.getState().replaceActiveTab(tabId);
      props.onActiveTabChange(tabId);
    },
    [props.onActiveTabChange, store, validatedTabs]
  );

  const setPreferences = useCallback(
    (
      update:
        | SchemaBuilderPreferences
        | ((current: SchemaBuilderPreferences) => SchemaBuilderPreferences)
    ) => {
      const current = store.getState().preferences;
      const next = typeof update === 'function' ? update(current) : update;
      store.getState().replacePreferences(next);
      props.onPreferencesChange(next);
    },
    [props.onPreferencesChange, store]
  );

  const selectTable = useCallback(
    (tableId: string | null, tableName?: string | null) => {
      store.getState().setSelectedTableId(tableId);
      props.onSelectedTableChange?.({ tableId, tableName: tableName ?? null });
    },
    [props.onSelectedTableChange, store]
  );
  const selectField = useCallback(
    (fieldId: string | null) => store.getState().setSelectedFieldId(fieldId),
    [store]
  );

  const value = useMemo<SchemaBuilderContextValue>(
    () => ({
      adapter: props.adapter,
      scope: props.scope,
      colorMode: props.colorMode,
      preferences: props.preferences,
      onPreferencesChange: props.onPreferencesChange,
      activeTab: props.activeTab,
      onActiveTabChange: props.onActiveTabChange,
      selectedTableId: props.selectedTableId,
      onSelectedTableChange: props.onSelectedTableChange,
      onNavigate: props.onNavigate,
      onInvalidate: props.onInvalidate,
      tabs: validatedTabs,
      store,
      setActiveTab,
      setPreferences,
      selectTable,
      selectField
    }),
    [
      props.activeTab,
      props.adapter,
      props.colorMode,
      props.onActiveTabChange,
      props.onInvalidate,
      props.onNavigate,
      props.onPreferencesChange,
      props.onSelectedTableChange,
      props.preferences,
      props.scope,
      props.selectedTableId,
      selectField,
      selectTable,
      setActiveTab,
      setPreferences,
      store,
      validatedTabs
    ]
  );

  return <SchemaBuilderContext.Provider value={value}>{children}</SchemaBuilderContext.Provider>;
}

export function useSchemaBuilder(): SchemaBuilderContextValue {
  const value = useContext(SchemaBuilderContext);
  if (!value) throw new Error('SchemaBuilderProvider is missing');
  return value;
}

export function useSchemaBuilderStore<T>(selector: (state: SchemaBuilderStoreState) => T): T {
  const { store } = useSchemaBuilder();
  return useStore(store, selector);
}

export { SchemaBuilderProvider, useSchemaBuilder, useSchemaBuilderStore } from './context';
export type { SchemaBuilderProviderProps, SchemaBuilderContextValue } from './context';
export { createSchemaBuilderStore, getSchemaBuilderScopeKey } from './store';
export type { SchemaBuilderStoreState } from './store';
export { schemaBuilderQueryKey, useSchemaBuilderQuery } from './query';
export { useSchemaBuilderMutation } from './mutation';
export type { SchemaBuilderMutationOptions } from './mutation';
export {
  DEFAULT_SCHEMA_BUILDER_PREFERENCES,
  defineSchemaBuilderAdapter
} from '../types';
export type {
  SchemaBuilderAdapter,
  SchemaBuilderCollection,
  SchemaBuilderColorMode,
  SchemaBuilderCoreCapabilities,
  SchemaBuilderCoreTabId,
  SchemaBuilderFeature,
  SchemaBuilderField,
  SchemaBuilderHostOptions,
  SchemaBuilderIndex,
  SchemaBuilderInvalidationEvent,
  SchemaBuilderNavigationTarget,
  SchemaBuilderOperation,
  SchemaBuilderOperationContext,
  SchemaBuilderPolicy,
  SchemaBuilderPreferences,
  SchemaBuilderRelationship,
  SchemaBuilderSchema,
  SchemaBuilderScope,
  SchemaBuilderSidebarSections,
  SchemaBuilderTab,
  SchemaBuilderTabRenderContext,
  SchemaBuilderTable,
  SchemaBuilderVariables
} from '../types';

'use client';

import {
  useMutation,
  useQueryClient,
  type UseMutationOptions,
  type UseMutationResult
} from '@tanstack/react-query';

import { useSchemaBuilder } from './context';
import { schemaBuilderQueryKey } from './query';
import type {
  SchemaBuilderAdapter,
  SchemaBuilderFeature,
  SchemaBuilderOperation,
  SchemaBuilderOperationContext,
  SchemaBuilderVariables
} from '../types';

type FeatureOperation<TFeature extends SchemaBuilderFeature> = Extract<
  keyof SchemaBuilderAdapter[TFeature],
  string
>;

export type SchemaBuilderMutationOptions<TData, TVariables, TContext = unknown> =
  UseMutationOptions<TData, Error, TVariables, TContext> & {
    /** Result fields required by generated GraphQL adapters for this mutation. */
    selection?: SchemaBuilderOperationContext['selection'];
  };

export function useSchemaBuilderMutation<
  TData = unknown,
  TVariables extends SchemaBuilderVariables = SchemaBuilderVariables,
  TFeature extends SchemaBuilderFeature = SchemaBuilderFeature
>(
  feature: TFeature,
  operation: FeatureOperation<TFeature>,
  options: SchemaBuilderMutationOptions<TData, TVariables> = {}
): UseMutationResult<TData, Error, TVariables> {
  const { adapter, scope, onInvalidate } = useSchemaBuilder();
  const queryClient = useQueryClient();
  const capability = adapter[feature] as unknown as Record<string, SchemaBuilderOperation>;
  const operationFn = capability[operation];

  if (typeof operationFn !== 'function') {
    throw new Error(`SchemaBuilder adapter is missing ${feature}.${operation}`);
  }

  const { selection, ...mutationOptions } = options;
  const hostOnSuccess = mutationOptions.onSuccess;

  return useMutation({
    ...mutationOptions,
    mutationFn: (variables) =>
      operationFn(variables, { scope, selection }) as Promise<TData>,
    onSuccess: async (data, variables, onMutateResult, context) => {
      await queryClient.invalidateQueries({
        queryKey: schemaBuilderQueryKey(scope, 'core', '').slice(0, 4)
      });
      onInvalidate?.({ scope, feature, operation });
      await hostOnSuccess?.(data, variables, onMutateResult, context);
    }
  });
}

'use client';

import {
  useQuery,
  type UseQueryOptions,
  type UseQueryResult
} from '@tanstack/react-query';

import { useSchemaBuilder } from './context';
import type {
  SchemaBuilderAdapter,
  SchemaBuilderFeature,
  SchemaBuilderOperation,
  SchemaBuilderVariables
} from '../types';

type FeatureOperation<TFeature extends SchemaBuilderFeature> = Extract<
  keyof SchemaBuilderAdapter[TFeature],
  string
>;

export function schemaBuilderQueryKey(
  scope: { orgId: string; databaseId: string; userId?: string | null },
  feature: SchemaBuilderFeature,
  operation: string,
  variables: SchemaBuilderVariables = {}
) {
  return [
    '@constructive-io/schema-builder',
    scope.orgId,
    scope.databaseId,
    scope.userId ?? null,
    feature,
    operation,
    variables
  ] as const;
}

export function useSchemaBuilderQuery<
  TData = unknown,
  TFeature extends SchemaBuilderFeature = SchemaBuilderFeature
>(
  feature: TFeature,
  operation: FeatureOperation<TFeature>,
  variables: SchemaBuilderVariables = {},
  options: Omit<
    UseQueryOptions<TData, Error, TData, ReturnType<typeof schemaBuilderQueryKey>>,
    'queryKey' | 'queryFn'
  > = {}
): UseQueryResult<TData, Error> {
  const { adapter, scope } = useSchemaBuilder();
  const capability = adapter[feature] as unknown as Record<string, SchemaBuilderOperation>;
  const operationFn = capability[operation];

  if (typeof operationFn !== 'function') {
    throw new Error(`SchemaBuilder adapter is missing ${feature}.${operation}`);
  }

  return useQuery({
    ...options,
    queryKey: schemaBuilderQueryKey(scope, feature, operation, variables),
    queryFn: ({ signal }) => operationFn(variables, { scope, signal }) as Promise<TData>
  });
}

import { createStore, type StoreApi } from 'zustand/vanilla';

import type { SchemaBuilderPreferences, SchemaBuilderScope } from '../types';

export interface SchemaBuilderStoreState {
  scopeKey: string;
  selectedTableId: string | null;
  selectedFieldId: string | null;
  currentDatabaseApi: unknown | null;
  preferences: SchemaBuilderPreferences;
  activeTab: string;
  setSelectedTableId: (tableId: string | null) => void;
  setSelectedFieldId: (fieldId: string | null) => void;
  setCurrentDatabaseApi: (api: unknown | null) => void;
  replacePreferences: (preferences: SchemaBuilderPreferences) => void;
  replaceActiveTab: (tabId: string) => void;
  replaceScope: (scope: SchemaBuilderScope) => void;
}

export function getSchemaBuilderScopeKey(scope: SchemaBuilderScope): string {
  return [scope.orgId, scope.databaseId, scope.userId ?? 'anonymous'].join(':');
}

export function createSchemaBuilderStore(
  scope: SchemaBuilderScope,
  preferences: SchemaBuilderPreferences,
  activeTab: string,
  selectedTableId: string | null = null
): StoreApi<SchemaBuilderStoreState> {
  return createStore<SchemaBuilderStoreState>((set, get) => ({
    scopeKey: getSchemaBuilderScopeKey(scope),
    selectedTableId,
    selectedFieldId: null,
    currentDatabaseApi: null,
    preferences,
    activeTab,
    setSelectedTableId: (selectedTableId) =>
      set({
        selectedTableId,
        selectedFieldId: selectedTableId === get().selectedTableId ? get().selectedFieldId : null
      }),
    setSelectedFieldId: (selectedFieldId) => set({ selectedFieldId }),
    setCurrentDatabaseApi: (currentDatabaseApi) => set({ currentDatabaseApi }),
    replacePreferences: (nextPreferences) => set({ preferences: nextPreferences }),
    replaceActiveTab: (nextActiveTab) => set({ activeTab: nextActiveTab }),
    replaceScope: (nextScope) => {
      const nextScopeKey = getSchemaBuilderScopeKey(nextScope);
      if (nextScopeKey === get().scopeKey) return;

      set({
        scopeKey: nextScopeKey,
        selectedTableId: null,
        selectedFieldId: null,
        currentDatabaseApi: null
      });
    }
  }));
}

