// =============================================================================
// Transformer Functions
// =============================================================================

/**
 * Transform SDK Field to DatabaseFieldNode
 * Handles the SDK's quirky types (chk can be {} | boolean | null)
 */
export function transformField(f: Field): DatabaseFieldNode {
	return {
		id: f.id ?? '',
		name: f.name ?? '',
		// type is now a structured FieldType object; reduce to its type-name string.
		// defaultValue is a structured FieldDefault object; stringify for downstream
		// display (the write path re-parses it via toFieldDefault).
		type: fieldTypeToTypeName(f.type),
		chk: typeof f.chk === 'boolean' ? f.chk : null,
		chkExpr: typeof f.chkExpr === 'string' ? f.chkExpr : null,
		defaultValue: typeof f.defaultValue === 'string' ? f.defaultValue : f.defaultValue != null ? JSON.stringify(f.defaultValue) : null,
		description: f.description ?? null,
		fieldOrder: f.fieldOrder ?? null,
		isRequired: f.isRequired ?? null,
		label: f.label ?? null,
		max: f.max ?? null,
		min: f.min ?? null,
		regexp: f.regexp ?? null,
		smartTags: (f.smartTags as Record<string, unknown>) ?? null,
	};
}

/**
 * Transform SDK Table to DatabaseTableNode (without fields - compose separately)
 */
export function transformTable(t: Table, fields: DatabaseFieldNode[] = []): DatabaseTableNode {
	return {
		id: t.id ?? '',
		name: t.name ?? '',
		label: t.label ?? null,
		description: t.description ?? null,
		pluralName: t.pluralName ?? null,
		singularName: t.singularName ?? null,
		smartTags: (t.smartTags as Record<string, unknown>) ?? null,
		timestamps: t.timestamps ?? null,
		databaseId: t.databaseId ?? '',
		schemaId: t.schemaId ?? '',
		category: (t.category as string) ?? null,
		fields: { totalCount: fields.length, nodes: fields },
	};
}

// =============================================================================
// Map Builder Utilities
// =============================================================================

/**
 * Group fields by tableId into a Map for efficient lookup
 */
export function buildFieldsByTableMap(fields: Field[]): Map<string, DatabaseFieldNode[]> {
	const map = new Map<string, DatabaseFieldNode[]>();
	for (const f of fields) {
		if (!f.tableId) continue;
		const existing = map.get(f.tableId) ?? [];
		existing.push(transformField(f));
		map.set(f.tableId, existing);
	}
	return map;
}

/**
 * Group tables by databaseId into a Map for efficient lookup
 */
export function buildTablesByDatabaseMap(
	tables: Table[],
	fieldsByTable: Map<string, DatabaseFieldNode[]>
): Map<string, DatabaseTableNode[]> {
	const map = new Map<string, DatabaseTableNode[]>();
	for (const t of tables) {
		if (!t.databaseId) continue;
		const existing = map.get(t.databaseId) ?? [];
		const fields = fieldsByTable.get(t.id ?? '') ?? [];
		existing.push(transformTable(t, fields));
		map.set(t.databaseId, existing);
	}
	return map;
}

/**
 * Extract non-null IDs from an array of objects with id property
 */
export function extractIds<T extends { id?: string | null }>(items: T[]): string[] {
	return items.map((item) => item.id).filter((id): id is string => !!id);
}

/**
 * Extract unique non-null values from an array by key
 */
export function extractUniqueIds<T extends Record<string, unknown>>(items: T[], key: keyof T): string[] {
	const values: string[] = [];
	for (const item of items) {
		const value = item[key];
		if (typeof value === 'string' && value) {
			values.push(value);
		}
	}
	return [...new Set(values)];
}

import type { QueryClient, QueryKey } from '@tanstack/react-query';

import { isDashboardCacheScopeKey } from '../../dashboard/dashboard-query-keys';

import { blueprintTemplateKeys } from '@/components/schema-builder/compat/modules-sdk';
import { apiKeys, domainKeys, schemaKeys, siteKeys } from '@/components/schema-builder/compat/schema-builder-sdk';
import { databasePoliciesQueryKeys } from '../policies/use-database-policies';
import { accessibleDatabasesQueryKeys } from '../use-accessible-databases';
import { databaseConstraintsQueryKeys } from '../use-database-constraints';
import { databaseTablesQueryKeys } from '../use-database-tables';
import { userDatabasesQueryKeys } from '../use-user-databases';

const invalidateQueryKey = (queryClient: QueryClient, queryKey: QueryKey) =>
	queryClient.invalidateQueries({ queryKey });

function invalidateDashboardQueries(queryClient: QueryClient, databaseId?: string | null) {
	const matchesDashboard = (queryKey: readonly unknown[]): boolean => {
		const [root, scope] = queryKey as unknown[];
		if (root !== 'sheets') return false;
		if (!databaseId) return true;
		return isDashboardCacheScopeKey(scope) && scope.databaseId === databaseId;
	};

	// 1. REMOVE schema queries (meta + relations) — force fresh fetch, no stale data.
	//    This prevents stale-while-revalidate from showing wrong columns/tables after schema changes.
	queryClient.removeQueries({
		predicate: (query) => {
			if (!matchesDashboard(query.queryKey)) return false;
			const type = query.queryKey[2];
			return type === 'meta' || type === 'relations';
		},
	});

	// 2. INVALIDATE data queries (rows, counts) — stale-while-revalidate is fine for row data
	return queryClient.invalidateQueries({
		predicate: (query) => matchesDashboard(query.queryKey),
	});
}

export async function invalidateDatabaseEntities(queryClient: QueryClient, databaseId?: string | null) {
	const tasks: Array<Promise<unknown>> = [];
	tasks.push(invalidateQueryKey(queryClient, ['@constructive-io/schema-builder']));

	if (databaseId) {
		tasks.push(invalidateQueryKey(queryClient, databaseTablesQueryKeys.byDatabase(databaseId)));
		tasks.push(invalidateQueryKey(queryClient, databasePoliciesQueryKeys.byDatabase(databaseId)));
		tasks.push(invalidateQueryKey(queryClient, domainKeys.lists()));
		// These queries use the table id or other params; the prefix ensures all cached tables refresh.
		tasks.push(invalidateQueryKey(queryClient, ['database-table']));
	}

	// Dashboard/CRM queries (secondary auth /data). These are scoped by { databaseId, endpoint }.
	tasks.push(invalidateDashboardQueries(queryClient, databaseId));

	// Global database context
	// CRITICAL: Must invalidate BOTH split query keys since useSchemaBuilderSelectors uses them
	tasks.push(invalidateQueryKey(queryClient, userDatabasesQueryKeys.all));
	tasks.push(invalidateQueryKey(queryClient, accessibleDatabasesQueryKeys.all));
	tasks.push(invalidateQueryKey(queryClient, databaseConstraintsQueryKeys.all));

	// SDK query keys (for hooks using generated SDK)
	tasks.push(invalidateQueryKey(queryClient, apiKeys.all));
	tasks.push(invalidateQueryKey(queryClient, schemaKeys.all));
	tasks.push(invalidateQueryKey(queryClient, siteKeys.all));
	tasks.push(invalidateQueryKey(queryClient, blueprintTemplateKeys.all));

	// Hand-written wrapper query keys (for hooks using fetchXxxQuery with custom keys)
	tasks.push(invalidateQueryKey(queryClient, databaseTablesQueryKeys.all));
	tasks.push(invalidateQueryKey(queryClient, databasePoliciesQueryKeys.all));
	tasks.push(invalidateQueryKey(queryClient, domainKeys.all));

	await Promise.allSettled(tasks);
}

/**
 * Parse list-like scalar values emitted by schema-builder ORM fields.
 *
 * Codegen v4 ORM types expose list columns (e.g. uuid[]) as `string | null`.
 * At runtime this value may be:
 * - a real array (already parsed)
 * - JSON array string: ["a","b"]
 * - PostgreSQL array literal: {a,b} or {"a","b"}
 * - single scalar string: a
 */
export function parseListField(value: unknown): string[] {
	if (value == null) return [];

	if (Array.isArray(value)) {
		return value
			.filter((item): item is string => typeof item === 'string')
			.map((item) => item.trim())
			.filter(Boolean);
	}

	if (typeof value !== 'string') return [];

	const input = value.trim();
	if (!input) return [];

	// JSON array payload
	if (input.startsWith('[') && input.endsWith(']')) {
		try {
			const parsed = JSON.parse(input);
			if (Array.isArray(parsed)) {
				return parsed
					.filter((item): item is string => typeof item === 'string')
					.map((item) => item.trim())
					.filter(Boolean);
			}
		} catch {
			// Fall through to additional formats.
		}
	}

	// PostgreSQL array literal payload: {a,b} or {"a","b"}
	if (input.startsWith('{') && input.endsWith('}')) {
		const inner = input.slice(1, -1).trim();
		if (!inner) return [];
		return splitPgArrayLiteral(inner)
			.map(stripPgArrayItemQuotes)
			.map((item) => item.trim())
			.filter((item) => item.length > 0 && item.toUpperCase() !== 'NULL');
	}

	// Fallback: treat as single scalar value.
	return [input];
}

function splitPgArrayLiteral(input: string): string[] {
	const items: string[] = [];
	let current = '';
	let inQuotes = false;
	let escaped = false;

	for (let i = 0; i < input.length; i += 1) {
		const char = input[i];

		if (escaped) {
			current += char;
			escaped = false;
			continue;
		}

		if (char === '\\') {
			escaped = true;
			continue;
		}

		if (char === '"') {
			inQuotes = !inQuotes;
			current += char;
			continue;
		}

		if (char === ',' && !inQuotes) {
			items.push(current);
			current = '';
			continue;
		}

		current += char;
	}

	items.push(current);
	return items;
}

function stripPgArrayItemQuotes(item: string): string {
	if (item.startsWith('"') && item.endsWith('"') && item.length >= 2) {
		return item.slice(1, -1).replace(/\\"/g, '"');
	}
	return item;
}

/**
 * Hook for fetching database policies
 * Tier 4 wrapper: Uses SDK hooks + composition
 */
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useSchemaBuilderSdkClient,
	useSchemaBuilderRuntime,
} from '@/components/schema-builder/compat/block-config';

import { fieldTypeToTypeName } from '../transformers/field-type-mapper';

interface FieldNode {
	id: string;
	name: string;
	type: string;
	fieldOrder: number | null;
	smartTags: unknown;
}

interface SchemaNode {
	id: string;
	schemaName: string;
}

interface PolicyNode {
	createdAt: string | null;
	data: unknown;
	disabled: boolean | null;
	id: string;
	name: string | null;
	permissive: boolean | null;
	privilege: string | null;
	granteeName: string | null;
	policyType: string | null;
	updatedAt: string | null;
}

// Policy types auto-injected by the backend as companions to user-selected
// policies (e.g. AuthzNotReadOnly alongside AuthzEntityMembership). Users don't
// create or manage these, so they're filtered out of all UI reads.
const BACKEND_MANAGED_POLICY_TYPES = new Set(['AuthzNotReadOnly']);

type TableCategory = string | null;

export type DatabasePolicy = PolicyNode;
export type TableField = FieldNode;

export type { TableCategory, SchemaNode };

export interface PolicyTableData {
	id: string;
	name: string;
	useRls: boolean;
	policies: DatabasePolicy[];
	fields: TableField[];
	schema: SchemaNode | null;
	category: TableCategory;
}

export const databasePoliciesQueryKeys = {
	all: ['database-policies'] as const,
	byDatabase: (databaseId: string) => ['database-policies', databaseId] as const,
};

export interface UseDatabasePoliciesOptions {
	enabled?: boolean;
}

export function useDatabasePolicies(databaseId: string, options: UseDatabasePoliciesOptions = {}) {
	const isEnabled = options.enabled !== false && Boolean(databaseId);
	const { scope } = useSchemaBuilderRuntime();
	const { fetchFieldsQuery, fetchPoliciesQuery, fetchSchemasQuery, fetchTablesQuery } = useSchemaBuilderSdkClient();

	return useQuery<PolicyTableData[]>({
		queryKey: schemaBuilderQueryKey(scope, 'core', 'databasePolicies', { databaseId }),
		queryFn: async (): Promise<PolicyTableData[]> => {
			// Step 1: Fetch tables for this database
			const tablesResult = await fetchTablesQuery({
				selection: {
					fields: { id: true, name: true, useRls: true, category: true, schemaId: true },
					where: { databaseId: { equalTo: databaseId } },
					orderBy: ['NAME_ASC'],
				},
			});

			const tables = tablesResult.tables?.nodes ?? [];
			if (tables.length === 0) {
				return [];
			}

			// Build table data map
			const tableIds = tables.map((t) => t.id).filter((id): id is string => !!id);
			const schemaIds = [...new Set(tables.map((t) => t.schemaId).filter((id): id is string => !!id))];

			// Step 2: Fetch schemas, fields, and policies in parallel
			const [schemasResult, fieldsResult, policiesResult] = await Promise.all([
				schemaIds.length > 0
					? fetchSchemasQuery({ selection: { fields: { id: true, schemaName: true }, where: { id: { in: schemaIds } } } })
					: Promise.resolve({ schemas: { nodes: [] } }),
				tableIds.length > 0
					? fetchFieldsQuery({ selection: { fields: { id: true, name: true, type: true, fieldOrder: true, smartTags: true, tableId: true }, where: { tableId: { in: tableIds } } } })
					: Promise.resolve({ fields: { nodes: [] } }),
				tableIds.length > 0
					? fetchPoliciesQuery({
							selection: {
								fields: { id: true, name: true, granteeName: true, privilege: true, permissive: true, disabled: true, policyType: true, data: true, createdAt: true, updatedAt: true, tableId: true },
								where: { tableId: { in: tableIds } },
								orderBy: ['CREATED_AT_DESC'],
							},
						})
					: Promise.resolve({ policies: { nodes: [] } }),
			]);

			// Build lookup maps
			const schemaMap = new Map<string, SchemaNode>();
			for (const schema of schemasResult.schemas?.nodes ?? []) {
				if (schema.id) {
					schemaMap.set(schema.id, {
						id: schema.id,
						schemaName: schema.schemaName ?? '',
					});
				}
			}

			const fieldsByTable = new Map<string, FieldNode[]>();
			for (const field of fieldsResult.fields?.nodes ?? []) {
				if (field.tableId) {
					const existing = fieldsByTable.get(field.tableId) ?? [];
					existing.push({
						id: field.id ?? '',
						name: field.name ?? '',
						// type is now a structured FieldType object; reduce to its type-name string.
						type: fieldTypeToTypeName(field.type),
						fieldOrder: field.fieldOrder ?? null,
						smartTags: field.smartTags ?? null,
					});
					fieldsByTable.set(field.tableId, existing);
				}
			}

			const policiesByTable = new Map<string, PolicyNode[]>();
			for (const policy of policiesResult.policies?.nodes ?? []) {
				if (!policy.tableId) continue;
				if (policy.policyType && BACKEND_MANAGED_POLICY_TYPES.has(policy.policyType)) continue;
				const existing = policiesByTable.get(policy.tableId) ?? [];
				existing.push({
					id: policy.id ?? '',
					name: policy.name ?? null,
					granteeName: policy.granteeName ?? null,
					privilege: policy.privilege ?? null,
					permissive: policy.permissive ?? null,
					disabled: policy.disabled ?? null,
					policyType: policy.policyType ?? null,
					data: policy.data ?? null,
					createdAt: policy.createdAt ?? null,
					updatedAt: policy.updatedAt ?? null,
				});
				policiesByTable.set(policy.tableId, existing);
			}

			// Step 3: Build result
			return tables.map((table): PolicyTableData => ({
				id: table.id ?? '',
				name: table.name ?? '',
				useRls: table.useRls ?? false,
				policies: policiesByTable.get(table.id ?? '') ?? [],
				fields: fieldsByTable.get(table.id ?? '') ?? [],
				schema: table.schemaId ? schemaMap.get(table.schemaId) ?? null : null,
				category: (table.category as TableCategory) ?? null,
			}));
		},
		enabled: isEnabled,
		staleTime: 5 * 60 * 1000,
		refetchOnMount: isEnabled,
		refetchOnWindowFocus: false,
		refetchOnReconnect: false,
	});
}

import { nodes } from 'pg-ast';

/**
 * Generate AST for decimal precision and scale constraints
 * @param precision - Maximum total number of digits
 * @param scale - Maximum number of decimal places
 * @returns PostgreSQL AST for the precision/scale constraint
 */
export function generateDecimalPrecisionScaleAST(precision?: number, scale?: number) {
	const constraints = [];

	// Precision constraint: max total digits (excluding decimal point)
	if (precision !== undefined && precision > 0) {
		constraints.push(
			nodes.aExpr({
				kind: 'AEXPR_OP',
				name: [nodes.string({ sval: '<=' })],
				lexpr: nodes.funcCall({
					funcname: [nodes.string({ sval: 'length' })],
					args: [
						nodes.funcCall({
							funcname: [nodes.string({ sval: 'replace' })],
							args: [
								nodes.typeCast({
									arg: nodes.columnRef({ fields: [nodes.string({ sval: 'value' })] }),
									typeName: {
										names: [nodes.string({ sval: 'text' })],
									},
								}),
								nodes.aConst({ sval: { sval: '.' } }),
								nodes.aConst({ sval: { sval: '' } }),
							],
						}),
					],
				}),
				rexpr: nodes.aConst({ ival: { ival: precision } }),
			})
		);
	}

	// Scale constraint: max decimal places
	if (scale !== undefined && scale > 0) {
		constraints.push(
			nodes.aExpr({
				kind: 'AEXPR_OP',
				name: [nodes.string({ sval: '<=' })],
				lexpr: nodes.funcCall({
					funcname: [nodes.string({ sval: 'length' })],
					args: [
						nodes.funcCall({
							funcname: [nodes.string({ sval: 'coalesce' })],
							args: [
								nodes.funcCall({
									funcname: [nodes.string({ sval: 'split_part' })],
									args: [
										nodes.typeCast({
											arg: nodes.columnRef({ fields: [nodes.string({ sval: 'value' })] }),
											typeName: {
												names: [nodes.string({ sval: 'text' })],
											},
										}),
										nodes.aConst({ sval: { sval: '.' } }),
										nodes.aConst({ ival: { ival: 2 } }),
									],
								}),
								nodes.aConst({ sval: { sval: '' } }),
							],
						}),
					],
				}),
				rexpr: nodes.aConst({ ival: { ival: scale } }),
			})
		);
	}

	// Return null if no constraints
	if (constraints.length === 0) {
		return null;
	}

	// Return single constraint or combine with AND
	if (constraints.length === 1) {
		return constraints[0];
	}

	return nodes.boolExpr({
		boolop: 'AND_EXPR',
		args: constraints,
	});
}

/**
 * Parse precision and scale from a check constraint AST
 * Based on the actual generated AST structure from pg-ast
 * @param chk - The check constraint AST from the database
 * @returns Object with precision and scale if found, otherwise undefined values
 */
export function parseDecimalConstraintsFromAST(chk: any): { precision?: number; scale?: number } {
	if (!chk) {
		return {};
	}

	const result: { precision?: number; scale?: number } = {};

	try {
		// The AST structure is: { BoolExpr: { boolop: 'AND_EXPR', args: [...] } }
		const boolExpr = chk.BoolExpr;
		if (!boolExpr || boolExpr.boolop !== 'AND_EXPR' || !Array.isArray(boolExpr.args)) {
			// Single constraint case (not wrapped in BoolExpr)
			parseConstraintExpression(chk, result);
			return result;
		}

		// Parse each constraint in the AND expression
		for (const arg of boolExpr.args) {
			parseConstraintExpression(arg, result);
		}
	} catch (error) {
		console.warn('Failed to parse decimal constraints from AST:', error);
	}

	return result;
}

/**
 * Parse a single constraint expression (A_Expr)
 */
function parseConstraintExpression(node: any, result: { precision?: number; scale?: number }): void {
	const aExpr = node.A_Expr;
	if (!aExpr) return;

	// Structure: A_Expr { lexpr: FuncCall, rexpr: A_Const }
	const funcCall = aExpr.lexpr?.FuncCall;
	const rexprConst = aExpr.rexpr?.A_Const;

	if (!funcCall || !rexprConst) return;

	// Get the outer function name (should be "length")
	const outerFuncName = funcCall.funcname?.[0]?.String?.sval;
	if (outerFuncName !== 'length') return;

	// Get the inner function call
	const innerFuncCall = funcCall.args?.[0]?.FuncCall;
	if (!innerFuncCall) return;

	const innerFuncName = innerFuncCall.funcname?.[0]?.String?.sval;

	// Get the constraint value (ival)
	const constraintValue = rexprConst.ival?.ival;
	if (typeof constraintValue !== 'number') return;

	// Determine if this is precision or scale based on inner function
	if (innerFuncName === 'replace') {
		// Precision: length(replace(value::text, '.', '')) <= N
		result.precision = constraintValue;
	} else if (innerFuncName === 'coalesce') {
		// Scale: length(coalesce(split_part(value::text, '.', 2), '')) <= N
		result.scale = constraintValue;
	}
}

import type { CellType } from '../../../../types/cell-types';
import type { FieldConstraints, FieldDefinition } from '../../../../schema';
import { getFieldTypeInfo } from '../../../../schema';

/**
 * Database field data used for constraint mapping.
 * Compatible with both DatabaseFieldNode and FieldPatch types.
 */
export interface FieldConstraintData {
	min?: number | null;
	max?: number | null;
	regexp?: string | null;
	chk?: unknown;
	chkExpr?: unknown;
}

import { generateDecimalPrecisionScaleAST, parseDecimalConstraintsFromAST } from './decimal-constraints';

/**
 * Convert CellType to backend type string for GraphQL mutations
 */
export function cellTypeToBackendType(cellType: CellType): string {
	const typeMap: Record<CellType, string> = {
		// Basic types
		text: 'text',
		textarea: 'text',
		integer: 'integer',
		smallint: 'smallint',
		number: 'numeric',
		decimal: 'numeric',
		boolean: 'boolean',

		// Date/time types
		date: 'date',
		datetime: 'timestamp',
		timestamptz: 'timestamptz',
		time: 'time',
		interval: 'interval',

		// JSON types
		json: 'json',
		jsonb: 'jsonb',

		// Special types
		uuid: 'uuid',
		inet: 'inet',
		geometry: 'geometry',
		'geometry-point': 'point',
		'geometry-collection': 'geometry',
		tsvector: 'tsvector',
		citext: 'citext',
		bpchar: 'bpchar',
		bit: 'bit',

		// Enhanced types - some use PostgreSQL DOMAINs, others map to base types
		// DOMAINs: email (citext), url (text), origin (text) - defined in pgpm-types extension
		email: 'email', // PostgreSQL DOMAIN over citext
		url: 'url', // PostgreSQL DOMAIN over text
		phone: 'text', // No DOMAIN available, uses base type
		currency: 'numeric',
		percentage: 'numeric',
		color: 'text',
		rating: 'integer',
		tags: 'text',

		// Media types - use PostgreSQL DOMAINs where available
		// DOMAINs: image (jsonb), upload (jsonb) - defined in pgpm-types extension
		// These DOMAINs enforce { url, mime } structure with URL validation
		image: 'image', // PostgreSQL DOMAIN over jsonb
		file: 'text', // No DOMAIN available, uses base type
		video: 'text', // No DOMAIN available, uses base type
		audio: 'text', // No DOMAIN available, uses base type
		upload: 'upload', // PostgreSQL DOMAIN over jsonb

		// Array types
		'text-array': 'text[]',
		'integer-array': 'integer[]',
		'number-array': 'numeric[]',
		'uuid-array': 'uuid[]',
		'date-array': 'date[]',
		array: 'text[]',

		// Special cases
		relation: 'uuid', // Relations are typically UUID foreign keys
		origin: 'text',
		toggle: 'boolean',

		// Fallback
		unknown: 'text',
	};

	return typeMap[cellType] || 'text';
}

type FieldConstraintMapping = {
	min?: number;
	max?: number;
	regexp?: string;
	chk?: unknown;
	chkExpr?: unknown;
	smartTags?: unknown;
};

/**
 * Determines if a field type needs a pgAlias smart tag
 * (when frontend type differs from backend type semantically)
 *
 * This is critical for preserving the original frontend type when:
 * - Enhanced types map to base types (e.g., 'phone' → 'text')
 * - Media types without DOMAINs map to text (e.g., 'file' → 'text', 'video' → 'text')
 * - Numeric variants map to numeric (e.g., 'number' → 'numeric', 'currency' → 'numeric')
 *
 * Types that use PostgreSQL DOMAINs do NOT need pgAlias because _meta returns the
 * domain name directly (e.g., 'upload', 'image', 'email', 'url').
 *
 * Without the pgAlias, the original type is lost after refetch from the server.
 */
function needsPgAlias(cellType: CellType): boolean {
	const backendType = cellTypeToBackendType(cellType);

	// Types that need pgAlias because they map to a different backend type
	// NOTE: Types using PostgreSQL DOMAINs are EXCLUDED - _meta returns domain name directly
	// DOMAINs available: upload, image, email, url, origin (defined in pgpm-types extension)
	const typesNeedingAlias: CellType[] = [
		// Enhanced text types that map to 'text' (no DOMAIN available)
		// NOTE: 'email' and 'url' now use DOMAINs, so they're excluded
		'phone',
		'color',
		'tags',

		// Media types that map to 'text' (no DOMAIN available)
		// NOTE: 'image' and 'upload' now use DOMAINs, so they're excluded
		'file',
		'video',
		'audio',

		// Numeric types that map to 'numeric'
		'number',
		'currency',
		'percentage',

		// Geometry types that lose specificity
		'geometry-collection', // maps to 'geometry', would come back as 'geometry'

		// Array types that lose specificity
		'array', // maps to 'text[]', would come back as 'text-array'

		// Other special types
		'rating', // maps to 'integer'
	];

	if (typesNeedingAlias.includes(cellType)) {
		return true;
	}

	// Fallback: check if cellType differs from backendType (defensive)
	// This catches any types we might have missed
	if (cellType !== backendType && cellType !== 'unknown') {
		// Some types legitimately map to different backend types without needing alias
		// e.g., 'decimal' → 'numeric', 'datetime' → 'timestamp', 'toggle' → 'boolean'
		const legitimateMappings: Partial<Record<CellType, string[]>> = {
			// These types map to different backend types but round-trip correctly
			// because mapBackendTypeToCellType restores them properly
			decimal: ['numeric'], // numeric → decimal
			datetime: ['timestamp'], // timestamp → datetime
			timestamptz: ['timestamptz'],
			'geometry-point': ['point'], // point → geometry-point

			// These are not user-selectable in the field type registry
			// so they won't be created via UI, only from existing DB schemas
			toggle: ['boolean'],
			textarea: ['text'],
			relation: ['uuid'],
			origin: ['text'],

			// Array types - these round-trip correctly via isArray flag
			'text-array': ['text[]'],
			'integer-array': ['integer[]'],
			'number-array': ['numeric[]'],
			'uuid-array': ['uuid[]'],
			'date-array': ['date[]'],
			// Note: 'array' is NOT in this list because it needs pgAlias to preserve as 'array' vs 'text-array'
		};

		const legitimate = legitimateMappings[cellType];
		if (!legitimate || !legitimate.includes(backendType)) {
			// This type maps to a different backend type and isn't in our known mappings
			// It might need an alias - log for debugging but don't automatically add
			console.warn(`Type '${cellType}' maps to '${backendType}' - consider adding to needsPgAlias if type is lost on refetch`);
		}
	}

	return false;
}

/**
 * Maps field constraints to FieldPatch properties based on type configurability
 */
export function mapConstraintsToFieldPatch(
	field: Omit<FieldDefinition, 'id'> | FieldDefinition,
): FieldConstraintMapping {
	const typeInfo = getFieldTypeInfo(field.type);
	if (!typeInfo) {
		return {};
	}

	const result: FieldConstraintMapping = {};
	const { constraints } = field;

	// Always preserve smart tags (Form Builder uses smartTags for UI hints like ui/enum/order/group/help)
	if (field.metadata?.smartTags && Object.keys(field.metadata.smartTags).length > 0) {
		result.smartTags = { ...field.metadata.smartTags };
	}

	// Handle length constraints (for text types)
	if (typeInfo.configurable.length) {
		if (constraints.minLength != null) result.min = constraints.minLength;
		if (constraints.maxLength != null) result.max = constraints.maxLength;
	}

	// Handle range constraints (for numeric types)
	if (typeInfo.configurable.range) {
		if (constraints.minValue != null) result.min = constraints.minValue;
		if (constraints.maxValue != null) result.max = constraints.maxValue;
	}

	// Handle pattern constraints (for text types with regex validation)
	if (typeInfo.configurable.pattern) {
		if (constraints.pattern != null) result.regexp = constraints.pattern;
	}

	// Handle precision and scale constraints (for decimal-like types)
	if (typeInfo.configurable.precision || typeInfo.configurable.scale) {
		const constraintAST = generateDecimalPrecisionScaleAST(constraints.precision, constraints.scale);
		result.chk = constraintAST;
	}

	// Handle generic check expressions (forward-compatible constraint surface)
	if (constraints.checkExpression) {
		result.chkExpr = constraints.checkExpression;
	}

	// Handle smart tags for type aliases - preserve existing smart tags
	if (needsPgAlias(field.type)) {
		const existingSmartTags =
			typeof result.smartTags === 'object' && result.smartTags !== null && !Array.isArray(result.smartTags)
				? (result.smartTags as Record<string, unknown>)
				: {};
		result.smartTags = {
			...existingSmartTags,
			pgAlias: field.type,
		};
	}

	return result;
}

/**
 * Maps backend field constraints to frontend FieldConstraints based on type configurability
 * This is the inverse operation of mapConstraintsToFieldPatch
 */
export function mapDbFieldToConstraints(dbField: FieldConstraintData, cellType: CellType): Partial<FieldConstraints> {
	const typeInfo = getFieldTypeInfo(cellType);
	if (!typeInfo) {
		return {};
	}

	const result: Partial<FieldConstraints> = {};

	// Handle length constraints (for text types)
	if (typeInfo.configurable.length) {
		result.minLength = dbField.min ?? undefined;
		result.maxLength = dbField.max ?? undefined;
	}

	// Handle range constraints (for numeric types)
	if (typeInfo.configurable.range) {
		result.minValue = dbField.min ?? undefined;
		result.maxValue = dbField.max ?? undefined;
	}

	// Handle pattern constraints (for text types with regex validation)
	if (typeInfo.configurable.pattern) {
		result.pattern = dbField.regexp ?? undefined;
	}

	// Handle precision and scale constraints (for decimal-like types)
	if ((typeInfo.configurable.precision || typeInfo.configurable.scale) && dbField.chk) {
		const { precision, scale } = parseDecimalConstraintsFromAST(dbField.chk);
		if (precision !== undefined) {
			result.precision = precision;
		}
		if (scale !== undefined) {
			result.scale = scale;
		}
	}

	// Handle check expressions (generic constraint)
	if (dbField.chkExpr) {
		result.checkExpression = String(dbField.chkExpr);
	}

	return result;
}

/**
 * Field type / default-value mappers.
 *
 * Backend breaking change: metaschema `field.type` and `field.default_value`
 * are now JSONB **objects** (validated by ast_validate.validate_field_type /
 * validate_field_default + the `_00001_ensure_no_sql_injection` trigger which
 * requires `jsonb_typeof = 'object'`). Sending bare strings raises
 * `BAD_FIELD_INPUT`. These helpers convert the dashboard's internal
 * type-name / default-expression strings into the structured objects the
 * backend expects, and back again on read.
 *
 * The canonical FieldType / FieldDefault types live in `node-type-registry`,
 * but are not exported by the version pinned here (^0.33.1). We mirror the
 * verified ground-truth shapes locally to stay self-contained; keep these in
 * sync with node-type-registry/src/types.ts.
 */

/** Mirror of node-type-registry FieldType (verified against ast_validate.validate_field_type). */
export interface FieldType {
	name: string;
	schema?: string;
	args?: (string | number | boolean)[];
	/** 0..6 */
	array_dimensions?: number;
	range?: string[];
}

/**
 * Mirror of node-type-registry FieldDefault — discriminated union with EXACTLY
 * one discriminant key (verified against ast_validate.validate_field_default).
 */
export type FieldDefault =
	| { value: string | number | boolean | null | unknown[] | Record<string, unknown>; cast?: FieldType }
	| { function: string; schema?: string; args?: (FieldDefault | string | number | boolean | null)[]; cast?: FieldType }
	| { operator: '+' | '-'; left: FieldDefault; right: FieldDefault }
	| { sql_keyword: string };

// SQL keyword allowlist — mirrors v_allowed_sql_keywords in validate_field_default.sql.
const SQL_KEYWORDS = new Set([
	'CURRENT_TIMESTAMP',
	'CURRENT_DATE',
	'CURRENT_TIME',
	'LOCALTIME',
	'LOCALTIMESTAMP',
	'CURRENT_ROLE',
	'CURRENT_USER',
	'SESSION_USER',
	'USER',
	'CURRENT_CATALOG',
	'CURRENT_SCHEMA',
]);

/**
 * Convert a backend type-name string into a structured FieldType object.
 *
 * Handles array suffixes (`'text[]'` → `{ name: 'text', array_dimensions: 1 }`)
 * since brackets fail the backend `is_valid_type_name` regex. Trailing `[]`
 * pairs are stripped and counted into `array_dimensions`.
 */
export function toFieldType(typeName: string): FieldType {
	const raw = (typeName ?? '').trim();
	let base = raw;
	let dims = 0;
	while (base.endsWith('[]')) {
		base = base.slice(0, -2);
		dims += 1;
	}
	base = base.trim();
	const result: FieldType = { name: base };
	if (dims > 0) result.array_dimensions = dims;
	return result;
}

/** Best-effort parse of a single function-arg literal into a scalar. */
function parseScalarLiteral(token: string): string | number | boolean | null {
	const t = token.trim();
	if (t === '') return '';
	if (t === 'true') return true;
	if (t === 'false') return false;
	if (t.toLowerCase() === 'null') return null;
	if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
	// Strip surrounding single or double quotes.
	if ((t.startsWith("'") && t.endsWith("'")) || (t.startsWith('"') && t.endsWith('"'))) {
		return t.slice(1, -1);
	}
	return t;
}

/**
 * Convert a backend default-expression string into a structured FieldDefault
 * object (or undefined when empty).
 *
 * Recognizes:
 *  - function calls            `uuidv7()` → `{ function: 'uuidv7' }`
 *  - boolean / numeric literals `true` → `{ value: true }`, `42` → `{ value: 42 }`
 *  - SQL keywords (allowlist)   `CURRENT_TIMESTAMP` → `{ sql_keyword: 'CURRENT_TIMESTAMP' }`
 *  - quoted / plain string      `'draft'` → `{ value: 'draft' }`
 */
export function toFieldDefault(def?: string | null): FieldDefault | undefined {
	if (def === undefined || def === null) return undefined;
	const raw = String(def).trim();
	if (raw === '') return undefined;

	// SQL keyword allowlist (case-insensitive match, canonical upper-case emit).
	if (SQL_KEYWORDS.has(raw.toUpperCase())) {
		return { sql_keyword: raw.toUpperCase() };
	}

	// Function call: name(...optional args...)
	const fnMatch = raw.match(/^([a-zA-Z_][a-zA-Z0-9_]*)\s*\(([\s\S]*)\)$/);
	if (fnMatch) {
		const fnName = fnMatch[1];
		const argsRaw = fnMatch[2].trim();
		const result: { function: string; args?: (string | number | boolean | null)[] } = { function: fnName };
		if (argsRaw !== '') {
			const args = argsRaw.split(',').map((a) => parseScalarLiteral(a));
			if (args.length > 0) result.args = args;
		}
		return result;
	}

	// Boolean / numeric literals.
	if (raw === 'true') return { value: true };
	if (raw === 'false') return { value: false };
	if (/^-?\d+(\.\d+)?$/.test(raw)) return { value: Number(raw) };

	// Quoted string literal — strip surrounding quotes.
	if ((raw.startsWith("'") && raw.endsWith("'")) || (raw.startsWith('"') && raw.endsWith('"'))) {
		return { value: raw.slice(1, -1) };
	}

	// Plain string literal.
	return { value: raw };
}

/**
 * Reverse of {@link toFieldType}: extract the type-name string from a structured
 * FieldType object (`{ name, array_dimensions? }` → `'name'` / `'name[]'`).
 *
 * Passes through if already a string; returns '' for null/undefined.
 */
export function fieldTypeToTypeName(t: unknown): string {
	if (t == null) return '';
	if (typeof t === 'string') return t;
	if (typeof t === 'object') {
		const obj = t as { name?: unknown; array_dimensions?: unknown };
		if (typeof obj.name === 'string') {
			const dims = typeof obj.array_dimensions === 'number' && obj.array_dimensions > 0 ? obj.array_dimensions : 0;
			return obj.name + '[]'.repeat(dims);
		}
	}
	return '';
}

import type {
	DatabaseField,
	DatabaseIndex,
	DatabaseTable,
	ForeignKeyConstraint,
	PrimaryKeyConstraint,
	UniqueConstraint,
	UserDatabase,
} from '../use-user-databases';
import { mapToFrontendCellType } from '../../../type-mapping';
import type { CellType } from '../../../../types/cell-types';
import type {
	DbLightSchema,
	FieldConstraints,
	FieldDefinition,
	ForeignKeyAction,
	IndexType,
	RelationshipDefinition,
	TableConstraint,
	TableDefinition,
} from '../../../../schema';
import { ForeignKeyActions } from '../../../../schema';

import { mapDbFieldToConstraints } from './field-constraints-mapper';

const DEFAULT_TIMESTAMP = '1970-01-01T00:00:00.000Z';

export interface RemoteSchemaInput {
	key: string;
	dbSchema: DbLightSchema;
	category?: string;
	description?: string;
	checksum: string;
	databaseInfo?: {
		id: string;
		name: string;
		label?: string | null;
		schemaId?: string | null;
		ownerName?: string;
		ownerId?: string;
		tableCount: number;
		fieldCount: number;
	};
}

type SchemaNode = NonNullable<NonNullable<UserDatabase['schemas']>['nodes']>[number];
type TableEdge = NonNullable<NonNullable<UserDatabase['tables']>['edges']>[number];

function normalizeTables(connection: UserDatabase['tables'] | undefined): DatabaseTable[] {
	if (!connection) return [];
	return connection.edges?.map((edge) => edge.node).filter(Boolean) ?? [];
}

function normalizeFields(connection: DatabaseTable['fields'] | undefined): DatabaseField[] {
	if (!connection) return [];
	return connection.nodes ?? [];
}

function extractSmartTagAlias(smartTags: Record<string, unknown> | null | undefined): string | null {
	if (!smartTags || typeof smartTags !== 'object') return null;

	const aliasCandidates = ['pgAlias', 'type', 'alias'];
	for (const key of aliasCandidates) {
		const value = smartTags[key];
		if (typeof value === 'string' && value.trim().length > 0) {
			return value;
		}
	}

	return null;
}

function mapPgTypeToGraphql(pgType?: string | null): string {
	if (!pgType) return 'String';

	const normalized = pgType.toLowerCase();

	if (normalized.includes('int')) return 'Int';
	if (normalized.includes('uuid')) return 'UUID';
	if (normalized.includes('bool')) return 'Boolean';
	if (
		normalized.includes('double') ||
		normalized.includes('numeric') ||
		normalized.includes('float') ||
		normalized.includes('decimal')
	) {
		return 'Float';
	}
	if (normalized.includes('timestamp') || normalized.includes('datetime')) return 'Datetime';
	if (normalized.includes('date')) return 'Date';
	if (normalized.includes('time')) return 'Time';
	if (normalized.includes('jsonb')) return 'JSON';
	if (normalized.includes('json')) return 'JSON';
	if (normalized.includes('interval')) return 'Interval';
	if (normalized.includes('point') || normalized.includes('geometry')) return 'GeoJSON';

	return 'String';
}

function inferCellType(field: DatabaseField): CellType {
	const typeName = field.type ?? '';
	const isArray = typeName.endsWith('[]');
	const baseType = isArray ? typeName.slice(0, -2) : typeName;
	const smartTagAlias = extractSmartTagAlias(field.smartTags ?? undefined);

	const cellType = mapToFrontendCellType({
		gqlType: mapPgTypeToGraphql(baseType),
		isArray,
		pgAlias: smartTagAlias ?? undefined,
		pgType: baseType || undefined,
		subtype: null,
	});

	return cellType === 'unknown' ? 'text' : cellType;
}

function buildFieldConstraints(
	field: DatabaseField,
	cellType: CellType,
	isPrimaryKey: boolean,
	isUnique: boolean,
): FieldConstraints {
	const constraints: FieldConstraints = {
		nullable: !field.isRequired,
		defaultValue: field.defaultValue,
		primaryKey: isPrimaryKey,
		unique: isUnique,
	};

	const dynamicConstraints = mapDbFieldToConstraints(field, cellType);

	return {
		...constraints,
		...dynamicConstraints,
	};
}

function buildFieldDefinition(
	field: DatabaseField,
	isPrimaryKey: boolean,
	isUnique: boolean,
	naturalOrder: number,
): FieldDefinition {
	const cellType = inferCellType(field);

	return {
		id: field.id,
		name: field.name,
		type: cellType,
		label: field.label ?? field.name,
		description: field.description ?? undefined,
		constraints: buildFieldConstraints(field, cellType, isPrimaryKey, isUnique),
		fieldOrder: field.fieldOrder ?? naturalOrder,
		isRequired: field.isRequired ?? false,
		metadata: {
			smartTags: field.smartTags ?? null,
		},
	};
}

function buildTableDefinition(
	table: DatabaseTable,
	primaryKeyConstraint: PrimaryKeyConstraint | undefined,
	uniqueConstraints: UniqueConstraint[],
	foreignKeyConstraints: ForeignKeyConstraint[],
	indices: DatabaseIndex[],
): TableDefinition {
	const fields = normalizeFields(table.fields).sort((a, b) => (a.fieldOrder ?? 0) - (b.fieldOrder ?? 0));

	const primaryKeyFieldIds = new Set(primaryKeyConstraint?.fieldIds ?? []);
	const uniqueFieldIds = new Set<string>();
	for (const constraint of uniqueConstraints) {
		// Only mark single-field unique constraints on the field level
		if (constraint.fieldIds.length === 1) {
			uniqueFieldIds.add(constraint.fieldIds[0]);
		}
	}

	const fieldDefinitions = fields.map((field, index) =>
		buildFieldDefinition(field, primaryKeyFieldIds.has(field.id), uniqueFieldIds.has(field.id), index),
	);

	const constraints: TableConstraint[] = [];
	if (primaryKeyConstraint) {
		constraints.push({
			id: primaryKeyConstraint.id,
			name: primaryKeyConstraint.name ?? undefined,
			type: 'primary_key',
			fields: primaryKeyConstraint.fieldIds,
		});
	}

	for (const constraint of uniqueConstraints) {
		constraints.push({
			id: constraint.id,
			name: constraint.name ?? undefined,
			type: 'unique',
			fields: constraint.fieldIds,
		});
	}

	// Add foreign key constraints (only 1-to-1 field mappings)
	for (const fk of foreignKeyConstraints) {
		if (fk.fieldIds.length === 1 && fk.refFieldIds.length === 1) {
			constraints.push({
				id: fk.id,
				name: fk.name ?? undefined,
				type: 'foreign_key',
				fields: fk.fieldIds,
				referencedTable: fk.refTableId,
				referencedFields: fk.refFieldIds,
				onDelete: (fk.deleteAction as ForeignKeyAction) ?? ForeignKeyActions.NO_ACTION,
				onUpdate: (fk.updateAction as ForeignKeyAction) ?? ForeignKeyActions.NO_ACTION,
				smartTags: fk.smartTags ?? null,
				createdAt: fk.createdAt ?? undefined,
			});
		}
	}

	const tableIndexes = indices
		.filter((index) => index.tableId === table.id)
		.map((index) => ({
			id: index.id,
			name: index.name,
			fields: index.fieldIds ?? [],
			unique: Boolean(index.isUnique),
			type: index.accessMethod as IndexType,
			createdAt: index.createdAt ?? undefined,
		}));

	// Map GraphQL ObjectCategory enum (lowercase: 'core'|'module'|'app') to uppercase literals
	const category = table.category
		? (table.category.toUpperCase() as 'CORE' | 'MODULE' | 'APP')
		: undefined;

	return {
		id: table.id,
		name: table.name,
		label: table.label ?? table.name,
		description: table.description ?? undefined,
		fields: fieldDefinitions,
		indexes: tableIndexes,
		constraints,
		category,
		smartTags: table.smartTags ?? undefined,
	};
}

function buildDbLightSchema(
	database: UserDatabase,
	primaryKeyConstraintsMap: Map<string, PrimaryKeyConstraint>,
	uniqueConstraintsMap: Map<string, UniqueConstraint[]>,
	foreignKeyConstraintsMap: Map<string, ForeignKeyConstraint[]>,
	indicesMap: Map<string, DatabaseIndex[]>,
): DbLightSchema {
	const tables = normalizeTables(database.tables)
		// By default get all tables: core/module/app
		.map((table) =>
			buildTableDefinition(
				table,
				primaryKeyConstraintsMap.get(table.id),
				uniqueConstraintsMap.get(table.id) ?? [],
				foreignKeyConstraintsMap.get(table.id) ?? [],
				indicesMap.get(table.id) ?? [],
			),
		);
	const totalFields = tables.reduce((sum, table) => sum + table.fields.length, 0);

	const relationships = buildRelationships(foreignKeyConstraintsMap, tables);

	return {
		id: database.id,
		name: database.label ?? database.name ?? 'Untitled Database',
		description: database.name ?? undefined,
		version: 'remote-schema-1',
		tables,
		relationships,
		metadata: {
			createdAt: DEFAULT_TIMESTAMP,
			updatedAt: DEFAULT_TIMESTAMP,
			author: database.owner?.displayName ?? database.owner?.username ?? '',
			tags: ['Database', database.name ?? ''].filter(Boolean),
			databaseId: database.id,
			databaseName: database.name ?? undefined,
			databaseLabel: database.label ?? null,
			sourceType: 'remote-database',
			ownerId: database.owner?.id ?? null,
			ownerName: database.owner?.displayName ?? database.owner?.username ?? null,
			tableCount: tables.length,
			fieldCount: totalFields,
		},
	};
}

function createChecksum(dbSchema: DbLightSchema): string {
	return JSON.stringify({
		id: dbSchema.id,
		name: dbSchema.name,
		tables: dbSchema.tables.map((table) => ({
			id: table.id,
			name: table.name,
			fields: table.fields.map((field) => ({
				id: field.id,
				name: field.name,
				type: field.type,
				constraints: field.constraints,
				fieldOrder: field.fieldOrder,
			})),
			constraints: (table.constraints || []).map((constraint) => {
				if (constraint.type === 'foreign_key') {
					return {
						id: constraint.id,
						type: constraint.type,
						fields: constraint.fields,
						referencedTable: constraint.referencedTable,
						referencedFields: constraint.referencedFields,
						onDelete: constraint.onDelete,
						onUpdate: constraint.onUpdate,
					};
				}

				if (constraint.type === 'primary_key' || constraint.type === 'unique') {
					return {
						id: constraint.id,
						type: constraint.type,
						fields: constraint.fields,
					};
				}

				return {
					id: constraint.id,
					type: constraint.type,
					fields: constraint.fields,
				};
			}),
			indexes: (table.indexes || []).map((index) => ({
				id: index.id,
				name: index.name,
				fields: index.fields,
				unique: index.unique,
				type: index.type,
				createdAt: index.createdAt,
			})),
		})),
		relationships: (dbSchema.relationships || []).map((relationship) => ({
			id: relationship.id,
			name: relationship.name,
			sourceTable: relationship.sourceTable,
			sourceField: relationship.sourceField,
			targetTable: relationship.targetTable,
			targetField: relationship.targetField,
			type: relationship.type,
			onDelete: relationship.onDelete,
			onUpdate: relationship.onUpdate,
		})),
	});
}

function resolveSchemaId(database: UserDatabase): string | undefined {
	const schemaNodes: SchemaNode[] = (database.schemas?.nodes ?? []).filter((schema): schema is SchemaNode =>
		Boolean(schema && schema.id),
	);

	// Try 'app_public' first (provisioned databases), then 'public' (default)
	const appPublicSchema = schemaNodes.find((schema) => schema.name === 'app_public');
	if (appPublicSchema) return appPublicSchema.id;

	const publicSchema = schemaNodes.find((schema) => schema.name === 'public');
	return publicSchema?.id;
}

function buildRelationships(
	foreignKeyConstraintsMap: Map<string, ForeignKeyConstraint[]>,
	tables: TableDefinition[],
): RelationshipDefinition[] {
	const relationships: RelationshipDefinition[] = [];
	const tableIdToNameMap = new Map(tables.map((t) => [t.id, t.name]));
	const fieldIdToNameMap = new Map<string, string>();

	// Build field ID to name map
	for (const table of tables) {
		for (const field of table.fields) {
			fieldIdToNameMap.set(field.id, field.name);
		}
	}

	for (const [tableId, foreignKeys] of foreignKeyConstraintsMap) {
		for (const fk of foreignKeys) {
			// Only process 1-to-1 field mappings (both arrays have exactly 1 item)
			if (fk.fieldIds.length !== 1 || fk.refFieldIds.length !== 1) {
				continue;
			}

			const sourceTableName = tableIdToNameMap.get(tableId);
			const targetTableName = tableIdToNameMap.get(fk.refTableId);
			const sourceFieldName = fieldIdToNameMap.get(fk.fieldIds[0]);
			const targetFieldName = fieldIdToNameMap.get(fk.refFieldIds[0]);

			if (!sourceTableName || !targetTableName || !sourceFieldName || !targetFieldName) {
				continue;
			}

			relationships.push({
				id: fk.id,
				name: fk.name ?? undefined,
				sourceTable: tableId,
				sourceField: sourceFieldName,
				targetTable: fk.refTableId,
				targetField: targetFieldName,
				type: 'one-to-many',
				onDelete: (fk.deleteAction as ForeignKeyAction) ?? ForeignKeyActions.NO_ACTION,
				onUpdate: (fk.updateAction as ForeignKeyAction) ?? ForeignKeyActions.NO_ACTION,
			});
		}
	}

	return relationships;
}

export function transformUserDatabase(
	database: UserDatabase,
	primaryKeyConstraintsMap: Map<string, PrimaryKeyConstraint>,
	uniqueConstraintsMap: Map<string, UniqueConstraint[]>,
	foreignKeyConstraintsMap: Map<string, ForeignKeyConstraint[]>,
	indicesMap: Map<string, DatabaseIndex[]>,
): RemoteSchemaInput {
	const dbSchema = buildDbLightSchema(
		database,
		primaryKeyConstraintsMap,
		uniqueConstraintsMap,
		foreignKeyConstraintsMap,
		indicesMap,
	);
	const fieldCount = dbSchema.tables.reduce((sum, table) => sum + table.fields.length, 0);
	const resolvedSchemaId = resolveSchemaId(database);

	if (resolvedSchemaId) {
		const metadata = dbSchema.metadata ?? {
			createdAt: DEFAULT_TIMESTAMP,
			updatedAt: DEFAULT_TIMESTAMP,
			tableCount: dbSchema.tables.length,
			fieldCount,
		};
		dbSchema.metadata = {
			...metadata,
			schemaId: resolvedSchemaId,
			tableCount: metadata.tableCount ?? dbSchema.tables.length,
			fieldCount: metadata.fieldCount ?? fieldCount,
		};
	}
	const checksum = createChecksum(dbSchema);

	return {
		key: `db-${database.id}`,
		dbSchema,
		category: 'Database',
		description: database.owner ? `Owner: ${database.owner.displayName ?? database.owner.username}` : undefined,
		checksum,
		databaseInfo: {
			id: database.id,
			name: database.name ?? 'Untitled Database',
			label: database.label,
			schemaId: resolvedSchemaId ?? undefined,
			ownerName: database.owner?.displayName ?? database.owner?.username ?? undefined,
			ownerId: database.owner?.id ?? undefined,
			tableCount: dbSchema.tables.length,
			fieldCount,
		},
	};
}

export function transformUserDatabases(
	databases: UserDatabase[],
	primaryKeyConstraints: PrimaryKeyConstraint[],
	uniqueConstraints: UniqueConstraint[],
	foreignKeyConstraints: ForeignKeyConstraint[],
	indices: DatabaseIndex[],
): RemoteSchemaInput[] {
	// Build map of tableId -> primaryKeyConstraint
	const primaryKeyConstraintsMap = new Map<string, PrimaryKeyConstraint>();
	for (const constraint of primaryKeyConstraints) {
		primaryKeyConstraintsMap.set(constraint.tableId, constraint);
	}

	// Build map of tableId -> uniqueConstraints[]
	const uniqueConstraintsMap = new Map<string, UniqueConstraint[]>();
	for (const constraint of uniqueConstraints) {
		const existing = uniqueConstraintsMap.get(constraint.tableId) ?? [];
		existing.push(constraint);
		uniqueConstraintsMap.set(constraint.tableId, existing);
	}

	// Build map of tableId -> foreignKeyConstraints[]
	const foreignKeyConstraintsMap = new Map<string, ForeignKeyConstraint[]>();
	for (const constraint of foreignKeyConstraints) {
		const existing = foreignKeyConstraintsMap.get(constraint.tableId) ?? [];
		existing.push(constraint);
		foreignKeyConstraintsMap.set(constraint.tableId, existing);
	}

	// Build map of tableId -> indices[]
	const indicesMap = new Map<string, DatabaseIndex[]>();
	for (const index of indices) {
		const existing = indicesMap.get(index.tableId) ?? [];
		existing.push(index);
		indicesMap.set(index.tableId, existing);
	}

	return databases.map((database) =>
		transformUserDatabase(
			database,
			primaryKeyConstraintsMap,
			uniqueConstraintsMap,
			foreignKeyConstraintsMap,
			indicesMap,
		),
	);
}

/**
 * Hook for fetching databases accessible to the current user (without constraints)
 * Tier 4 wrapper: Uses SDK hooks + composition
 *
 * This includes:
 * 1. Databases owned directly by the user
 * 2. Databases owned by organizations the user is a member of
 *
 * This hook fetches databases/tables/fields which change frequently.
 * For constraints/indexes (which change rarely), use useDatabaseConstraints.
 *
 * Split from the original mega-query to enable different caching strategies:
 * - Databases: 30s staleTime, respects cache on mount
 * - Constraints: 5min staleTime (see use-database-constraints.ts)
 */
import { useMemo } from 'react';
import {
	type Field,
	type Table,
} from '@/components/schema-builder/compat/schema-builder-sdk';
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useAuthSdkClient,
	useSchemaBuilderConfig,
	useSchemaBuilderSdkClient,
} from '@/components/schema-builder/compat/block-config';

import type { SchemaContext } from '../../../../app-config';

import {
	buildFieldsByTableMap,
	buildTablesByDatabaseMap,
	extractIds,
	type DatabaseApiNode,
	type DatabaseFieldNode,
	type DatabaseOwnerNode,
	type DatabaseSchemaNode,
	type DatabaseTableNode,
} from './database-shared-utils';

// Re-export shared types for backwards compatibility
export type { DatabaseFieldNode as AccessibleDatabaseField, DatabaseTableNode as AccessibleDatabaseTable };

// Owner type - extends shared type with 'type' field for user/org distinction
export interface AccessibleDatabaseOwner extends DatabaseOwnerNode {
	type: string | null;
}

// Database type (uses shared sub-types)
export interface AccessibleDatabase {
	id: string;
	label: string | null;
	name: string;
	ownerId: string;
	owner: AccessibleDatabaseOwner | null;
	tables: {
		edges: Array<{ node: DatabaseTableNode }>;
		totalCount: number;
	} | null;
	schemas: {
		nodes: DatabaseSchemaNode[];
	} | null;
	apis: {
		nodes: DatabaseApiNode[];
	} | null;
}

interface AccessibleDatabasesQueryResult {
	databases: {
		nodes: AccessibleDatabase[];
		totalCount: number;
		pageInfo: {
			hasNextPage: boolean;
			hasPreviousPage: boolean;
		};
	} | null;
}

export interface UseAccessibleDatabasesOptions {
	/** Enable/disable the query */
	enabled?: boolean;
	/** Override schema context (defaults to schema-builder) */
	context?: SchemaContext;
}

export interface UseAccessibleDatabasesResult {
	/** Array of all accessible database objects */
	databases: AccessibleDatabase[];
	/** Total count of all databases */
	totalCount: number;
	/** True once the current enabled lookup has produced a stable result (success, empty, or error). */
	hasResolved: boolean;
	/** True only on initial load (no cached data yet) */
	isLoading: boolean;
	/** True when fetching (including background refetch with cached data) */
	isFetching: boolean;
	/** Error state */
	error: Error | null;
	/** Pagination info */
	pageInfo: {
		hasNextPage: boolean;
		hasPreviousPage: boolean;
	};
	/** Refetch function */
	refetch: () => Promise<unknown>;
}

/**
 * Hook for fetching databases accessible to the current user
 *
 * This combines:
 * - User's personal databases (owned directly)
 * - Organization databases (owned by orgs the user belongs to)
 *
 * NOTE: This hook does NOT include constraints/indexes.
 * Use useDatabaseConstraints separately for those.
 *
 * @example
 * ```tsx
 * const { databases, isLoading } = useAccessibleDatabases();
 *
 * // Databases include both personal and org-owned databases
 * databases.forEach(db => {
 *   console.log(db.name, db.owner?.displayName);
 * });
 * ```
 */
export function useAccessibleDatabases(options: UseAccessibleDatabasesOptions = {}): UseAccessibleDatabasesResult {
	const { enabled = true, context = 'schema-builder' } = options;
	const {
		fetchApiSchemasQuery,
		fetchApisQuery,
		fetchDatabasesQuery,
		fetchFieldsQuery,
		fetchSchemasQuery,
		fetchTablesQuery,
	} = useSchemaBuilderSdkClient();
	const { fetchUsersQuery } = useAuthSdkClient();
	void context; // Context handled by SDK execute-adapter

	// Block scope (org + user) is host-supplied, not URL/auth-store derived.
	const { databaseId, orgId, userId } = useSchemaBuilderConfig();
	const isAuthLoading = false;
	const orgsLoading = false;

	// Owner IDs = current user + the configured org. Memoized to keep query keys stable.
	const ownerIds = useMemo(() => [userId, orgId].filter((id): id is string => Boolean(id)), [userId, orgId]);

	// Fetch databases for all owner IDs in a single query
	const {
		data,
		isFetched,
		isLoading: dbLoading,
		isFetching: dbFetching,
		error,
		refetch,
	} = useQuery<AccessibleDatabasesQueryResult>({
		queryKey: schemaBuilderQueryKey(
			{ orgId, databaseId, userId },
			'core',
			'accessibleDatabases',
			{ context, ownerIds },
		),
		queryFn: async (): Promise<AccessibleDatabasesQueryResult> => {
			// Step 1: Fetch databases by owner IDs
			const databasesResult = await fetchDatabasesQuery({
				selection: {
					fields: { id: true, name: true, label: true, ownerId: true },
					where: { ownerId: { in: ownerIds } },
					orderBy: ['CREATED_AT_ASC'],
				},
			});

			const rawDatabases = databasesResult.databases?.nodes ?? [];
			if (rawDatabases.length === 0) {
				return {
					databases: { nodes: [], totalCount: 0, pageInfo: { hasNextPage: false, hasPreviousPage: false } },
				};
			}

			const databaseIds = extractIds(rawDatabases);
			const uniqueOwnerIds = [...new Set(rawDatabases.map((d) => d.ownerId).filter((id): id is string => !!id))];

			// Step 2: Fetch all related data in parallel
			const [tablesResult, schemasResult, apisResult, ownersResult] = await Promise.all([
				fetchTablesQuery({
					selection: {
						fields: {
							id: true,
							name: true,
							label: true,
							description: true,
							pluralName: true,
							singularName: true,
							smartTags: true,
							timestamps: true,
							databaseId: true,
							schemaId: true,
							category: true,
						},
						where: { databaseId: { in: databaseIds } },
						orderBy: ['NAME_ASC'],
					},
				}),
				fetchSchemasQuery({
					selection: {
						fields: { id: true, name: true, schemaName: true, databaseId: true },
						where: { databaseId: { in: databaseIds } },
						orderBy: ['NAME_ASC'],
					},
				}),
				fetchApisQuery({
					selection: {
						fields: { id: true, name: true, databaseId: true },
						where: { databaseId: { in: databaseIds } },
						orderBy: ['NAME_ASC'],
					},
				}),
				uniqueOwnerIds.length > 0
					? fetchUsersQuery({
							selection: {
								fields: { id: true, displayName: true, username: true, type: true },
								where: { id: { in: uniqueOwnerIds } },
							},
						})
					: Promise.resolve({ users: { nodes: [] } }),
			]);

			// Step 3: Fetch fields and apiSchemas
			const tableIds = extractIds(tablesResult.tables?.nodes ?? []);
			const apiIds = extractIds(apisResult.apis?.nodes ?? []);

			const [fieldsResult, apiSchemasResult] = await Promise.all([
				tableIds.length > 0
					? fetchFieldsQuery({
							selection: {
								fields: {
									id: true,
									name: true,
									type: true,
									chk: true,
									chkExpr: true,
									defaultValue: true,
									description: true,
									fieldOrder: true,
									isRequired: true,
									label: true,
									max: true,
									min: true,
									regexp: true,
									smartTags: true,
									tableId: true,
								},
								where: { tableId: { in: tableIds } },
							},
						})
					: Promise.resolve({ fields: { nodes: [] } }),
				apiIds.length > 0
					? fetchApiSchemasQuery({
							selection: {
								fields: { id: true, apiId: true, schemaId: true },
								where: { apiId: { in: apiIds } },
							},
						})
					: Promise.resolve({ apiSchemas: { nodes: [] } }),
			]);

			// Step 4: Build lookup maps using shared utilities
			const ownerMap = new Map<string, AccessibleDatabaseOwner>();
			for (const u of ownersResult.users?.nodes ?? []) {
				if (u.id) {
					ownerMap.set(u.id, {
						id: u.id,
						displayName: u.displayName ?? null,
						username: u.username ?? null,
						type: u.type != null ? String(u.type) : null,
					});
				}
			}

			// Use shared utility for fields and tables
			const fieldsByTable = buildFieldsByTableMap((fieldsResult.fields?.nodes ?? []) as Field[]);
			const tablesByDatabase = buildTablesByDatabaseMap((tablesResult.tables?.nodes ?? []) as Table[], fieldsByTable);

			const schemasByDatabase = new Map<string, DatabaseSchemaNode[]>();
			for (const s of schemasResult.schemas?.nodes ?? []) {
				if (s.databaseId) {
					const existing = schemasByDatabase.get(s.databaseId) ?? [];
					existing.push({ id: s.id ?? '', name: s.name ?? '', schemaName: s.schemaName ?? '' });
					schemasByDatabase.set(s.databaseId, existing);
				}
			}

			const apiSchemasByApi = new Map<string, Array<{ schemaId: string }>>();
			for (const as of apiSchemasResult.apiSchemas?.nodes ?? []) {
				if (as.apiId) {
					const existing = apiSchemasByApi.get(as.apiId) ?? [];
					existing.push({ schemaId: as.schemaId ?? '' });
					apiSchemasByApi.set(as.apiId, existing);
				}
			}

			const apisByDatabase = new Map<string, DatabaseApiNode[]>();
			for (const a of apisResult.apis?.nodes ?? []) {
				if (a.databaseId) {
					const existing = apisByDatabase.get(a.databaseId) ?? [];
					existing.push({
						id: a.id ?? '',
						name: a.name ?? '',
						apiSchemas: { nodes: apiSchemasByApi.get(a.id ?? '') ?? [] },
					});
					apisByDatabase.set(a.databaseId, existing);
				}
			}

			// Step 5: Build final databases structure
			const databases: AccessibleDatabase[] = rawDatabases.map((d) => {
				const tables = tablesByDatabase.get(d.id ?? '') ?? [];
				return {
					id: d.id ?? '',
					label: d.label ?? null,
					name: d.name ?? '',
					ownerId: d.ownerId ?? '',
					owner: d.ownerId ? (ownerMap.get(d.ownerId) ?? null) : null,
					tables: {
						edges: tables.map((t) => ({ node: t })),
						totalCount: tables.length,
					},
					schemas: { nodes: schemasByDatabase.get(d.id ?? '') ?? [] },
					apis: { nodes: apisByDatabase.get(d.id ?? '') ?? [] },
				};
			});

			return {
				databases: {
					nodes: databases,
					totalCount: databasesResult.databases?.totalCount ?? 0,
					pageInfo: {
						hasNextPage: databasesResult.databases?.pageInfo?.hasNextPage ?? false,
						hasPreviousPage: databasesResult.databases?.pageInfo?.hasPreviousPage ?? false,
					},
				},
			};
		},
		enabled: enabled && !orgsLoading && ownerIds.length > 0,
		staleTime: 30 * 1000, // 30 seconds - shorter for fresher data
		refetchOnMount: true, // Respect staleTime (NOT 'always' which ignores cache)
	});

	// Extract the data from the response (data is undefined when query is disabled or loading)
	const databases = data?.databases?.nodes ?? [];
	const totalCount = data?.databases?.totalCount ?? 0;
	const pageInfo = data?.databases?.pageInfo ?? {
		hasNextPage: false,
		hasPreviousPage: false,
	};

	// Loading state logic:
	// isLoading = true only on initial load (no cached data yet)
	// isFetching = true during any fetch (including background refetch)
	//
	// - If auth is still initializing, report loading
	// - If orgs are loading (includes auth loading via useOrganizations), report loading
	// - If db query is loading (first time), report loading
	// - If auth done and not authenticated (no userId, empty ownerIds), report NOT loading
	//   (query is disabled, allows route guards to properly redirect)
	const isLoading = isAuthLoading || orgsLoading || dbLoading;
	const isFetching = dbFetching;
	const hasResolved =
		enabled &&
		!isAuthLoading &&
		!orgsLoading &&
		(ownerIds.length === 0 || isFetched || data !== undefined || error != null);

	return {
		databases,
		totalCount,
		hasResolved,
		isLoading,
		isFetching,
		error,
		pageInfo,
		refetch,
	};
}

/**
 * Generate query keys for consistent cache management
 */
export const accessibleDatabasesQueryKeys = {
	all: ['accessible-databases'] as const,
	byContext: (context: SchemaContext) => [...accessibleDatabasesQueryKeys.all, { context }] as const,
	byOwners: (context: SchemaContext, ownerIds: string[]) =>
		[...accessibleDatabasesQueryKeys.byContext(context), { ownerIds: [...ownerIds].sort() }] as const,
};

/**
 * Hook for fetching database constraints and indexes
 * Tier 4 wrapper: Uses SDK hooks + cache invalidation
 *
 * This includes:
 * - Primary key constraints
 * - Unique constraints
 * - Foreign key constraints
 * - Indexes
 *
 * These are fetched globally (no databaseId filter) because:
 * - tableId is globally unique across all databases
 * - During transformation, constraints are mapped by tableId to correct tables
 * - See transformUserDatabases() in transformers.ts
 *
 * Split from the original mega-query to enable different caching strategies:
 * - Constraints: 5min staleTime (changes rarely)
 * - Databases: 30s staleTime (see use-accessible-databases.ts)
 */
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useSchemaBuilderSdkClient,
	useSchemaBuilderRuntime,
} from '@/components/schema-builder/compat/block-config';

import type { SchemaContext } from '../../../../app-config';
import { parseListField } from './parse-list-field';

// Constraint types
export interface PrimaryKeyConstraint {
	databaseId: string;
	fieldIds: string[];
	id: string;
	name: string;
	tableId: string;
	type: string;
}

export interface UniqueConstraint {
	databaseId: string;
	fieldIds: string[];
	id: string;
	name: string;
	tableId: string;
	type: string;
}

export interface ForeignKeyConstraint {
	createdAt: string | null;
	databaseId: string;
	deleteAction: string | null;
	description: string | null;
	fieldIds: string[];
	id: string;
	name: string;
	refFieldIds: string[];
	refTableId: string;
	smartTags: Record<string, unknown> | null;
	tableId: string;
	type: string;
	updateAction: string | null;
}

export interface DatabaseIndex {
	accessMethod: string | null;
	createdAt: string | null;
	databaseId: string;
	fieldIds: string[];
	id: string;
	includeFieldIds: string[] | null;
	indexParams: string | null;
	isUnique: boolean | null;
	name: string;
	tableId: string;
	whereClause: string | null;
}

interface DatabaseConstraintsData {
	primaryKeyConstraints: PrimaryKeyConstraint[];
	uniqueConstraints: UniqueConstraint[];
	foreignKeyConstraints: ForeignKeyConstraint[];
	indexes: DatabaseIndex[];
}

export interface UseDatabaseConstraintsOptions {
	/** Enable/disable the query */
	enabled?: boolean;
	/** Override schema context (defaults to schema-builder) */
	context?: SchemaContext;
}

export interface UseDatabaseConstraintsResult {
	/** Primary key constraints across all databases */
	primaryKeyConstraints: PrimaryKeyConstraint[];
	/** Unique constraints across all databases */
	uniqueConstraints: UniqueConstraint[];
	/** Foreign key constraints across all databases */
	foreignKeyConstraints: ForeignKeyConstraint[];
	/** Index definitions across all databases */
	indexes: DatabaseIndex[];
	/** True only on initial load (no cached data yet) */
	isLoading: boolean;
	/** True when fetching (including background refetch with cached data) */
	isFetching: boolean;
	/** Error state */
	error: Error | null;
	/** Refetch function */
	refetch: () => Promise<unknown>;
}

/**
 * Hook for fetching database constraints and indexes
 *
 * This fetches constraints/indexes which change rarely (5min staleTime).
 * For databases/tables/fields (which change more often), use useAccessibleDatabases.
 *
 * @example
 * ```tsx
 * const {
 *   primaryKeyConstraints,
 *   foreignKeyConstraints,
 *   indexes,
 *   isLoading
 * } = useDatabaseConstraints();
 *
 * // Constraints are mapped by tableId in the transformer
 * foreignKeyConstraints.forEach(fk => {
 *   console.log(fk.name, fk.tableId, '->', fk.refTableId);
 * });
 * ```
 */
export function useDatabaseConstraints(
	options: UseDatabaseConstraintsOptions = {}
): UseDatabaseConstraintsResult {
	const { enabled = true, context = 'schema-builder' } = options;
	const { scope } = useSchemaBuilderRuntime();
	const {
		fetchForeignKeyConstraintsQuery,
		fetchIndicesQuery,
		fetchPrimaryKeyConstraintsQuery,
		fetchUniqueConstraintsQuery,
	} = useSchemaBuilderSdkClient();
	void context; // Context is handled by SDK execute-adapter

	const {
		data,
		isLoading,
		isFetching,
		error,
		refetch,
	} = useQuery<DatabaseConstraintsData>({
		queryKey: schemaBuilderQueryKey(scope, 'core', 'databaseConstraints', { context }),
		queryFn: async () => {
			// Fetch all constraint types in parallel using SDK fetch functions
			const [pkResult, uqResult, fkResult, idxResult] = await Promise.all([
				fetchPrimaryKeyConstraintsQuery({
					selection: {
						fields: { id: true, databaseId: true, tableId: true, name: true, type: true, fieldIds: true },
					},
				}),
				fetchUniqueConstraintsQuery({
					selection: {
						fields: { id: true, databaseId: true, tableId: true, name: true, type: true, fieldIds: true },
					},
				}),
				fetchForeignKeyConstraintsQuery({
					selection: {
						fields: { id: true, databaseId: true, tableId: true, name: true, type: true, fieldIds: true, refFieldIds: true, refTableId: true, deleteAction: true, updateAction: true, description: true, smartTags: true, createdAt: true },
						orderBy: ['CREATED_AT_DESC'],
					},
				}),
				fetchIndicesQuery({
					selection: {
						fields: { id: true, databaseId: true, tableId: true, name: true, fieldIds: true, includeFieldIds: true, accessMethod: true, indexParams: true, whereClause: true, isUnique: true, createdAt: true },
						orderBy: ['CREATED_AT_DESC'],
					},
				}),
			]);

			// Map SDK types to local types
			const primaryKeyConstraints: PrimaryKeyConstraint[] = (pkResult.primaryKeyConstraints?.nodes ?? []).map(
				(node) => ({
					databaseId: node.databaseId ?? '',
					fieldIds: parseListField(node.fieldIds),
					id: node.id ?? '',
					name: node.name ?? '',
					tableId: node.tableId ?? '',
					type: node.type ?? '',
				}),
			);

			const uniqueConstraints: UniqueConstraint[] = (uqResult.uniqueConstraints?.nodes ?? []).map((node) => ({
				databaseId: node.databaseId ?? '',
				fieldIds: parseListField(node.fieldIds),
				id: node.id ?? '',
				name: node.name ?? '',
				tableId: node.tableId ?? '',
				type: node.type ?? '',
			}));

			const foreignKeyConstraints: ForeignKeyConstraint[] = (fkResult.foreignKeyConstraints?.nodes ?? []).map(
				(node) => ({
					createdAt: node.createdAt ?? null,
					databaseId: node.databaseId ?? '',
					deleteAction: node.deleteAction ?? null,
					description: node.description ?? null,
					fieldIds: parseListField(node.fieldIds),
					id: node.id ?? '',
					name: node.name ?? '',
					refFieldIds: parseListField(node.refFieldIds),
					refTableId: node.refTableId ?? '',
					smartTags: (node.smartTags as Record<string, unknown>) ?? null,
					tableId: node.tableId ?? '',
					type: node.type ?? '',
					updateAction: node.updateAction ?? null,
				}),
			);

			const indexes: DatabaseIndex[] = (idxResult.indices?.nodes ?? []).map((node): DatabaseIndex => ({
				accessMethod: node.accessMethod ?? null,
				createdAt: node.createdAt ?? null,
				databaseId: node.databaseId ?? '',
				fieldIds: parseListField(node.fieldIds),
				id: node.id ?? '',
				includeFieldIds: parseListField(node.includeFieldIds) ?? null,
				indexParams: typeof node.indexParams === 'string' ? node.indexParams : null,
				isUnique: node.isUnique ?? null,
				name: node.name ?? '',
				tableId: node.tableId ?? '',
				whereClause: typeof node.whereClause === 'string' ? node.whereClause : null,
			}));

			return {
				primaryKeyConstraints,
				uniqueConstraints,
				foreignKeyConstraints,
				indexes,
			};
		},
		enabled,
		staleTime: 5 * 60 * 1000, // 5 minutes - constraints change rarely
		refetchOnMount: true, // Respect staleTime (NOT 'always' which ignores cache)
	});

	return {
		primaryKeyConstraints: data?.primaryKeyConstraints ?? [],
		uniqueConstraints: data?.uniqueConstraints ?? [],
		foreignKeyConstraints: data?.foreignKeyConstraints ?? [],
		indexes: data?.indexes ?? [],
		isLoading,
		isFetching,
		error,
		refetch,
	};
}

/**
 * Generate query keys for consistent cache management
 */
export const databaseConstraintsQueryKeys = {
	all: ['database-constraints'] as const,
	byContext: (context: SchemaContext) =>
		[...databaseConstraintsQueryKeys.all, { context }] as const,
};

/**
 * Hook for fetching tables within a specific database
 * Tier 4 wrapper: Uses SDK hooks + composition
 */
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useSchemaBuilderSdkClient,
	useSchemaBuilderRuntime,
} from '@/components/schema-builder/compat/block-config';

import {
	type Field,
	type Table,
} from '@/components/schema-builder/compat/schema-builder-sdk';

import {
	type DatabaseFieldNode,
	type DatabaseTableNode,
	type PageInfo,
	EMPTY_PAGE_INFO,
	transformField,
	transformTable,
	buildFieldsByTableMap,
	extractIds,
} from './database-shared-utils';

// Re-export shared types for backwards compatibility
export type { DatabaseFieldNode as DbFieldNode, DatabaseTableNode as DbTableNode };

interface DatabaseTablesQueryResult {
	tables: {
		nodes: DatabaseTableNode[];
		totalCount: number;
		pageInfo: PageInfo;
	} | null;
}

export interface UseDatabaseTablesOptions {
	/** Database ID to fetch tables for */
	databaseId: string;
	/** Number of tables to fetch (default: 50) */
	first?: number;
	/** Offset for pagination */
	offset?: number;
	/** Enable/disable the query */
	enabled?: boolean;
}

export interface UseDatabaseTablesResult {
	tables: DatabaseTableNode[];
	totalCount: number;
	isLoading: boolean;
	error: Error | null;
	pageInfo: PageInfo;
	refetch: () => Promise<unknown>;
}

/**
 * Hook for fetching tables within a specific database
 *
 * @example
 * ```tsx
 * const { tables, totalCount, isLoading } = useDatabaseTables({
 *   databaseId: 'database-uuid',
 * });
 * ```
 */
export function useDatabaseTables(options: UseDatabaseTablesOptions): UseDatabaseTablesResult {
	const { databaseId, first = 50, offset = 0, enabled = true } = options;
	const { scope } = useSchemaBuilderRuntime();
	const { fetchFieldsQuery, fetchTablesQuery } = useSchemaBuilderSdkClient();

	const { data, isLoading, error, refetch } = useQuery<DatabaseTablesQueryResult, Error>({
		queryKey: schemaBuilderQueryKey(scope, 'core', 'databaseTables', { databaseId, first, offset }),
		queryFn: async (): Promise<DatabaseTablesQueryResult> => {
			// Step 1: Fetch tables for this database
			const tablesResult = await fetchTablesQuery({
				selection: {
					fields: { id: true, name: true, label: true, description: true, pluralName: true, singularName: true, smartTags: true, timestamps: true, databaseId: true, schemaId: true, category: true },
					where: { databaseId: { equalTo: databaseId } },
					first,
					offset,
					orderBy: ['NAME_ASC'],
				},
			});

			const tables = tablesResult.tables?.nodes ?? [];
			if (tables.length === 0) {
				return { tables: { nodes: [], totalCount: 0, pageInfo: EMPTY_PAGE_INFO } };
			}

			// Step 2: Fetch fields for all tables
			const tableIds = extractIds(tables);
			const fieldsResult = await fetchFieldsQuery({
				selection: {
					fields: { id: true, name: true, type: true, chk: true, chkExpr: true, defaultValue: true, description: true, fieldOrder: true, isRequired: true, label: true, max: true, min: true, regexp: true, smartTags: true, tableId: true },
					where: { tableId: { in: tableIds } },
				},
			});

			// Step 3: Build result with nested fields
			const fieldsByTable = buildFieldsByTableMap((fieldsResult.fields?.nodes ?? []) as Field[]);
			const tableNodes = tables.map((t) => transformTable(t as Table, fieldsByTable.get(t.id ?? '') ?? []));

			return {
				tables: {
					nodes: tableNodes,
					totalCount: tablesResult.tables?.totalCount ?? 0,
					pageInfo: {
						hasNextPage: tablesResult.tables?.pageInfo?.hasNextPage ?? false,
						hasPreviousPage: tablesResult.tables?.pageInfo?.hasPreviousPage ?? false,
					},
				},
			};
		},
		enabled: enabled && !!databaseId,
		staleTime: 5 * 60 * 1000,
	});

	return {
		tables: data?.tables?.nodes ?? [],
		totalCount: data?.tables?.totalCount ?? 0,
		isLoading,
		error,
		pageInfo: data?.tables?.pageInfo ?? EMPTY_PAGE_INFO,
		refetch,
	};
}

/**
 * Hook for fetching a single table by ID
 */
export function useDatabaseTable(tableId: string, enabled = true) {
	const { scope } = useSchemaBuilderRuntime();
	const { fetchFieldsQuery, fetchTableQuery } = useSchemaBuilderSdkClient();
	return useQuery<DatabaseTableNode | null, Error>({
		queryKey: schemaBuilderQueryKey(scope, 'core', 'databaseTable', { tableId }),
		queryFn: async (): Promise<DatabaseTableNode | null> => {
			const tableResult = await fetchTableQuery({
				id: tableId,
				selection: {
					fields: { id: true, name: true, label: true, description: true, pluralName: true, singularName: true, smartTags: true, timestamps: true, databaseId: true, schemaId: true, category: true },
				},
			});
			const table = tableResult.table;
			if (!table) return null;

			const fieldsResult = await fetchFieldsQuery({
				selection: {
					fields: { id: true, name: true, type: true, chk: true, chkExpr: true, defaultValue: true, description: true, fieldOrder: true, isRequired: true, label: true, max: true, min: true, regexp: true, smartTags: true, tableId: true },
					where: { tableId: { equalTo: tableId } },
				},
			});

			const fields = ((fieldsResult.fields?.nodes ?? []) as Field[]).map(transformField);
			return transformTable(table as Table, fields);
		},
		enabled: enabled && !!tableId,
		staleTime: 5 * 60 * 1000,
	});
}

/**
 * Query keys for cache management
 */
export const databaseTablesQueryKeys = {
	all: ['database-tables'] as const,
	byDatabase: (databaseId: string) => [...databaseTablesQueryKeys.all, { databaseId }] as const,
	byDatabaseWithOptions: (databaseId: string, options: Omit<UseDatabaseTablesOptions, 'databaseId'>) =>
		[...databaseTablesQueryKeys.byDatabase(databaseId), options] as const,
};

/**
 * Schema Builder Selectors Hook
 *
 * This hook provides derived state by combining:
 * 1. React Query data from SchemaBuilderDataProvider
 * 2. Zustand selection state (selectedSchemaKey, selectedTableId, etc.)
 *
 * All derived values are computed via useMemo - nothing is stored redundantly.
 * This eliminates the sync layer that caused race conditions.
 */
import { createElement, useCallback, useMemo, type ReactNode } from 'react';
import * as FluentContextSelector from '@fluentui/react-context-selector';

const fluentContextSelector = (
	FluentContextSelector as typeof FluentContextSelector & { default?: typeof FluentContextSelector }
).default ?? FluentContextSelector;
const { createContext, useContextSelector } = fluentContextSelector;

import type { DbLightSchema, FieldDefinition, SchemaData, TableDefinition } from '../../../schema';
import { dbLightToSchemaData } from '../../../schema';
import type { CurrentDatabaseApi, SchemaInfo as StoreSchemaInfo } from '../../../../store/schema-slice';
import {
	useSchemaBuilderConfig,
	useSchemaBuilderRuntime,
	useSchemaBuilderRuntimeStore,
} from '@/components/schema-builder/compat/block-config';

import { transformUserDatabases } from './transformers/transformers';
import { useAccessibleDatabases } from './use-accessible-databases';
import { useDatabaseConstraints } from './use-database-constraints';

// Re-export types for convenience
export type { CurrentDatabaseApi, StoreSchemaInfo };

export interface SchemaInfo {
	key: string;
	name: string;
	description: string;
	category: string;
	nodeCount: number;
	edgeCount: number;
	source: 'custom' | 'database';
	schema: SchemaData;
	dbSchema?: DbLightSchema;
	checksum?: string;
	databaseInfo?: {
		id: string;
		name: string;
		label?: string | null;
		schemaId?: string | null;
		ownerName?: string;
		ownerId?: string;
		tableCount: number;
		fieldCount: number;
	};
}

export interface CurrentDatabaseInfo {
	schemaKey: string;
	databaseId: string;
	name: string;
	label: string | null;
	schemaId: string | null;
}

const EMPTY_STORE_SCHEMAS: StoreSchemaInfo[] = [];
const EMPTY_SCHEMAS: SchemaInfo[] = EMPTY_STORE_SCHEMAS;
const NOOP_SELECT_ORG = (_orgId: string | null): void => undefined;
const NOOP_SELECT_SCHEMA = (_schemaKey: string): void => undefined;
const NOOP_SET_ACTIVE_TAB = (_tab: 'diagram' | 'schemas'): void => undefined;
const IS_CUSTOM_SCHEMA = (schemaKey: string) => schemaKey.startsWith('custom-');

export interface SchemaBuilderDataState {
	availableSchemas: SchemaInfo[];
	routeOrgId: string | null;
	routeDatabaseId: string | null;
	selectedSchemaKey: string;
	currentSchemaInfo: SchemaInfo | null;
	currentSchema: DbLightSchema | null;
	currentTable: TableDefinition | null;
	selectedTableId: string | null;
	hasResolvedDatabaseLookup: boolean;
	isLoading: boolean;
	isFetching: boolean;
	error: Error | null;
	refetch: () => Promise<unknown>;
	selectTable: (tableId: string | null, tableName?: string | null) => void;
}

const SchemaBuilderDataContext = createContext<SchemaBuilderDataState | null>(null);

export interface SchemaBuilderDataProviderProps {
	children: ReactNode;
	value?: SchemaBuilderDataState;
}

export function SchemaBuilderDataProvider({ children, value }: SchemaBuilderDataProviderProps) {
	if (value) {
		return createElement(SchemaBuilderDataContext.Provider, { value }, children);
	}

	return createElement(SchemaBuilderQueryDataProvider, null, children);
}

function SchemaBuilderQueryDataProvider({ children }: { children: ReactNode }) {
	const { databaseId, orgId } = useSchemaBuilderConfig();
	const shouldLoadFullSchemaData = Boolean(databaseId);

	const {
		databases,
		hasResolved: hasResolvedAccessibleDatabases,
		isLoading: dbLoading,
		isFetching: dbFetching,
		error: dbError,
		refetch: refetchDatabases,
	} = useAccessibleDatabases({ enabled: shouldLoadFullSchemaData });

	const {
		primaryKeyConstraints,
		uniqueConstraints,
		foreignKeyConstraints,
		indexes,
		isLoading: constraintsLoading,
		isFetching: constraintsFetching,
		error: constraintsError,
	} = useDatabaseConstraints({ enabled: shouldLoadFullSchemaData });

	const remoteSchemas = useMemo<SchemaInfo[]>(() => {
		if (!shouldLoadFullSchemaData) return EMPTY_SCHEMAS;
		const transformed = transformUserDatabases(
			databases,
			primaryKeyConstraints,
			uniqueConstraints,
			foreignKeyConstraints,
			indexes,
		);

		return transformed.map((entry) => ({
			key: entry.key,
			name: entry.dbSchema.name,
			description: entry.description ?? entry.dbSchema.description ?? '',
			category: entry.category ?? 'Database',
			nodeCount: entry.dbSchema.tables.length,
			edgeCount: entry.dbSchema.relationships?.length ?? 0,
			source: 'database' as const,
			schema: dbLightToSchemaData(entry.dbSchema),
			dbSchema: entry.dbSchema,
			checksum: entry.checksum,
			databaseInfo: entry.databaseInfo,
		}));
	}, [
		databases,
		foreignKeyConstraints,
		indexes,
		primaryKeyConstraints,
		shouldLoadFullSchemaData,
		uniqueConstraints,
	]);

	const storeSelectedTableId = useSchemaBuilderRuntimeStore((state) => state.selectedTableId);
	const { selectTable: storeSelectTable } = useSchemaBuilderRuntime();

	const resolvedAvailableSchemas = shouldLoadFullSchemaData ? remoteSchemas : EMPTY_SCHEMAS;
	const hasResolvedDatabaseLookup = !databaseId ? true : hasResolvedAccessibleDatabases;
	const isLoading = shouldLoadFullSchemaData
		? !hasResolvedAccessibleDatabases || dbLoading || constraintsLoading
		: false;
	const isFetching = shouldLoadFullSchemaData ? dbFetching || constraintsFetching : false;
	const error = shouldLoadFullSchemaData ? dbError || constraintsError : null;

	const selectedSchemaKey = useMemo(() => {
		if (!databaseId) return '';
		return resolvedAvailableSchemas.find((schema) => schema.databaseInfo?.id === databaseId)?.key ?? '';
	}, [resolvedAvailableSchemas, databaseId]);

	const currentSchemaInfo = useMemo(
		() => resolvedAvailableSchemas.find((schema) => schema.key === selectedSchemaKey) ?? null,
		[resolvedAvailableSchemas, selectedSchemaKey],
	);

	const currentSchema = currentSchemaInfo?.dbSchema ?? null;

	const selectedTableId = storeSelectedTableId;

	const currentTable = useMemo(
		() => currentSchema?.tables.find((table) => table.id === selectedTableId) ?? null,
		[currentSchema, selectedTableId],
	);

	const selectTable = useCallback(
		(tableId: string | null, tableName?: string | null) => {
			storeSelectTable(tableId, tableName);
		},
		[storeSelectTable],
	);

	const refetch = useCallback(async () => {
		if (shouldLoadFullSchemaData) await refetchDatabases();
	}, [refetchDatabases, shouldLoadFullSchemaData]);

	const value = useMemo(
		() => ({
			availableSchemas: resolvedAvailableSchemas,
			routeOrgId: orgId,
			routeDatabaseId: databaseId,
			selectedSchemaKey,
			currentSchemaInfo,
			currentSchema,
			currentTable,
			selectedTableId,
			hasResolvedDatabaseLookup,
			isLoading,
			isFetching,
			error,
			refetch,
			selectTable,
		}),
		[
			resolvedAvailableSchemas,
			orgId,
			databaseId,
			selectedSchemaKey,
			currentSchemaInfo,
			currentSchema,
			currentTable,
			selectedTableId,
			hasResolvedDatabaseLookup,
			isLoading,
			isFetching,
			error,
			refetch,
			selectTable,
		],
	);

	return createElement(SchemaBuilderDataContext.Provider, { value }, children);
}

export function useSchemaBuilderDataSelector<T>(selector: (state: SchemaBuilderDataState) => T): T {
	return useContextSelector(SchemaBuilderDataContext, (state) => {
		if (!state) {
			throw new Error('SchemaBuilderDataProvider is missing');
		}
		return selector(state);
	});
}

export interface UseSchemaBuilderSelectorsResult {
	// === Entity Selection State (from Zustand) ===
	selectedOrgId: string | null;
	selectedSchemaKey: string; // database key
	selectedTableId: string | null;
	selectedFieldId: string | null;
	activeTab: 'diagram' | 'schemas';

	// === Entity Selection Actions (from Zustand, with cascade clearing) ===
	selectOrg: (orgId: string | null) => void;
	selectSchema: (schemaKey: string) => void;
	selectTable: (tableId: string | null, tableName?: string | null) => void;
	selectField: (fieldId: string | null) => void;
	clearAllSelections: () => void;
	setActiveTab: (tab: 'diagram' | 'schemas') => void;

	// === Derived Data (computed, not stored) ===
	availableSchemas: SchemaInfo[];
	currentSchema: DbLightSchema | null;
	currentTable: TableDefinition | null;
	currentField: FieldDefinition | null;
	currentDatabase: CurrentDatabaseInfo | null;

	// === API State (from Zustand, fetched separately) ===
	currentDatabaseApi: CurrentDatabaseApi | null;
	setCurrentDatabaseApi: (api: CurrentDatabaseApi | null) => void;

	// === Computed Helpers ===
	isCustomSchema: (schemaKey: string) => boolean;
	getSchemaByKey: (key: string) => SchemaInfo | null;

	// === Loading/Error State ===
	/** True only on initial load (no cached data yet). Use for blocking UI. */
	isLoading: boolean;
	/** True during any fetch (including background refetch). Use for syncing indicators. */
	isFetching: boolean;
	error: Error | null;
	refetch: () => Promise<unknown>;

	// === Custom Schemas (localStorage-backed, kept in Zustand) ===
	customSchemas: SchemaInfo[];
}

export function useSchemaBuilderSelectors(): UseSchemaBuilderSelectorsResult {
	// 1. Instance-scoped state. Entity scope itself remains host controlled.
	const {
		scope,
		store,
		selectField: selectFieldFromContext,
		selectTable: selectTableFromContext,
	} = useSchemaBuilderRuntime();
	const selectedFieldId = useSchemaBuilderRuntimeStore((state) => state.selectedFieldId);
	const currentDatabaseApi = useSchemaBuilderRuntimeStore((state) => state.currentDatabaseApi) as CurrentDatabaseApi | null;
	const selectedOrgId = scope.orgId;
	const activeTab = 'schemas' as const;
	const customSchemas = EMPTY_SCHEMAS;
	const selectOrg = NOOP_SELECT_ORG;
	const selectSchema = NOOP_SELECT_SCHEMA;
	const selectField = useCallback(
		(fieldId: string | null) => selectFieldFromContext(fieldId),
		[selectFieldFromContext],
	);
	const clearAllSelections = useCallback(() => {
		selectTableFromContext(null);
		selectFieldFromContext(null);
	}, [selectTableFromContext, selectFieldFromContext]);
	const setActiveTab = NOOP_SET_ACTIVE_TAB;
	const setCurrentDatabaseApi = useCallback(
		(api: CurrentDatabaseApi | null) => store.getState().setCurrentDatabaseApi(api),
		[store],
	);

	// 2. Get server + selection data from provider (computed once per tree)
	const availableSchemas = useSchemaBuilderDataSelector((state) => state.availableSchemas);
	const selectedSchemaKey = useSchemaBuilderDataSelector((state) => state.selectedSchemaKey);
	const currentSchemaInfo = useSchemaBuilderDataSelector((state) => state.currentSchemaInfo);
	const currentSchema = useSchemaBuilderDataSelector((state) => state.currentSchema);
	const currentTable = useSchemaBuilderDataSelector((state) => state.currentTable);
	const selectedTableId = useSchemaBuilderDataSelector((state) => state.selectedTableId);
	const isLoading = useSchemaBuilderDataSelector((state) => state.isLoading);
	const isFetching = useSchemaBuilderDataSelector((state) => state.isFetching);
	const error = useSchemaBuilderDataSelector((state) => state.error);
	const refetch = useSchemaBuilderDataSelector((state) => state.refetch);
	const selectTableFromProvider = useSchemaBuilderDataSelector((state) => state.selectTable);

	// 3. Derive current field (computed, not stored)
	const currentField = useMemo(
		() => currentTable?.fields.find((f) => f.id === selectedFieldId) ?? null,
		[currentTable, selectedFieldId],
	);

	// 8. Derive current database info (computed, not stored)
	const currentDatabase = useMemo<CurrentDatabaseInfo | null>(() => {
		if (!currentSchemaInfo?.databaseInfo) return null;
		return {
			schemaKey: selectedSchemaKey,
			databaseId: currentSchemaInfo.databaseInfo.id,
			name: currentSchemaInfo.databaseInfo.name,
			label: currentSchemaInfo.databaseInfo.label ?? null,
			schemaId: currentSchemaInfo.databaseInfo.schemaId ?? null,
		};
	}, [currentSchemaInfo, selectedSchemaKey]);

	// 9. Helper functions
	const isCustomSchema = IS_CUSTOM_SCHEMA;

	const getSchemaByKey = useCallback(
		(key: string) => availableSchemas.find((schema) => schema.key === key) ?? null,
		[availableSchemas],
	);

	// 10. Wrapped selection actions that clear dependent selections
	const selectTable = useCallback(
		(tableId: string | null, tableName?: string | null) => {
			selectTableFromProvider(tableId, tableName);
			// Always clear field selection when selecting a table
			selectField(null);
		},
		[selectTableFromProvider, selectField],
	);

	return {
		// Entity selection state
		selectedOrgId,
		selectedSchemaKey,
		selectedTableId,
		selectedFieldId,
		activeTab,

		// Entity selection actions (with cascade clearing)
		selectOrg,
		selectSchema,
		selectTable,
		selectField,
		clearAllSelections,
		setActiveTab,

		// Derived data
		availableSchemas,
		currentSchema,
		currentTable,
		currentField,
		currentDatabase,

		// API state (from Zustand)
		currentDatabaseApi,
		setCurrentDatabaseApi,

		// Helpers
		isCustomSchema,
		getSchemaByKey,

		// Loading/error
		isLoading,
		isFetching,
		error,
		refetch,

		// Custom schemas
		customSchemas,
	};
}

export interface UseVisualizerSchemaOptions {
	/** Show CORE/MODULE tables in addition to APP tables. Default: false */
	showSystemTables?: boolean;
}

/**
 * Hook to get visualizer schema data.
 * Computed from currentSchema - call this only where needed (visualizer components).
 *
 * @param options.showSystemTables - If true, include CORE/MODULE tables. Default: false (only APP tables)
 */
export function useVisualizerSchema(options?: UseVisualizerSchemaOptions): SchemaData | null {
	const { currentSchema } = useSchemaBuilderSelectors();
	const { showSystemTables = false } = options ?? {};

	return useMemo(() => {
		if (!currentSchema) return null;

		// Determine which categories to include
		const includeCategories: ('APP' | 'MODULE' | 'CORE')[] = showSystemTables ? ['APP', 'MODULE', 'CORE'] : ['APP'];

		return dbLightToSchemaData(currentSchema, { includeCategories });
	}, [currentSchema, showSystemTables]);
}

/**
 * Hook to get constraint information for a table.
 * Useful for field-level operations.
 */
export function useTableConstraints(tableId: string | null) {
	const { currentSchema } = useSchemaBuilderSelectors();

	return useMemo(() => {
		if (!tableId || !currentSchema) {
			return {
				primaryKey: null,
				uniqueConstraints: [],
				foreignKeyConstraints: [],
				indexes: [],
			};
		}

		const table = currentSchema.tables.find((t) => t.id === tableId);
		if (!table) {
			return {
				primaryKey: null,
				uniqueConstraints: [],
				foreignKeyConstraints: [],
				indexes: [],
			};
		}

		const constraints = table.constraints ?? [];
		let primaryKey = null;
		const uniqueConstraints = [];
		const foreignKeyConstraints = [];

		for (const c of constraints) {
			if (c.type === 'primary_key') primaryKey = c;
			else if (c.type === 'unique') uniqueConstraints.push(c);
			else if (c.type === 'foreign_key') foreignKeyConstraints.push(c);
		}

		return {
			primaryKey,
			uniqueConstraints,
			foreignKeyConstraints,
			indexes: table.indexes ?? [],
		};
	}, [tableId, currentSchema]);
}

/**
 * Hook for fetching databases owned by the current authenticated user
 * Tier 4 wrapper: Uses SDK hooks + composition
 */
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useAuthSdkClient,
	useSchemaBuilderSdkClient,
	useSchemaBuilderRuntime,
} from '@/components/schema-builder/compat/block-config';

import type { SchemaContext } from '../../../../app-config';
import {
	type Field,
	type Table,
} from '@/components/schema-builder/compat/schema-builder-sdk';

import {
	type DatabaseTableNode,
	type DatabaseFieldNode,
	type DatabaseOwnerNode,
	type DatabaseSchemaNode,
	type DatabaseApiNode,
	buildFieldsByTableMap,
	buildTablesByDatabaseMap,
	extractIds,
} from './database-shared-utils';
import { parseListField } from './parse-list-field';

// Re-export shared types for backwards compatibility
