export const and = (...args: Node[]) =>
	nodes.boolExpr({
		boolop: 'AND_EXPR',
		args,
	});

export const or = (...args: Node[]) =>
	nodes.boolExpr({
		boolop: 'OR_EXPR',
		args,
	});

function mapLeafToAstNode(leaf: ConditionLeafNode<PolicyConditionData>): Node | null {
	const policyTypeId = leaf.data.policyType as PolicyTypeId;
	const astNode = getAstNodeForPolicyType(policyTypeId, leaf.data.data as Record<string, unknown>);
	if (!astNode) return null;

	const data = sanitizePolicyTypeData(policyTypeId, (leaf.data.data || {}) as Record<string, unknown>);

	return {
		[astNode]: data,
	} as unknown as Node;
}

export function mapConditionNodeToAst(
	node: ConditionGroupNode<PolicyConditionData> | ConditionLeafNode<PolicyConditionData>,
): Node | null {
	if (node.type === 'condition') {
		return mapLeafToAstNode(node);
	}

	const childExprs = node.children
		.map((child) => mapConditionNodeToAst(child))
		.filter((child): child is Node => child !== null);

	if (childExprs.length === 0) return null;
	if (childExprs.length === 1) return childExprs[0];

	return node.operator === 'AND' ? and(...childExprs) : or(...childExprs);
}

import { POLICY_TYPE_UI_CONFIG, type PolicyTypeId } from '../../components/policies/policy-config';

export type { PolicyTypeId };

const UI_POLICY_TYPE_DISCRIMINATOR_KEY = '__ui_policy_type';

/**
 * Build reverse lookup: AST node name → policy type ID.
 * Used by the RLS parser to identify policy types from AST expressions.
 */
export const AST_NODE_TO_POLICY_TYPE: Record<string, PolicyTypeId> = Object.fromEntries(
	Object.keys(POLICY_TYPE_UI_CONFIG)
		.filter((name) => name !== 'AuthzComposite')
		.map((name) => [name, name as PolicyTypeId]),
);

/**
 * Map a backend policy type ID to a frontend PolicyTypeId.
 * Handles AuthzComposite and AuthzEntityMembership variant detection.
 */
export function fromBackendPolicyTypeId(
	backendPolicyTypeId: string,
	_data?: Record<string, unknown> | null,
): PolicyTypeId | 'AuthzComposite' | undefined {
	if (backendPolicyTypeId === 'AuthzComposite') return 'AuthzComposite';
	if (backendPolicyTypeId === 'AuthzEntityMembership') return 'AuthzEntityMembership';
	if (backendPolicyTypeId in POLICY_TYPE_UI_CONFIG) return backendPolicyTypeId as PolicyTypeId;
	return undefined;
}

/**
 * Map a frontend PolicyTypeId back to the backend policy type ID.
 */
export function toBackendPolicyTypeId(policyTypeId: PolicyTypeId | 'AuthzComposite'): string {
	if (policyTypeId === 'AuthzComposite') return 'AuthzComposite';
	return policyTypeId;
}

/**
 * Strip unknown keys from policy data based on the fieldOverrides for that policy type.
 * Preserves the UI discriminator key and auto-injected schema fields.
 */
export function sanitizePolicyTypeData(
	policyTypeId: PolicyTypeId,
	data: Record<string, unknown>,
): Record<string, unknown> {
	const config = POLICY_TYPE_UI_CONFIG[policyTypeId];
	if (!config?.fieldOverrides) return data;

	const allowedKeys = new Set(Object.keys(config.fieldOverrides));
	allowedKeys.add(UI_POLICY_TYPE_DISCRIMINATOR_KEY);

	const filtered: Record<string, unknown> = {};
	for (const key of Object.keys(data)) {
		if (allowedKeys.has(key)) {
			filtered[key] = data[key];
		}
	}
	return filtered;
}

/**
 * Get the AST node name for a policy type, resolving backend ID if needed.
 */
export function getAstNodeForPolicyType(
	policyTypeId: string,
	data?: Record<string, unknown> | null,
): string | undefined {
	const frontendId = fromBackendPolicyTypeId(policyTypeId, data) ?? (policyTypeId as PolicyTypeId);
	if (frontendId === 'AuthzComposite') return undefined;
	return frontendId in POLICY_TYPE_UI_CONFIG ? frontendId : undefined;
}

/**
 * Builders for the `grants[]` / `policies[]` jsonb arrays expected by
 * `secure_table_provision` and `relation_provision`.
 *
 * The backend replaced its scalar policy/grant columns with jsonb arrays,
 * so one provision call can now install multiple grants and policies atomically.
 */
import type { CrudOperation, CrudPolicyConfigs } from '../../components/policies/policy-types';

/** A single privilege clause: [verb, '*'] or [verb, ['col_a','col_b']]. All lowercase. */
export type GrantPrivilege = [string, string | string[]];

/** One entry in a `grants[]` array: all listed roles get the listed privileges. */
export interface GrantEntry {
	roles: string[];
	privileges: GrantPrivilege[];
}

/** One entry in a `policies[]` array. Only `$type` is required; backend fills defaults. */
export interface PolicyEntry {
	$type: string;
	data?: Record<string, unknown>;
	privileges?: string[];
	policy_role?: string;
	permissive?: boolean;
	policy_name?: string;
}

/** Full-CRUD grant on all columns. */
export const ALL_CRUD_PRIVILEGES: GrantPrivilege[] = [
	['select', '*'],
	['insert', '*'],
	['update', '*'],
	['delete', '*'],
];

const CRUD_OP_TO_LOWER_PRIVILEGE: Record<CrudOperation, string> = {
	create: 'insert',
	read: 'select',
	update: 'update',
	delete: 'delete',
};

/** Convert a CRUD op (`'read'`, `'create'`, …) to the lowercase privilege verb the backend expects. */
export function crudOpToPrivilege(op: CrudOperation): string {
	return CRUD_OP_TO_LOWER_PRIVILEGE[op];
}

/** Convert many CRUD ops to their lowercase privilege verbs. */
export function crudOpsToPrivileges(ops: readonly CrudOperation[]): string[] {
	return ops.map(crudOpToPrivilege);
}

/**
 * Build a single-entry `grants[]` array: one role group with the given privileges.
 * Defaults to `['authenticated']` with full-CRUD on all columns.
 */
export function buildGrants(
	roles: string[] = ['authenticated'],
	privileges: GrantPrivilege[] = ALL_CRUD_PRIVILEGES,
): GrantEntry[] {
	return [{ roles, privileges }];
}

/**
 * Build a single `policies[]` entry. Only `$type` is required; other fields are omitted
 * when falsy/empty so the backend defaults kick in.
 */
export function buildPolicyEntry(
	type: string,
	opts: Partial<Omit<PolicyEntry, '$type'>> = {},
): PolicyEntry {
	const entry: PolicyEntry = { $type: type };
	if (opts.data && Object.keys(opts.data).length > 0) entry.data = opts.data;
	if (opts.privileges && opts.privileges.length > 0) entry.privileges = opts.privileges;
	if (opts.policy_role) entry.policy_role = opts.policy_role;
	if (opts.permissive !== undefined) entry.permissive = opts.permissive;
	if (opts.policy_name) entry.policy_name = opts.policy_name;
	return entry;
}

/** Group of CRUD operations sharing the same (role, permissive) tuple — one entry in `policies[]`. */
export interface OperationGroup {
	roleName: string;
	isPermissive: boolean;
	/** Lowercase privilege verbs (select, insert, update, delete). */
	privileges: string[];
}

/**
 * Group enabled CRUD operations by (roleName, isPermissive). Each distinct group
 * becomes one `policies[]` entry, since the backend models them as separate policies.
 */
export function groupOperationsByConfig(
	enabledOperations: readonly CrudOperation[],
	operations: CrudPolicyConfigs,
): OperationGroup[] {
	const groupMap = new Map<string, OperationGroup>();

	for (const op of enabledOperations) {
		const config = operations[op];
		const key = `${config.roleName}:${config.isPermissive}`;

		let group = groupMap.get(key);
		if (!group) {
			group = { roleName: config.roleName, isPermissive: config.isPermissive, privileges: [] };
			groupMap.set(key, group);
		}
		group.privileges.push(...crudOpsToPrivileges([op]));
	}

	return [...groupMap.values()];
}

import type {
	ConditionGroupNode,
	ConditionLeafNode,
	ConditionLogicalOperator,
	ConditionNode,
	PolicyConditionData,
} from '../../components/policies/condition-builder/types';

import { AST_NODE_TO_POLICY_TYPE, fromBackendPolicyTypeId, type PolicyTypeId } from './policy-type-utils';

type AstNode = Record<string, unknown>;

class IdGenerator {
	private counter = 1;
	next(): string {
		return `c-${this.counter++}`;
	}
}

class MembershipByFieldParser implements NodeParser {
	canParse(tag: string): boolean {
		return tag === 'AuthzEntityMembership';
	}

	parse(node: AstNode, tag: string, idGen: IdGenerator): ConditionLeafNode<PolicyConditionData> {
		const data = node[tag] as Record<string, unknown>;
		const policyTypeId = fromBackendPolicyTypeId('AuthzEntityMembership', data) ?? 'OwnedRecords';

		return {
			id: idGen.next(),
			type: 'condition',
			data: {
				policyType: policyTypeId,
				data: { ...data },
			},
		};
	}
}

interface NodeParser {
	canParse(tag: string): boolean;
	parse(node: AstNode, tag: string, idGen: IdGenerator): ConditionNode<PolicyConditionData> | null;
}

class RlsNodeParser implements NodeParser {
	canParse(tag: string): boolean {
		return tag in AST_NODE_TO_POLICY_TYPE;
	}

	parse(node: AstNode, tag: string, idGen: IdGenerator): ConditionLeafNode<PolicyConditionData> {
		const policyTypeId = AST_NODE_TO_POLICY_TYPE[tag];
		const data = node[tag] as Record<string, unknown>;

		return {
			id: idGen.next(),
			type: 'condition',
			data: {
				policyType: policyTypeId,
				data: { ...data },
			},
		};
	}
}

class BoolExprParser implements NodeParser {
	constructor(private transformer: AstToConditionTransformer) {}

	canParse(tag: string): boolean {
		return tag === 'BoolExpr';
	}

	parse(node: AstNode, _tag: string, idGen: IdGenerator): ConditionNode<PolicyConditionData> | null {
		const data = node['BoolExpr'] as { boolop: string; args: AstNode[] };
		const operator: ConditionLogicalOperator = data.boolop === 'AND_EXPR' ? 'AND' : 'OR';
		const args = data.args || [];

		const children: ConditionNode<PolicyConditionData>[] = [];
		for (const arg of args) {
			const child = this.transformer.transformNode(arg, idGen);
			if (child) children.push(child);
		}

		if (children.length === 0) return null;
		if (children.length === 1) return children[0];

		return {
			id: idGen.next(),
			type: 'group',
			operator,
			children,
		};
	}
}

class AstToConditionTransformer {
	private parsers: NodeParser[];

	constructor() {
		this.parsers = [new MembershipByFieldParser(), new RlsNodeParser(), new BoolExprParser(this)];
	}

	private getNodeTag(node: AstNode): string | null {
		const keys = Object.keys(node);
		if (keys.length === 1 && /^[A-Z]/.test(keys[0])) {
			return keys[0];
		}
		return null;
	}

	transformNode(node: AstNode, idGen: IdGenerator): ConditionNode<PolicyConditionData> | null {
		const tag = this.getNodeTag(node);
		if (!tag) return null;

		for (const parser of this.parsers) {
			if (parser.canParse(tag)) {
				return parser.parse(node, tag, idGen);
			}
		}
		return null;
	}

	transform(ast: AstNode): ConditionGroupNode<PolicyConditionData> {
		const idGen = new IdGenerator();
		const result = this.transformNode(ast, idGen);

		if (!result) {
			return { id: 'root', type: 'group', operator: 'AND', children: [] };
		}

		if (result.type === 'group') {
			return { ...result, id: 'root' };
		}

		return { id: 'root', type: 'group', operator: 'AND', children: [result] };
	}
}

const transformer = new AstToConditionTransformer();

export function mapAstToConditionNode(ast: AstNode): ConditionGroupNode<PolicyConditionData> {
	return transformer.transform(ast);
}

