/**
 * Schema Slice - Entity Selection & UI State
 *
 * NOTE: URL is the SOURCE OF TRUTH for entity selection.
 * Entity IDs (org, database) are read from URL path params via useEntityParams hook.
 * This Zustand slice provides:
 * 1. A sync target for layouts to write URL state to (for legacy components)
 * 2. Actions for entity selection that can be called during transition
 * 3. Non-URL state like selectedTable, activeTab, searchParams
 *
 * Entity Hierarchy (selection cascade):
 * - App (root) → Org → Database → Table → Field
 * - Selecting a parent clears all child selections
 *
 * URL Path Params (source of truth):
 * - orgId: from /orgs/[orgId]/*
 * - databaseId: from /orgs/[orgId]/databases/[databaseId]/*
 *
 * Zustand State (synced from URL or UI-only):
 * - selectedOrgId, selectedSchemaKey: synced from URL by layouts
 * - selectedTable, selectedField: UI state (will migrate to URL query params)
 * - activeTab, searchParams: UI state (will migrate to URL query params)
 * - customSchemas: localStorage-backed user schemas
 * - currentDatabaseApi: runtime state (fetched separately)
 *
 * What's NOT stored here (derived via selectors):
 * - availableSchemas, currentSchema, currentTable, currentField, currentDatabase
 */
import { StateCreator } from 'zustand';

import type { DbLightSchema, SchemaData } from '../lib/schema';
import { dbLightToSchemaData } from '../lib/schema';

// Custom schema storage key
const CUSTOM_SCHEMAS_STORAGE_KEY = 'constructive-custom-schemas';

// Schema source types
type SchemaSource = 'custom' | 'database';

const logger = {
	warn: (...args: unknown[]) => console.warn('[schema-slice]', ...args),
	error: (...args: unknown[]) => console.error('[schema-slice]', ...args),
};

export interface SchemaInfo {
	key: string;
	name: string;
	description: string;
	category: string;
	nodeCount: number;
	edgeCount: number;
	source: SchemaSource;
	schema: SchemaData;
	dbSchema?: DbLightSchema;
	checksum?: string;
	databaseInfo?: {
		id: string;
		name: string;
		label?: string | null;
		schemaId?: string | null;
		ownerName?: string;
		ownerId?: string;
		tableCount: number;
		fieldCount: number;
	};
}

export interface CurrentDatabaseApi {
	id: string;
	name: string;
	url: string | null;
	domain?: string | null;
	subdomain?: string | null;
	isPublic?: boolean | null;
}

export interface SchemaSlice {
	// === Entity Selection State (hierarchy: org → database) ===
	selectedOrgId: string | null;
	selectedSchemaKey: string; // database key

	// === Schema Selection State (within database: table → field) ===
	selectedTable: string | null;
	selectedField: string | null;
	activeTab: 'diagram' | 'schemas';

	// === Search Params State ===
	searchParams: {
		search: string | null;
		sort: string;
		order: 'asc' | 'desc';
		page: number;
		limit: number;
		selected: string[] | null;
	};

	// === Custom Schemas (localStorage-backed) ===
	customSchemas: SchemaInfo[];

	// === API State (fetched separately, not derivable from schema) ===
	currentDatabaseApi: CurrentDatabaseApi | null;

	// === Entity Selection Actions (with cascade clearing) ===
	selectOrg: (orgId: string | null) => void;
	selectSchema: (schemaKey: string) => void;
	selectTable: (tableId: string | null) => void;
	selectField: (fieldId: string | null) => void;
	clearAllSelections: () => void;
	setActiveTab: (tab: 'diagram' | 'schemas') => void;

	// === Search Params Actions ===
	setSearch: (search: string | null) => void;
	setSorting: (sort: string, order?: 'asc' | 'desc') => void;
	setPage: (page: number) => void;
	setLimit: (limit: number) => void;
	setSelected: (selected: string[] | null) => void;
	clearFilters: () => void;

	// === Custom Schema Actions ===
	createCustomSchema: (name: string) => void;
	deleteCustomSchema: (schemaKey: string) => void;

	// === API State Actions ===
	setCurrentDatabaseApi: (api: CurrentDatabaseApi | null) => void;

	// === Computed Properties ===
	isCustomSchema: (schemaKey: string) => boolean;
	hasActiveFilters: boolean;
	selectedCount: number;

	// === Internal Helpers ===
	_loadCustomSchemas: () => SchemaInfo[];
	_saveCustomSchema: (key: string, dbSchema: DbLightSchema) => void;
	_deleteCustomSchemaFromStorage: (key: string) => void;
	_refreshCustomSchemas: () => void;
}

// Helper function to load custom schemas from localStorage
const loadCustomSchemasFromStorage = (): SchemaInfo[] => {
	if (typeof window === 'undefined') return [];

	try {
		const stored = localStorage.getItem(CUSTOM_SCHEMAS_STORAGE_KEY);
		if (!stored) return [];

		const parsed = JSON.parse(stored) as Record<string, DbLightSchema>;
		return Object.entries(parsed).map(([key, dbSchema]) => {
			const schemaData = dbLightToSchemaData(dbSchema);
			return {
				key,
				name: dbSchema.name,
				description: dbSchema.description || '',
				category: dbSchema.metadata?.tags?.[0] || 'Custom',
				nodeCount: dbSchema.tables.length,
				edgeCount: dbSchema.relationships?.length || 0,
				source: 'custom' as const,
				schema: schemaData,
				dbSchema,
			};
		});
	} catch (error) {
		logger.warn('Failed to load custom schemas', { error });
		return [];
	}
};

export const createSchemaSlice: StateCreator<SchemaSlice, [], [], SchemaSlice> = (set, get) => {
	// Initialize custom schemas from localStorage
	const customSchemas = loadCustomSchemasFromStorage();

	return {
		// === Initial Entity Selection State ===
		selectedOrgId: null,
		selectedSchemaKey: '',

		// === Initial Schema Selection State ===
		selectedTable: null,
		selectedField: null,
		activeTab: 'diagram',

		// === Initial Search Params State ===
		searchParams: {
			search: null,
			sort: 'name',
			order: 'asc',
			page: 1,
			limit: 20,
			selected: null,
		},
		customSchemas,
		currentDatabaseApi: null,

		// === Computed Properties ===
		isCustomSchema: (schemaKey: string) => {
			return schemaKey.startsWith('custom-');
		},

		hasActiveFilters: false,
		selectedCount: 0,

		// === Internal Helpers ===
		_loadCustomSchemas: () => {
			return loadCustomSchemasFromStorage();
		},

		_saveCustomSchema: (key: string, dbSchema: DbLightSchema) => {
			if (typeof window === 'undefined') return;

			try {
				const existing = localStorage.getItem(CUSTOM_SCHEMAS_STORAGE_KEY);
				const customSchemas = existing ? JSON.parse(existing) : {};

				customSchemas[key] = dbSchema;
				localStorage.setItem(CUSTOM_SCHEMAS_STORAGE_KEY, JSON.stringify(customSchemas));

				// Refresh custom schemas list
				get()._refreshCustomSchemas();
			} catch (error) {
				logger.error('Failed to save custom schema', { error });
			}
		},

		_deleteCustomSchemaFromStorage: (key: string) => {
			if (typeof window === 'undefined') return;

			try {
				const existing = localStorage.getItem(CUSTOM_SCHEMAS_STORAGE_KEY);
				if (!existing) return;

				const customSchemas = JSON.parse(existing);
				delete customSchemas[key];

				localStorage.setItem(CUSTOM_SCHEMAS_STORAGE_KEY, JSON.stringify(customSchemas));

				// Refresh custom schemas list
				get()._refreshCustomSchemas();
			} catch (error) {
				logger.error('Failed to delete custom schema', { error });
			}
		},

		_refreshCustomSchemas: () => {
			const customSchemas = loadCustomSchemasFromStorage();
			set({ customSchemas });
		},

		// === Entity Selection Actions (with cascade clearing) ===
		// Selecting a parent entity clears all child selections

		selectOrg: (orgId: string | null) => {
			set({
				selectedOrgId: orgId,
				// Clear all child selections when changing org
				selectedSchemaKey: '',
				selectedTable: null,
				selectedField: null,
			});
		},

		selectSchema: (schemaKey: string) => {
			// Guard: Skip if value hasn't changed
			if (get().selectedSchemaKey === schemaKey) return;
			set({
				selectedSchemaKey: schemaKey,
				// Clear table/field selection when switching schemas
				selectedTable: null,
				selectedField: null,
			});
		},

		selectTable: (tableId: string | null) => {
			// Guard: Skip if value hasn't changed
			if (get().selectedTable === tableId) return;
			set({
				selectedTable: tableId,
				// Clear field selection when switching tables
				selectedField: null,
			});
		},

		selectField: (fieldId: string | null) => {
			// Guard: Skip if value hasn't changed
			if (get().selectedField === fieldId) return;
			set({ selectedField: fieldId });
		},

		clearAllSelections: () => {
			set({
				selectedOrgId: null,
				selectedSchemaKey: '',
				selectedTable: null,
				selectedField: null,
			});
		},

		setActiveTab: (tab: 'diagram' | 'schemas') => {
			set({ activeTab: tab });
		},

		// === Search Params Actions ===
		setSearch: (search: string | null) => {
			const state = get();
			const newSearchParams = {
				...state.searchParams,
				search,
				page: 1, // Reset page when searching
			};
			const hasActiveFilters = !!(
				newSearchParams.search ||
				newSearchParams.sort !== 'name' ||
				newSearchParams.order !== 'asc' ||
				(newSearchParams.selected && newSearchParams.selected.length > 0)
			);
			set({
				searchParams: newSearchParams,
				hasActiveFilters,
			});
		},

		setSorting: (sort: string, order: 'asc' | 'desc' = 'asc') => {
			const state = get();
			const newSearchParams = {
				...state.searchParams,
				sort,
				order,
				page: 1, // Reset page when sorting
			};
			const hasActiveFilters = !!(
				newSearchParams.search ||
				newSearchParams.sort !== 'name' ||
				newSearchParams.order !== 'asc' ||
				(newSearchParams.selected && newSearchParams.selected.length > 0)
			);
			set({
				searchParams: newSearchParams,
				hasActiveFilters,
			});
		},

		setPage: (page: number) => {
			set({
				searchParams: {
					...get().searchParams,
					page,
				},
			});
		},

		setLimit: (limit: number) => {
			set({
				searchParams: {
					...get().searchParams,
					limit,
					page: 1, // Reset page when changing limit
				},
			});
		},

		setSelected: (selected: string[] | null) => {
			const state = get();
			const newSearchParams = {
				...state.searchParams,
				selected,
			};
			const hasActiveFilters = !!(
				newSearchParams.search ||
				newSearchParams.sort !== 'name' ||
				newSearchParams.order !== 'asc' ||
				(newSearchParams.selected && newSearchParams.selected.length > 0)
			);
			set({
				searchParams: newSearchParams,
				hasActiveFilters,
				selectedCount: selected?.length || 0,
			});
		},

		clearFilters: () => {
			const state = get();
			set({
				searchParams: {
					search: null,
					sort: 'name',
					order: 'asc',
					page: 1,
					selected: null,
					limit: state.searchParams.limit, // Keep limit
				},
				hasActiveFilters: false,
				selectedCount: 0,
			});
		},

		// === Custom Schema Actions ===
		createCustomSchema: (name: string) => {
			const key = `custom-${Date.now()}`;
			const dbSchema: DbLightSchema = {
				id: key,
				name,
				description: `Custom schema: ${name}`,
				version: '1.0.0',
				tables: [],
				relationships: [],
				metadata: {
					createdAt: new Date().toISOString(),
					updatedAt: new Date().toISOString(),
					author: 'Schema Builder',
					tags: ['Custom'],
				},
			};

			get()._saveCustomSchema(key, dbSchema);
			get().selectSchema(key);
		},

		deleteCustomSchema: (schemaKey: string) => {
			const state = get();

			get()._deleteCustomSchemaFromStorage(schemaKey);

			// If we're deleting the currently selected schema, clear selection
			if (state.selectedSchemaKey === schemaKey) {
				set({
					selectedSchemaKey: '',
					selectedTable: null,
					selectedField: null,
				});
			}
		},

		// === API State Actions ===
		setCurrentDatabaseApi: (api: CurrentDatabaseApi | null) => {
			set({ currentDatabaseApi: api });
		},
	};
};

/* ==== Serialization and deserialization ==== */
/**
 * What gets persisted to localStorage:
 *
 * NOT persisted (URL is source of truth):
 * - selectedOrgId - URL path params
 * - selectedSchemaKey - URL path param (databaseId)
 *
 * PERSISTED (non-URL state):
 * - selectedTable - will migrate to URL query param via nuqs
 * - activeTab - will migrate to URL query param via nuqs
 * - searchParams - will migrate to URL query params via nuqs
 * - currentDatabaseApi - runtime state, not derivable from URL
 * - customSchemas - stored separately in localStorage
 */
export const serializeSchemaSlice = (state: SchemaSlice) => ({
	// Only persist state that isn't in URL
	// Entity IDs (org, database) come from URL now
	selectedTable: state.selectedTable,
	// UI state - will eventually move to URL via nuqs
	activeTab: state.activeTab,
	searchParams: state.searchParams,
	currentDatabaseApi: state.currentDatabaseApi,
	// customSchemas are stored in localStorage separately
});

export const deserializeSchemaSlice = (state: SchemaSlice): Partial<SchemaSlice> => ({
	// Entity IDs start as null - URL will set them via layouts
	selectedOrgId: null,
	selectedSchemaKey: '',
	selectedTable: state.selectedTable,
	// UI state
	activeTab: state.activeTab || 'diagram',
	searchParams: state.searchParams || {
		search: null,
		sort: 'name',
		order: 'asc' as const,
		page: 1,
		limit: 20,
		selected: null,
	},
	currentDatabaseApi: state.currentDatabaseApi ?? null,
});

'use client';

import { useCallback, useMemo, useRef, useState, useEffect } from 'react';
import { ChevronsUpDownIcon, Loader2 } from 'lucide-react';

import type { CardComponent } from '@/components/ui/stack';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useCreateField, useUpdateField } from '../../lib/gql/hooks/schema-builder/use-field-mutations';
import type { CellType } from '@/components/schema-builder/schema/schema-builder-core/lib/types/cell-types';
import { cn } from '@/components/schema-builder/lib/utils';
import { Button } from '@/components/ui/button';
import {
	Combobox,
	ComboboxEmpty,
	ComboboxInput,
	ComboboxItem,
	ComboboxList,
	ComboboxPopup,
	ComboboxTrigger,
} from '@/components/ui/combobox';
import { Input } from '@/components/ui/input';
import { ScrollArea } from '@/components/ui/scroll-area';
import { toast } from '@/components/ui/toast';

import type { FieldConstraints, FieldDefinition } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { getAllFieldTypes, getFieldTypeInfo, updateCommonConstraint } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { ConstraintCard } from './constraint-card';
import { FormField, FormSection } from './form-field';
import { ValidationRulesSection, type ValidationRulesValues } from './validation-rules-section';

const fieldTypes = getAllFieldTypes();

export interface AddFieldCardProps {
	editingField: FieldDefinition | null;
	preSelectedType?: CellType | null;
	primaryKeyConstraintId?: string;
	uniqueConstraintId?: string;
	allPrimaryKeyFieldIds?: string[];
	isPartOfPrimaryKey?: boolean;
	remoteFields?: FieldDefinition[];
}

export const AddFieldCard: CardComponent<AddFieldCardProps> = ({
	editingField: initialEditingField,
	preSelectedType,
	primaryKeyConstraintId,
	uniqueConstraintId,
	allPrimaryKeyFieldIds = [],
	isPartOfPrimaryKey = false,
	remoteFields = [],
	card,
}) => {
	const { currentTable, currentSchema, currentDatabase } = useSchemaBuilderSelectors();

	const createFieldMutation = useCreateField();
	const updateFieldMutation = useUpdateField();

	// Form state - use lazy initial state to populate from props on mount
	const [columnName, setColumnName] = useState(() => initialEditingField?.name ?? '');
	const [dataType, setDataType] = useState<CellType>(() => initialEditingField?.type ?? preSelectedType ?? 'text');
	const [constraints, setConstraints] = useState<FieldConstraints>(() => initialEditingField?.constraints ?? { nullable: true });
	const [defaultValue, setDefaultValue] = useState(() => initialEditingField?.constraints.defaultValue?.toString() ?? '');
	// Type-specific validation state
	const [minLength, setMinLength] = useState<number | undefined>(() => initialEditingField?.constraints.minLength);
	const [maxLength, setMaxLength] = useState<number | undefined>(() => initialEditingField?.constraints.maxLength);
	const [pattern, setPattern] = useState<string | undefined>(() => initialEditingField?.constraints.pattern);
	const [precision, setPrecision] = useState<number | undefined>(() => initialEditingField?.constraints.precision);
	const [scale, setScale] = useState<number | undefined>(() => initialEditingField?.constraints.scale);
	const [minValue, setMinValue] = useState<number | undefined>(() => initialEditingField?.constraints.minValue);
	const [maxValue, setMaxValue] = useState<number | undefined>(() => initialEditingField?.constraints.maxValue);

	// Type search
	const [typeSearchTerm, setTypeSearchTerm] = useState('');

	const [isSaving, setIsSaving] = useState(false);

	// Ref for field name input - used for delayed focus after drag-drop
	const fieldNameInputRef = useRef<HTMLInputElement>(null);

	const tableId = currentTable?.id || '';
	const databaseId = currentDatabase?.databaseId ?? (currentSchema?.metadata?.databaseId || '');
	const tableName = currentTable?.name || '';

	const isEditMode = initialEditingField !== null;
	const isPending = createFieldMutation.isPending || updateFieldMutation.isPending;

	// Auto-focus field name only on create (not edit - accidental rename is dangerous)
	useEffect(() => {
		if (isEditMode) return;
		const timer = setTimeout(() => {
			fieldNameInputRef.current?.focus();
		}, 100);
		return () => clearTimeout(timer);
	}, [isEditMode]);

	// Field type options for combobox
	const fieldTypeOptions = useMemo(
		() =>
			fieldTypes
				.filter((type) => type.label.toLowerCase().includes(typeSearchTerm.toLowerCase()))
				.map((fieldType) => ({
					label: fieldType.label,
					value: fieldType.type,
				})),
		[typeSearchTerm],
	);

	const selectedFieldTypeOption = fieldTypeOptions.find((o) => o.value === dataType) ?? null;

	// Handle constraint toggle
	const handleConstraintToggle = useCallback(
		(type: 'primaryKey' | 'unique' | 'nullable') => {
			const updatedConstraints = updateCommonConstraint(constraints, type, !constraints[type]);
			setConstraints(updatedConstraints);
		},
		[constraints],
	);

	// Validation rules values and handler
	const validationRulesValues = useMemo<ValidationRulesValues>(
		() => ({ minLength, maxLength, pattern, precision, scale, minValue, maxValue }),
		[minLength, maxLength, pattern, precision, scale, minValue, maxValue],
	);

	const handleValidationRuleChange = useCallback(
		(field: keyof ValidationRulesValues, value: ValidationRulesValues[keyof ValidationRulesValues]) => {
			switch (field) {
				case 'minLength':
					setMinLength(value as number | undefined);
					break;
				case 'maxLength':
					setMaxLength(value as number | undefined);
					break;
				case 'pattern':
					setPattern(value as string | undefined);
					break;
				case 'precision':
					setPrecision(value as number | undefined);
					break;
				case 'scale':
					setScale(value as number | undefined);
					break;
				case 'minValue':
					setMinValue(value as number | undefined);
					break;
				case 'maxValue':
					setMaxValue(value as number | undefined);
					break;
			}
		},
		[],
	);

	// Build field definition from form state
	const buildFieldDefinition = useCallback((): FieldDefinition => {
		return {
			id: initialEditingField?.id || `temp-field-${Date.now()}`,
			name: columnName.trim(),
			type: dataType,
			constraints: {
				...constraints,
				defaultValue: defaultValue.trim() || undefined,
				minLength,
				maxLength,
				pattern: pattern?.trim() || undefined,
				precision,
				scale,
				minValue,
				maxValue,
			},
			fieldOrder: initialEditingField?.fieldOrder ?? (remoteFields.length > 0
				? Math.max(...remoteFields.map((f) => f.fieldOrder ?? 0)) + 1
				: 0),
		};
	}, [initialEditingField, columnName, dataType, constraints, defaultValue, minLength, maxLength, pattern, precision, scale, minValue, maxValue, remoteFields]);

	// Validation
	const canSave = useMemo(() => {
		if (!columnName.trim()) return false;
		if (!dataType) return false;
		return true;
	}, [columnName, dataType]);

	// Handle save
	const handleSave = useCallback(
		async () => {
			if (!canSave || !currentTable) return;

			setIsSaving(true);
			const field = buildFieldDefinition();

			try {
				if (isEditMode && initialEditingField) {
					// Update existing field
					await updateFieldMutation.mutateAsync({
						id: initialEditingField.id,
						field,
						tableId,
						databaseId,
						tableName,
						existingPrimaryKeyConstraintId: primaryKeyConstraintId,
						existingUniqueConstraintId: uniqueConstraintId,
						allPrimaryKeyFieldIds,
						wasPartOfPrimaryKey: isPartOfPrimaryKey,
					});
					toast.success({
						message: 'Field updated',
						description: `Field "${field.name}" has been updated successfully`,
					});
				} else {
					// Create new field
					await createFieldMutation.mutateAsync({
						field,
						tableId,
						databaseId,
						tableName,
						existingPrimaryKeyConstraintId: primaryKeyConstraintId,
						allPrimaryKeyFieldIds,
					});
					toast.success({
						message: 'Field created',
						description: `Field "${field.name}" has been created successfully`,
					});
				}

				card.close();
			} catch (error) {
				toast.error({
					message: isEditMode ? 'Failed to update field' : 'Failed to create field',
					description: error instanceof Error ? error.message : 'An error occurred',
				});
				setIsSaving(false);
			}
		},
		[
			canSave,
			currentTable,
			buildFieldDefinition,
			isEditMode,
			initialEditingField,
			updateFieldMutation,
			createFieldMutation,
			tableId,
			databaseId,
			tableName,
			primaryKeyConstraintId,
			uniqueConstraintId,
			allPrimaryKeyFieldIds,
			isPartOfPrimaryKey,
			card,
		],
	);

	const handleClose = useCallback(() => {
		card.close();
	}, [card]);

	const handleSubmit = useCallback(
		(e: React.FormEvent) => {
			e.preventDefault();
			if (canSave && !isPending) {
				handleSave();
			}
		},
		[canSave, isPending, handleSave],
	);

	if (!currentTable) return null;

	return (
		<form className='flex h-full flex-col' onSubmit={handleSubmit}>
			<ScrollArea className='min-h-0 flex-1'>
				<div className='space-y-6 p-6'>
					{/* Field Name */}
					<FormField htmlFor='columnName' label='Field name'>
						<Input
							id='columnName'
							ref={fieldNameInputRef}
							placeholder='e.g., user_email'
							value={columnName}
							onChange={(e) => setColumnName(e.target.value)}
							disabled={isPending}
							autoComplete='off'
						/>
					</FormField>

					{/* Data Type */}
					<FormField label='Data type'>
						<Combobox
							items={fieldTypeOptions}
							value={selectedFieldTypeOption}
							onValueChange={(next) => {
								if (next) setDataType(next.value as CellType);
							}}
						>
							<ComboboxTrigger
								className={cn(
									'flex h-9 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm',
									'hover:bg-muted/50 focus-visible:ring-1 focus-visible:ring-ring',
								)}
								disabled={isPending}
							>
								<div className='flex min-w-0 flex-1 items-center gap-2'>
									{(() => {
										const selectedTypeInfo = getFieldTypeInfo(dataType);
										return (
											<>
												<span className='text-muted-foreground flex shrink-0 items-center justify-center'>
													{typeof selectedTypeInfo?.icon === 'string' ? (
														selectedTypeInfo.icon
													) : selectedTypeInfo?.icon ? (
														<selectedTypeInfo.icon className='size-4' />
													) : (
														dataType.charAt(0).toUpperCase()
													)}
												</span>
												<span className='truncate'>{selectedTypeInfo?.label || dataType}</span>
											</>
										);
									})()}
								</div>
								<ChevronsUpDownIcon className='text-muted-foreground/50 shrink-0' size={16} />
							</ComboboxTrigger>
							<ComboboxPopup className='[&>[data-slot=combobox-popup]]:min-w-72'>
								<ComboboxInput
									value={typeSearchTerm}
									onChange={(e) => setTypeSearchTerm(e.target.value)}
									placeholder='Search field types...'
									showTrigger={false}
								/>
								<ComboboxEmpty>No field types found.</ComboboxEmpty>
								<ComboboxList>
									{(option: (typeof fieldTypeOptions)[number]) => {
										const fieldTypeInfo = getFieldTypeInfo(option.value as CellType);
										return (
											<ComboboxItem
												key={option.value}
												value={option}
												className='flex flex-row-reverse items-center justify-end gap-3 px-2'
											>
												<div className='flex flex-1 items-center gap-2.5'>
													<span className='text-muted-foreground flex size-5 shrink-0 items-center justify-center'>
														{typeof fieldTypeInfo?.icon === 'string' ? (
															fieldTypeInfo.icon
														) : fieldTypeInfo?.icon ? (
															<fieldTypeInfo.icon className='size-4' />
														) : (
															fieldTypeInfo?.type.charAt(0).toUpperCase()
														)}
													</span>
													<div className='flex flex-col'>
														<span className='text-sm'>{option.label}</span>
														{fieldTypeInfo?.description && (
															<span className='text-muted-foreground text-xs'>
																{fieldTypeInfo.description}
															</span>
														)}
													</div>
												</div>
											</ComboboxItem>
										);
									}}
								</ComboboxList>
							</ComboboxPopup>
						</Combobox>
					</FormField>

					{/* Constraints Section */}
					<FormSection title='Constraints'>
						<div className='flex flex-col gap-2'>
							<ConstraintCard
								type='primaryKey'
								selected={constraints.primaryKey ?? false}
								onToggle={() => handleConstraintToggle('primaryKey')}
								disabled={isPending}
							/>
							<ConstraintCard
								type='unique'
								// A primary key is unique by definition, so show it ticked while PK is on.
								selected={Boolean(constraints.unique || constraints.primaryKey)}
								onToggle={() => handleConstraintToggle('unique')}
								disabled={isPending || constraints.primaryKey}
								disabledReason={constraints.primaryKey ? 'set by PK' : undefined}
							/>
							<ConstraintCard
								type='nullable'
								selected={constraints.nullable ?? false}
								onToggle={() => handleConstraintToggle('nullable')}
								disabled={isPending || constraints.primaryKey}
								disabledReason={constraints.primaryKey ? 'disabled by PK' : undefined}
							/>
						</div>
					</FormSection>

					{/* Default Value */}
					<FormField
						hint='SQL functions or static values'
						htmlFor='defaultValue'
						label={
							<>
								Default value <span className='text-muted-foreground'>(optional)</span>
							</>
						}
					>
						<Input
							id='defaultValue'
							placeholder='e.g., 0, true, now()'
							value={defaultValue}
							onChange={(e) => setDefaultValue(e.target.value)}
							disabled={isPending}
						/>
					</FormField>

					{/* Validation Rules Section - Type-specific */}
					<ValidationRulesSection
						dataType={dataType}
						values={validationRulesValues}
						onChange={handleValidationRuleChange}
						disabled={isPending}
					/>
				</div>
			</ScrollArea>

			{/* Footer */}
			<div className='flex justify-end gap-3 border-t p-4'>
				<Button type='button' variant='outline' onClick={handleClose} disabled={isPending}>
					Cancel
				</Button>
				<Button
					type='submit'
					disabled={!canSave || isPending}
				>
					{isSaving ? <Loader2 className='mr-2 size-4 animate-spin' /> : null}
					{isEditMode ? 'Save' : 'Create'}
				</Button>
			</div>
		</form>
	);
};

'use client';

import { Fingerprint, Key, CircleDot } from 'lucide-react';

import { cn } from '@/components/schema-builder/lib/utils';
import { Checkbox } from '@/components/ui/checkbox';

type ConstraintType = 'primaryKey' | 'unique' | 'nullable';

interface ConstraintCardProps {
	type: ConstraintType;
	selected: boolean;
	disabled?: boolean;
	disabledReason?: string;
	onToggle: () => void;
}

const CONSTRAINT_CONFIG: Record<ConstraintType, { label: string; description: string; icon: typeof Key; tint: string }> = {
	primaryKey: {
		label: 'Primary key',
		description: 'Uniquely identifies each row (automatically sets UNIQUE + NOT NULL)',
		icon: Key,
		tint: 'text-blue-600 dark:text-blue-400',
	},
	unique: {
		label: 'Unique',
		description: 'All values in this column must be different',
		icon: Fingerprint,
		tint: 'text-purple-600 dark:text-purple-400',
	},
	nullable: {
		label: 'Nullable',
		description: 'Allow NULL values in this column',
		icon: CircleDot,
		tint: 'text-green-600 dark:text-green-400',
	},
};

/**
 * A checkbox with room for an explanation. The whole card is the checkbox's
 * label, so it toggles like one: no press animation, just the tick and a
 * quiet selected surface.
 */
export function ConstraintCard({ type, selected, disabled, disabledReason, onToggle }: ConstraintCardProps) {
	const { label, description, icon: Icon, tint } = CONSTRAINT_CONFIG[type];
	const active = selected && !disabled;

	return (
		<label
			className={cn(
				'flex items-center gap-3 rounded-lg border px-3 py-2.5',
				disabled ? 'cursor-not-allowed opacity-60' : 'cursor-pointer',
				active ? 'border-primary/35 bg-primary/[0.04]' : cn('border-border bg-card', !disabled && 'hover:bg-overlay-hover'),
			)}
		>
			<span className={cn('grid size-7 shrink-0 place-items-center rounded-md', active ? cn('bg-background', tint) : 'bg-muted text-muted-foreground')}>
				<Icon aria-hidden='true' className='size-3.5' />
			</span>
			<span className='flex min-w-0 flex-1 flex-col gap-0.5'>
				<span className='flex items-baseline gap-1.5'>
					<span className='text-foreground text-[13px] font-medium'>{label}</span>
					{disabled && disabledReason ? <span className='text-muted-foreground text-xs'>({disabledReason})</span> : null}
				</span>
				<span className='text-muted-foreground text-xs'>{description}</span>
			</span>
			<Checkbox checked={selected} className='shrink-0' disabled={disabled} onCheckedChange={() => onToggle()} />
		</label>
	);
}

'use client';

import { useState } from 'react';
import { Plus, X } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

import type { ConfigurableConstraintValue } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';

interface ConstraintControlProps {
	constraint: ConfigurableConstraintValue;
	onChange: (value: any) => void;
	onRemove: () => void;
}

export function LengthConstraintControl({ constraint, onChange }: Omit<ConstraintControlProps, 'onRemove'>) {
	const value = constraint.value || { min: undefined, max: undefined };

	const handleChange = (field: 'min' | 'max', newValue: string) => {
