'use client';

import { memo, useCallback, useMemo } from 'react';
import { Checkbox } from '@/components/ui/checkbox';
import { RiFingerprintLine, RiKey2Line, RiSparklingLine } from '@remixicon/react';

import type { FieldDefinition, TableConstraint } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { getFieldTypeInfo } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import type { CellType } from '@/components/schema-builder/schema/schema-builder-core/lib/types/cell-types';
import { handleActivationKeyDown } from '@/components/schema-builder/schema/schema-builder-core/lib/keyboard-activation';
import { cn } from '@/components/schema-builder/lib/utils';

interface FieldsListViewProps {
	fields: FieldDefinition[];
	constraints: TableConstraint[];
	selectedFieldIds: Set<string>;
	onSelectionChange: (selectedIds: Set<string>) => void;
	onFieldClick: (field: FieldDefinition) => void;
	disabled?: boolean;
}

const CONSTRAINT_STYLE = {
	pk: { className: 'bg-amber-500/10 text-amber-700 dark:text-amber-300', icon: RiKey2Line, label: 'Primary key' },
	unique: { className: 'bg-violet-500/10 text-violet-700 dark:text-violet-300', icon: RiFingerprintLine, label: 'Unique' },
} as const;

/** Keys stand out as tinted labels; required and nullable read as plain words, since every column is one or the other. */
function ConstraintIndicator({ type }: { type: keyof typeof CONSTRAINT_STYLE }) {
	const { className, icon: Icon, label } = CONSTRAINT_STYLE[type];
	return (
		<span className={cn('inline-flex h-5 items-center gap-1 rounded-md px-1.5 text-[11px] font-medium whitespace-nowrap', className)}>
			<Icon aria-hidden='true' className='size-3' />
			{label}
		</span>
	);
}

const GRID = 'grid grid-cols-[36px_minmax(0,1.3fr)_minmax(0,1fr)_minmax(0,1.1fr)_minmax(0,1fr)] items-center gap-3';

export function FieldsListView({
	fields,
	constraints,
	selectedFieldIds,
	onSelectionChange,
	onFieldClick,
	disabled,
}: FieldsListViewProps) {
	// Key membership, looked up once per table rather than per row.
	const { primaryKeyIds, uniqueIds } = useMemo(() => {
		const primaryKey = constraints.find((c) => c.type === 'primary_key');
		return {
			primaryKeyIds: new Set(primaryKey?.fields ?? []),
			uniqueIds: new Set(constraints.flatMap((c) => (c.type === 'unique' && c.fields.length === 1 ? c.fields : []))),
		};
	}, [constraints]);

	const handleSelectAll = useCallback(
		(checked: boolean) => onSelectionChange(checked ? new Set(fields.map((f) => f.id)) : new Set()),
		[fields, onSelectionChange],
	);

	const handleSelectRow = useCallback(
		(fieldId: string, checked: boolean) => {
			const next = new Set(selectedFieldIds);
			if (checked) next.add(fieldId);
			else next.delete(fieldId);
			onSelectionChange(next);
		},
		[selectedFieldIds, onSelectionChange],
	);

	const allSelected = fields.length > 0 && selectedFieldIds.size === fields.length;
	const someSelected = selectedFieldIds.size > 0 && selectedFieldIds.size < fields.length;

	return (
		<div className='min-w-[640px]'>
			{/* Header Row */}
			<div className={cn(GRID, 'bg-muted/60 text-muted-foreground px-3 py-2 text-xs')}>
				<div className='flex items-center justify-center'>
					<Checkbox
						checked={allSelected}
						indeterminate={someSelected}
						aria-label='Select all fields'
						onCheckedChange={(checked) => handleSelectAll(checked === true)}
						disabled={disabled || fields.length === 0}
					/>
				</div>
				<div>Field</div>
				<div>Type</div>
				<div>Constraints</div>
				<div>Default</div>
			</div>

			{/* Field Rows */}
			<div className='divide-border divide-y'>
				{fields.map((field) => (
					<FieldRow
						disabled={disabled}
						field={field}
						isPrimaryKey={primaryKeyIds.has(field.id)}
						isSelected={selectedFieldIds.has(field.id)}
						isUnique={uniqueIds.has(field.id)}
						key={field.id}
						onOpen={onFieldClick}
						onSelect={handleSelectRow}
					/>
				))}
			</div>

			{/* Empty state */}
			{fields.length === 0 && (
				<div className='flex flex-col items-center justify-center gap-2 py-10'>
					<span className='bg-muted text-muted-foreground grid size-9 place-items-center rounded-xl'>
						<RiSparklingLine aria-hidden='true' className='size-4' />
					</span>
					<div className='text-center'>
						<p className='text-foreground text-[13px] font-medium'>No fields yet</p>
						<p className='text-muted-foreground mt-0.5 text-xs'>Add a field, or drop a type from the library.</p>
					</div>
				</div>
			)}
		</div>
	);
}

type FieldRowProps = {
	field: FieldDefinition;
	isSelected: boolean;
	isPrimaryKey: boolean;
	isUnique: boolean;
	disabled?: boolean;
	onSelect: (fieldId: string, checked: boolean) => void;
	onOpen: (field: FieldDefinition) => void;
};

/** One field. Memoized so a selection change re-renders only the rows it touches. */
const FieldRow = memo(function FieldRow({
	field,
	isSelected,
	isPrimaryKey,
	isUnique,
	disabled,
	onSelect,
	onOpen,
}: FieldRowProps) {
	const typeInfo = getFieldTypeInfo(field.type as CellType);
	const TypeIcon = typeInfo?.icon;
	const isRequired = !field.constraints.nullable;
	const defaultValue = field.constraints.defaultValue;
	const hasDefault = defaultValue !== undefined && defaultValue !== null && defaultValue !== '';

	return (
		<div
			role='button'
			tabIndex={disabled ? -1 : 0}
			aria-disabled={disabled || undefined}
			data-chat-component='field-row'
			data-chat-field-name={field.name}
			data-chat-field-type={field.type}
			data-chat-nullable={String(field.constraints.nullable)}
			className={cn(
				GRID,
				'group hover:bg-overlay-hover cursor-pointer px-3 py-2 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:ring-inset',
				isSelected && 'bg-primary/[0.05]',
			)}
			onClick={() => {
				if (!disabled) onOpen(field);
			}}
			onKeyDown={(event) => handleActivationKeyDown(event, () => onOpen(field), disabled)}
		>
			<div className='flex items-center justify-center' onClick={(e) => e.stopPropagation()}>
				<Checkbox
					aria-label={`Select ${field.name}`}
					checked={isSelected}
					disabled={disabled}
					onCheckedChange={(checked) => onSelect(field.id, checked === true)}
				/>
			</div>

			<span className='text-foreground min-w-0 truncate font-mono text-[13px]' title={field.name}>
				{field.name}
			</span>

			<div className='flex min-w-0 items-center'>
				<span className='bg-muted/50 inline-flex h-6 min-w-0 items-center gap-1.5 rounded-md px-2 text-xs ring-1 ring-foreground/[0.07] ring-inset'>
					{TypeIcon ? (
						<span className='text-muted-foreground flex items-center'>
							{typeof TypeIcon === 'string' ? <span className='text-xs'>{TypeIcon}</span> : <TypeIcon className='size-3.5' />}
						</span>
					) : null}
					<span className='text-foreground/80 truncate'>{typeInfo?.label || field.type}</span>
				</span>
			</div>

			<div className='flex min-w-0 flex-wrap items-center gap-1.5'>
				{isPrimaryKey ? (
					<ConstraintIndicator type='pk' />
				) : (
					<>
						{isUnique ? <ConstraintIndicator type='unique' /> : null}
						<span className={cn('text-xs', isRequired ? 'text-foreground/75' : 'text-muted-foreground')}>
							{isRequired ? 'Required' : 'Nullable'}
						</span>
					</>
				)}
			</div>

			<div className='flex min-w-0 items-center'>
				{hasDefault ? (
					<code className='bg-muted/60 text-foreground/75 truncate rounded px-1.5 py-0.5 font-mono text-xs'>{String(defaultValue)}</code>
				) : (
					<span aria-label='No default' className='text-subtle-foreground text-xs'>
						—
					</span>
				)}
			</div>
		</div>
	);
});

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Button } from '@/components/ui/button';
import { useCardStack } from '@/components/ui/stack';
import { toast } from '@/components/ui/toast';
import { useDroppable } from '@dnd-kit/core';
import { Loader2, Plus, Trash2 } from 'lucide-react';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useDeleteField } from '../../lib/gql/hooks/schema-builder/use-field-mutations';
import type { FieldDefinition } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { CARD_WIDTHS } from '@/components/schema-builder/schema/schema-builder-core/lib/stack/card-widths';
import type { CellType } from '@/components/schema-builder/schema/schema-builder-core/lib/types/cell-types';
import { cn } from '@/components/schema-builder/lib/utils';

import { AddFieldCard } from './add-field-card';
import { FieldsListView } from './fields-list-view';

interface FieldsSectionProps {
	onAddFieldRef?: (addFieldFn: (field: FieldDefinition) => void) => void;
}

export function FieldsSection({ onAddFieldRef }: FieldsSectionProps = {}) {
	const { currentTable } = useSchemaBuilderSelectors();

	const stack = useCardStack();
	const deleteFieldMutation = useDeleteField();

	// Multi-select state
	const [selectedFieldIds, setSelectedFieldIds] = useState<Set<string>>(new Set());

	// Drag-drop zone
	const { setNodeRef: setDropZoneRef, isOver: isOverDropZone } = useDroppable({
		id: 'column-editor-dropzone',
	});

	const remoteFields = useMemo(() => currentTable?.fields || [], [currentTable?.fields]);
	const constraints = useMemo(() => currentTable?.constraints || [], [currentTable?.constraints]);

	// Sort fields: UUID fields first, then by field order
	const sortedFields = useMemo(() => {
		return [...remoteFields].sort((a, b) => {
			const aIsUuid = a.type === 'uuid';
			const bIsUuid = b.type === 'uuid';
			if (aIsUuid && !bIsUuid) return -1;
			if (!aIsUuid && bIsUuid) return 1;
			return (a.fieldOrder ?? 0) - (b.fieldOrder ?? 0);
		});
	}, [remoteFields]);

	// Clear selection when table changes
	useEffect(() => {
		setSelectedFieldIds(new Set());
	}, [currentTable?.id]);

	// The key constraints a field edit or delete must carry along.
	const constraintInfoFor = useCallback(
		(field: FieldDefinition) => {
			const pkConstraint = constraints.find((c) => c.type === 'primary_key');
			const uniqueConstraint = constraints.find(
				(c) => c.type === 'unique' && c.fields.length === 1 && c.fields[0] === field.id,
			);
			return {
				primaryKeyConstraintId: pkConstraint?.id,
				uniqueConstraintId: uniqueConstraint?.id,
				allPrimaryKeyFieldIds: pkConstraint?.fields ?? [],
				isPartOfPrimaryKey: pkConstraint?.fields.includes(field.id) ?? false,
			};
		},
		[constraints],
	);

	// Handle "Add Field" button click - push card in create mode
	const handleAddField = useCallback(() => {
		stack.push({
			id: 'add-field-new',
			title: 'Add Field',
			Component: AddFieldCard,
			props: {
				editingField: null,
				preSelectedType: null,
				remoteFields,
			},
			width: CARD_WIDTHS.wide,
		});
	}, [stack, remoteFields]);

	// Handle field row click - push card in edit mode
	const handleFieldClick = useCallback(
		(field: FieldDefinition) => {
			const constraintInfo = constraintInfoFor(field);
			stack.push({
				id: `edit-field-${field.id}`,
				title: 'Edit Field',
				Component: AddFieldCard,
				props: {
					editingField: field,
					preSelectedType: null,
					primaryKeyConstraintId: constraintInfo.primaryKeyConstraintId,
					uniqueConstraintId: constraintInfo.uniqueConstraintId,
					allPrimaryKeyFieldIds: constraintInfo.allPrimaryKeyFieldIds,
					isPartOfPrimaryKey: constraintInfo.isPartOfPrimaryKey,
					remoteFields,
				},
				width: CARD_WIDTHS.wide,
			});
		},
		[stack, constraintInfoFor, remoteFields],
	);

	// Handle drag-drop from types library - push card with pre-selected type
	const handleFieldDrop = useCallback(
		(field: FieldDefinition) => {
			stack.push({
				id: `add-field-${field.type}`,
				title: 'Add Field',
				Component: AddFieldCard,
				props: {
					editingField: null,
					preSelectedType: field.type as CellType,
					remoteFields,
				},
				width: CARD_WIDTHS.wide,
			});
		},
		[stack, remoteFields],
	);

	// Expose handleFieldDrop to parent component via onAddFieldRef
	useEffect(() => {
		onAddFieldRef?.(handleFieldDrop);
	}, [onAddFieldRef, handleFieldDrop]);

	// Handle bulk delete
	const [isDeleting, setIsDeleting] = useState(false);
	const handleBulkDelete = useCallback(async () => {
		if (selectedFieldIds.size === 0) return;

		const fieldsToDelete = sortedFields.filter((f) => selectedFieldIds.has(f.id));
		if (fieldsToDelete.length === 0) return;

		setIsDeleting(true);

		const results = await Promise.allSettled(
			fieldsToDelete.map((field) => {
				const { isPartOfPrimaryKey, ...keys } = constraintInfoFor(field);
				return deleteFieldMutation.mutateAsync({ id: field.id, ...keys, wasPartOfPrimaryKey: isPartOfPrimaryKey });
			}),
		);

		const deletedIds: string[] = [];
		const failed: { name: string }[] = [];

		results.forEach((result, i) => {
			if (result.status === 'fulfilled') {
				deletedIds.push(fieldsToDelete[i].id);
			} else {
				failed.push({ name: fieldsToDelete[i].name });
			}
		});

		setIsDeleting(false);

		// Clear only successfully deleted fields from selection
		if (deletedIds.length > 0) {
			setSelectedFieldIds((prev) => {
				const next = new Set(prev);
				for (const id of deletedIds) next.delete(id);
				return next;
			});
		}

		if (deletedIds.length > 0 && failed.length === 0) {
			toast.success({
				message: `${deletedIds.length} field${deletedIds.length > 1 ? 's' : ''} deleted`,
			});
		} else if (deletedIds.length > 0 && failed.length > 0) {
			toast.warning({
				message: `${deletedIds.length} deleted, ${failed.length} failed`,
				description: `Failed to delete: ${failed.map((f) => f.name).join(', ')}`,
			});
		} else {
			toast.error({
				message: 'Failed to delete fields',
				description: `Failed to delete: ${failed.map((f) => f.name).join(', ')}`,
			});
		}
	}, [selectedFieldIds, sortedFields, constraintInfoFor, deleteFieldMutation]);

	return (
		<div
			data-chat-component='fields-section'
			data-chat-table-name={currentTable?.name ?? ''}
			data-chat-field-count={String(remoteFields.length)}
			className='flex flex-col gap-2.5'
		>
			{/* Section Header */}
			<div className='flex h-7 items-center justify-between gap-2'>
				<h3 className='text-foreground text-[13px] font-medium'>
					Fields
					<span className='text-subtle-foreground ml-1.5 font-normal tabular-nums'>{remoteFields.length}</span>
				</h3>
				{selectedFieldIds.size > 0 ? (
					<Button
						variant='ghost'
						size='sm'
						className='text-destructive hover:bg-destructive/10 hover:text-destructive h-7 gap-1.5 px-2 text-xs'
						onClick={handleBulkDelete}
						disabled={isDeleting}
					>
						{isDeleting ? <Loader2 className='size-3.5 animate-spin' /> : <Trash2 className='size-3.5' />}
						{isDeleting ? 'Deleting…' : `Delete ${selectedFieldIds.size}`}
					</Button>
				) : (
					<Button className='h-7 gap-1.5 px-2 text-xs' onClick={handleAddField} size='sm' variant='ghost'>
						<Plus aria-hidden='true' className='size-3.5' />
						Add field
					</Button>
				)}
			</div>

			{/* Fields Card */}
			<div
				ref={setDropZoneRef}
				className={cn(
					'bg-card overflow-hidden rounded-xl shadow-card ring-inset',
					isOverDropZone ? 'ring-primary/50 ring-2' : null,
				)}
			>
				{/* Fields List */}
				<div className='overflow-x-auto'>
					<FieldsListView
						fields={sortedFields}
						constraints={constraints}
						selectedFieldIds={selectedFieldIds}
						onSelectionChange={setSelectedFieldIds}
						onFieldClick={handleFieldClick}
						disabled={isDeleting}
					/>
				</div>

				{/* Drop zone footer */}
				<div
					className={cn(
						'text-muted-foreground flex items-center justify-center gap-1.5 border-t border-dashed border-foreground/10 px-4 py-2.5 text-xs',
						isOverDropZone && 'bg-primary/[0.06] text-primary',
					)}
				>
					<button
						className='text-foreground/80 hover:text-foreground cursor-pointer rounded font-medium outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50'
						onClick={handleAddField}
						type='button'
					>
						Add a field
					</button>
					<span>or drop a type from the library here</span>
				</div>
			</div>
		</div>
	);
}

