'use client';

import { startTransition, useMemo, useState } from 'react';
import { RiDragDropLine, RiSearchLine } from '@remixicon/react';
import { ChevronRight } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';

import { Collapsible, CollapsibleTrigger } from '@/components/ui/collapsible';
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group';

import { durations, easings, springs } from '@/components/schema-builder/schema/schema-builder-core/lib/motion/motion-config';
import type { FieldTypeInfo } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { getAdvancedFieldTypes, getBasicFieldTypes, searchFieldTypes } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { DraggableFieldType } from './draggable-field-type';

const basicTypes = getBasicFieldTypes();
const advancedTypes = getAdvancedFieldTypes();
const allTypes = [...basicTypes, ...advancedTypes];

export function TypesLibrary() {
	const [searchQuery, setSearchQuery] = useState('');

	// Section expand/collapse state (local, not persisted) - lazy init
	const [sectionsExpanded, setSectionsExpanded] = useState(() => ({ basic: true, advanced: false }));
	const toggleSection = (section: 'basic' | 'advanced') =>
		setSectionsExpanded((prev) => ({ ...prev, [section]: !prev[section] }));

	// Filter types based on search query
	const { filteredBasicTypes, filteredAdvancedTypes } = useMemo(() => {
		if (!searchQuery.trim()) {
			return { filteredBasicTypes: basicTypes, filteredAdvancedTypes: advancedTypes };
		}

		const searchResults = searchFieldTypes(searchQuery);
		const matchingTypes = new Set(searchResults.map((r) => r.type));

		return {
			filteredBasicTypes: basicTypes.filter((type) => matchingTypes.has(type.type)),
			filteredAdvancedTypes: advancedTypes.filter((type) => matchingTypes.has(type.type)),
		};
	}, [searchQuery]);

	const totalFilteredCount = filteredBasicTypes.length + filteredAdvancedTypes.length;
	const totalTypesCount = allTypes.length;

	return (
		<div className='flex h-full min-h-0 flex-col'>
			{/* Search */}
			<div className='px-3 pt-3 pb-2'>
				<InputGroup>
					<InputGroupAddon>
						<RiSearchLine />
					</InputGroupAddon>
					<InputGroupInput
						placeholder='Search types…'
						value={searchQuery}
						onChange={(e) => {
							const value = e.target.value;
							startTransition(() => setSearchQuery(value));
						}}
						size='sm'
					/>
				</InputGroup>
				{searchQuery && (
					<p className='text-muted-foreground mt-1.5 text-xs'>
						{totalFilteredCount} of {totalTypesCount} types
					</p>
				)}
			</div>

			{/* Types sections */}
			<div className='scrollbar-neutral-thin min-h-0 flex-1 space-y-3 overflow-auto px-2 pb-2'>
				{totalFilteredCount === 0 ? (
					<div className='text-muted-foreground p-4 text-center text-sm'>
						<p>No types found for &ldquo;{searchQuery}&rdquo;</p>
					</div>
				) : (
					<>
						{/* Basic Types Section */}
						{filteredBasicTypes.length > 0 && (
							<TypesSection
								title='Basic'
								types={filteredBasicTypes}
								isExpanded={sectionsExpanded.basic}
								onToggleExpand={() => toggleSection('basic')}
							/>
						)}

						{/* Advanced Types Section */}
						{filteredAdvancedTypes.length > 0 && (
							<TypesSection
								title='Advanced'
								types={filteredAdvancedTypes}
								isExpanded={sectionsExpanded.advanced}
								onToggleExpand={() => toggleSection('advanced')}
							/>
						)}
					</>
				)}
			</div>

			{/* Footer hint */}
			<div className='text-muted-foreground flex items-center gap-1.5 border-t border-dashed border-foreground/10 px-3 py-2 text-xs'>
				<RiDragDropLine className='h-3 w-3' />
				<span>Drag or use the keyboard to add fields.</span>
			</div>
		</div>
	);
}

interface TypesSectionProps {
	title: string;
	types: FieldTypeInfo[];
	isExpanded: boolean;
	onToggleExpand: () => void;
}

function TypesSection({ title, types, isExpanded, onToggleExpand }: TypesSectionProps) {
	return (
		<Collapsible open={isExpanded} onOpenChange={onToggleExpand} className='flex min-h-0 shrink-0 flex-col'>
			<CollapsibleTrigger
				className='group text-muted-foreground hover:text-foreground flex h-7 w-full cursor-pointer items-center gap-1.5 rounded-md px-1.5 text-xs outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50'
			>
				<motion.div
					animate={{ rotate: isExpanded ? 90 : 0 }}
					transition={{ type: 'spring', stiffness: 400, damping: 25 }}
					className='flex shrink-0 items-center justify-center'
				>
					<ChevronRight className='size-3 opacity-70' />
				</motion.div>
				<span>{title}</span>
				<span className='text-subtle-foreground ml-auto tabular-nums'>{types.length}</span>
			</CollapsibleTrigger>

			<AnimatePresence initial={false}>
				{isExpanded && (
					<motion.div
						initial={{ opacity: 0, y: -4 }}
						animate={{ opacity: 1, y: 0 }}
						exit={{ opacity: 0, y: -4 }}
						transition={{
							...springs.stiff,
							opacity: { duration: durations.fast, ease: easings.easeOut },
						}}
						className='min-h-0 overflow-hidden'
					>
						<div className='mt-0.5 flex flex-col gap-px'>
							{types.map((typeInfo) => (
								<DraggableFieldType key={typeInfo.type} typeInfo={typeInfo} className='w-full' />
							))}
						</div>
					</motion.div>
				)}
			</AnimatePresence>
		</Collapsible>
	);
}

import { useCallback, useState } from 'react';
import {
	defaultDropAnimationSideEffects,
	DragEndEvent,
	DragStartEvent,
	KeyboardSensor,
	PointerSensor,
	rectIntersection,
	useSensor,
	useSensors,
	type CollisionDetection,
	type DropAnimation,
} from '@dnd-kit/core';

import type { FieldDefinition, FieldTypeInfo, TableDefinition } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { getDefaultConstraintsForType } from '../../../schema-builder-core/lib/schema';

export const COLUMN_EDITOR_DROPZONE_ID = 'column-editor-dropzone' as const;

export type DragSource = 'rail' | 'panel';

export interface FieldDragData {
	typeInfo?: FieldTypeInfo;
	source?: DragSource;
}

export const DEFAULT_DROP_ANIMATION: DropAnimation = {
	sideEffects: defaultDropAnimationSideEffects({
		styles: {
			active: {
				opacity: '0.5',
			},
		},
	}),
};

export function useFieldDnD(currentTable: TableDefinition | null) {
	const [activeId, setActiveId] = useState<string | null>(null);
	const [draggedType, setDraggedType] = useState<FieldTypeInfo | null>(null);
	const [dragSource, setDragSource] = useState<DragSource | null>(null);
	const [addFieldFn, setAddFieldFn] = useState<((field: FieldDefinition) => void) | null>(null);

	const sensors = useSensors(
		useSensor(KeyboardSensor),
		useSensor(PointerSensor, {
			activationConstraint: {
				distance: 8,
			},
		}),
	);

	const handleDragStart = (event: DragStartEvent) => {
		const { active } = event;
		setActiveId(active.id as string);

		// Check if it's a field type
		const data = active.data.current as FieldDragData | null;

		if (data?.typeInfo) {
			setDraggedType(data.typeInfo);
			setDragSource(data.source ?? 'panel');
		}
	};

	// Custom collision detection that filters out invalid drop targets
	const customCollisionDetection: CollisionDetection = (args) => {
		const collisions = rectIntersection(args);

		// Field types can only be dropped on the main drop zone
		return collisions.filter((collision) => collision.id === COLUMN_EDITOR_DROPZONE_ID);
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { over } = event;

		if (!over) {
			setActiveId(null);
			setDraggedType(null);
			setDragSource(null);
			return;
		}

		// Validate drop zone
		const isValidDrop = over.id === COLUMN_EDITOR_DROPZONE_ID;

		if (!isValidDrop || !draggedType || !addFieldFn || !currentTable) {
			setActiveId(null);
			setDraggedType(null);
			setDragSource(null);
			return;
		}

		// Handle field type drops
		if (over.id === COLUMN_EDITOR_DROPZONE_ID) {
			// Create new field
			const newField: FieldDefinition = {
				id: `temp-field-${Date.now()}`,
				name: '',
				type: draggedType.type,
				constraints: getDefaultConstraintsForType(draggedType.type),
				fieldOrder: 1000, // Temporary order
			};

			// Add field via callback from FieldsSection
			addFieldFn(newField);
		}

		// Reset state
		setActiveId(null);
		setDraggedType(null);
		setDragSource(null);
	};

	const handleDragCancel = () => {
		setActiveId(null);
		setDraggedType(null);
		setDragSource(null);
	};

	const handleAddFieldRef = useCallback((fn: (field: FieldDefinition) => void) => {
		setAddFieldFn(() => fn);
	}, []);

	return {
		sensors,
		customCollisionDetection,
		handleDragStart,
		handleDragEnd,
		handleDragCancel,
		handleAddFieldRef,
		activeId,
		draggedType,
		dragSource,
	};
}

'use client';

import { Input } from '@/components/ui/input';

import { getFieldTypeInfo } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import type { CellType } from '@/components/schema-builder/schema/schema-builder-core/lib/types/cell-types';

import { FormField, FormSection } from './form-field';

export interface ValidationRulesValues {
	minLength?: number;
	maxLength?: number;
	pattern?: string;
	precision?: number;
	scale?: number;
	minValue?: number;
	maxValue?: number;
}

interface ValidationRulesSectionProps {
	dataType: CellType;
	values: ValidationRulesValues;
	onChange: (field: keyof ValidationRulesValues, value: ValidationRulesValues[keyof ValidationRulesValues]) => void;
	disabled?: boolean;
}

type NumberRule = { key: keyof ValidationRulesValues; label: string; placeholder: string; hint?: string; decimal?: boolean };

const LENGTH_RULES: NumberRule[] = [
	{ key: 'minLength', label: 'Min length', placeholder: 'e.g., 3' },
	{ key: 'maxLength', label: 'Max length', placeholder: 'e.g., 255' },
];
const RANGE_RULES: NumberRule[] = [
	{ key: 'minValue', label: 'Min value', placeholder: 'e.g., 0', decimal: true },
	{ key: 'maxValue', label: 'Max value', placeholder: 'e.g., 100', decimal: true },
];
const PRECISION_RULE: NumberRule = { key: 'precision', label: 'Precision', placeholder: 'e.g., 10', hint: 'Total digits' };
const SCALE_RULE: NumberRule = { key: 'scale', label: 'Scale', placeholder: 'e.g., 2', hint: 'Decimal places' };

export function ValidationRulesSection({ dataType, values, onChange, disabled }: ValidationRulesSectionProps) {
	const configurable = getFieldTypeInfo(dataType)?.configurable;
	if (!configurable) return null;

	// Rows in display order; the regex pattern sits after the length row.
	const numericRows = [
		[...(configurable.precision ? [PRECISION_RULE] : []), ...(configurable.scale ? [SCALE_RULE] : [])],
		configurable.range ? RANGE_RULES : [],
	].filter((row) => row.length > 0);
	if (!configurable.length && !configurable.pattern && numericRows.length === 0) return null;

	const numberField = ({ key, label, placeholder, hint, decimal }: NumberRule) => (
		<FormField hint={hint} htmlFor={key} key={key} label={label} subtle>
			<Input
				disabled={disabled}
				id={key}
				onChange={(e) => onChange(key, e.target.value ? (decimal ? parseFloat : parseInt)(e.target.value) : undefined)}
				placeholder={placeholder}
				type='number'
				value={values[key] ?? ''}
			/>
		</FormField>
	);

	return (
		<FormSection
			title={
				<>
					Validation rules <span className='text-muted-foreground'>(optional)</span>
				</>
			}
		>
			<div className='flex flex-col gap-4'>
				{configurable.length ? <div className='grid grid-cols-2 gap-4'>{LENGTH_RULES.map(numberField)}</div> : null}
				{configurable.pattern ? (
					<FormField hint='Validate values with a regular expression' htmlFor='pattern' label='Regex pattern' subtle>
						<Input
							className='font-mono text-sm'
							disabled={disabled}
							id='pattern'
							onChange={(e) => onChange('pattern', e.target.value || undefined)}
							placeholder='e.g., ^[a-z]+$'
							value={values.pattern ?? ''}
						/>
					</FormField>
				) : null}
				{numericRows.map((row) => (
					<div className='grid grid-cols-2 gap-4' key={row[0]!.key}>
						{row.map(numberField)}
					</div>
				))}
			</div>
		</FormSection>
	);
}

/**
 * Hook for field mutations (create, update, delete)
 * Tier 4 wrapper: orchestrates field + constraint mutations
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';

import { asFieldIds, stripEmpty } from '@/components/schema-builder/schema/schema-builder-core/lib/data';

import { cellTypeToBackendType, mapConstraintsToFieldPatch } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/transformers/field-constraints-mapper';
import { fieldTypeToTypeName, toFieldDefault, toFieldType } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/transformers/field-type-mapper';
import type { FieldDefinition } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';

// SDK hooks for field mutations
import {
	useCreateFieldMutation,
	useCreatePrimaryKeyConstraintMutation,
	useCreateUniqueConstraintMutation,
	useDeleteFieldMutation,
	useDeletePrimaryKeyConstraintMutation,
	useDeleteUniqueConstraintMutation,
	useUpdateFieldMutation,
	useUpdatePrimaryKeyConstraintMutation,
} from '@/components/schema-builder/compat/schema-builder-sdk';

// SDK hooks for constraint mutations

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';

// Input types for hook consumers
export interface CreateFieldData {
	field: FieldDefinition;
	tableId: string;
	databaseId: string;
	tableName: string;
	existingPrimaryKeyConstraintId?: string;
	allPrimaryKeyFieldIds?: string[];
}

export interface UpdateFieldData {
	id: string;
	field: FieldDefinition;
	tableId: string;
	databaseId: string;
	tableName: string;
	existingPrimaryKeyConstraintId?: string;
	existingUniqueConstraintId?: string;
	allPrimaryKeyFieldIds?: string[];
	wasPartOfPrimaryKey?: boolean;
}

export interface DeleteFieldData {
	id: string;
	primaryKeyConstraintId?: string;
	uniqueConstraintId?: string;
	allPrimaryKeyFieldIds?: string[];
	wasPartOfPrimaryKey?: boolean;
}

export interface FieldOrderUpdate {
	id: string;
	fieldOrder: number;
}

// Return type for created field
interface CreatedField {
	id: string;
	name: string;
	type: string;
}

function fieldDefinitionToCreateInput(field: FieldDefinition, tableId: string, databaseId: string) {
	// CRITICAL: Auto-set UUID default value for primary keys to prevent "capability denied" errors
	let defaultValue = field.constraints.defaultValue?.toString() || undefined;

	const backendType = cellTypeToBackendType(field.type);
	if (backendType === 'uuid' && field.constraints.primaryKey && !defaultValue) {
		defaultValue = 'uuidv7()';
	}

	const { smartTags, chk, chkExpr, ...constraintFields } = mapConstraintsToFieldPatch(field);
	return {
		name: field.name,
		// type/defaultValue are structured JSONB objects in the metaschema now.
		type: toFieldType(backendType) as unknown as Record<string, unknown>,
		tableId,
		databaseId,
		description: stripEmpty(field.description),
		label: stripEmpty(field.label),
		defaultValue: toFieldDefault(defaultValue) as unknown as Record<string, unknown> | undefined,
		isRequired: field.isRequired ?? !field.constraints.nullable,
		fieldOrder: field.fieldOrder,
		...constraintFields,
		smartTags: smartTags as Record<string, unknown> | undefined,
		chk: chk as Record<string, unknown> | undefined,
		chkExpr: chkExpr as Record<string, unknown> | undefined,
	};
}

function fieldDefinitionToPatch(field: FieldDefinition) {
	let defaultValue = field.constraints.defaultValue?.toString() || undefined;

	const backendType = cellTypeToBackendType(field.type);
	if (backendType === 'uuid' && field.constraints.primaryKey && !defaultValue) {
		defaultValue = 'uuidv7()';
	}

	const { smartTags, chk, chkExpr, ...constraintFields } = mapConstraintsToFieldPatch(field);
	return {
		name: field.name,
		// type/defaultValue are structured JSONB objects in the metaschema FieldPatch now.
		type: toFieldType(backendType) as unknown as Record<string, unknown>,
		description: stripEmpty(field.description),
		label: stripEmpty(field.label),
		defaultValue: toFieldDefault(defaultValue) as unknown as Record<string, unknown> | undefined,
		isRequired: field.isRequired ?? !field.constraints.nullable,
		fieldOrder: field.fieldOrder,
		...constraintFields,
		smartTags: smartTags as Record<string, unknown> | undefined,
		chk: chk as Record<string, unknown> | undefined,
		chkExpr: chkExpr as Record<string, unknown> | undefined,
	};
}

export function useCreateField() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase } = useSchemaBuilderSelectors();
	const createFieldMutation = useCreateFieldMutation({ selection: { fields: { id: true, name: true, type: true } } });
	const createPkMutation = useCreatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const updatePkMutation = useUpdatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const createUniqueMutation = useCreateUniqueConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: CreateFieldData): Promise<CreatedField> => {
			const fieldInput = fieldDefinitionToCreateInput(input.field, input.tableId, input.databaseId);

			// Step 1: Create the field
			const result = await createFieldMutation.mutateAsync(fieldInput);

			const createdField = result.createField?.field;
			if (!createdField?.id || !createdField?.name) {
				throw new Error('Failed to create field');
			}

			const errors: string[] = [];

			// Step 2: Handle primary key constraint
			if (input.field.constraints.primaryKey) {
				if (input.existingPrimaryKeyConstraintId && input.allPrimaryKeyFieldIds) {
					const updatedFieldIds = [...input.allPrimaryKeyFieldIds, createdField.id];
					try {
						await updatePkMutation.mutateAsync({
							id: input.existingPrimaryKeyConstraintId, primaryKeyConstraintPatch: { fieldIds: asFieldIds(updatedFieldIds) },
						});
					} catch (error) {
						errors.push(`Failed to update primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
						throw new Error(errors.join('; '));
					}
				} else {
					try {
						await createPkMutation.mutateAsync({
							tableId: input.tableId,
							databaseId: input.databaseId,
							fieldIds: asFieldIds([createdField.id]),
							name: `${input.tableName}_pkey`,
							type: 'p',
						});
					} catch (error) {
						errors.push(`Failed to create primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
						throw new Error(errors.join('; '));
					}
				}
			}

			// Step 3: Create unique constraint if needed
			if (input.field.constraints.unique) {
				try {
					await createUniqueMutation.mutateAsync({
						tableId: input.tableId,
						databaseId: input.databaseId,
						fieldIds: asFieldIds([createdField.id]),
						name: `${input.field.name}_key`,
						type: 'u',
					});
				} catch (error) {
					errors.push(`Failed to create unique constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
					throw new Error(errors.join('; '));
				}
			}

			// createdField.type is now a structured FieldType object; reduce to the
			// type-name string this return shape expects.
			return { id: createdField.id, name: createdField.name, type: fieldTypeToTypeName(createdField.type) };
		},
		onSuccess: async (_result, variables) => {
			await invalidateDatabaseEntities(queryClient, variables.databaseId ?? currentDatabase?.databaseId);
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to create field:', error);
		},
	});
}

export function useUpdateField() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase } = useSchemaBuilderSelectors();
	const updateFieldMutation = useUpdateFieldMutation({ selection: { fields: { id: true, name: true, type: true } } });
	const createPkMutation = useCreatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const updatePkMutation = useUpdatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const deletePkMutation = useDeletePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const createUniqueMutation = useCreateUniqueConstraintMutation({ selection: { fields: { id: true } } });
	const deleteUniqueMutation = useDeleteUniqueConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: UpdateFieldData) => {
			const patch = fieldDefinitionToPatch(input.field);
			const errors: string[] = [];

			// Step 1: Update the field
			const result = await updateFieldMutation.mutateAsync({ id: input.id, fieldPatch: patch });

			const updatedField = result.updateField?.field;
			if (!updatedField?.id) {
				throw new Error('Failed to update field');
			}

			// Step 2: Handle primary key constraint changes
			const hasPrimaryKey = input.field.constraints.primaryKey;
			const hadPrimaryKey = input.wasPartOfPrimaryKey || false;

			if (hasPrimaryKey && !hadPrimaryKey) {
				if (input.existingPrimaryKeyConstraintId && input.allPrimaryKeyFieldIds) {
					const updatedFieldIds = [...input.allPrimaryKeyFieldIds, input.id];
					try {
						await updatePkMutation.mutateAsync({
							id: input.existingPrimaryKeyConstraintId, primaryKeyConstraintPatch: { fieldIds: asFieldIds(updatedFieldIds) },
						});
					} catch (error) {
						errors.push(`Failed to update primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
					}
				} else {
					try {
						await createPkMutation.mutateAsync({
							tableId: input.tableId,
							databaseId: input.databaseId,
							fieldIds: asFieldIds([input.id]),
							name: `${input.tableName}_pkey`,
							type: 'p',
						});
					} catch (error) {
						errors.push(`Failed to create primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
					}
				}
			} else if (!hasPrimaryKey && hadPrimaryKey) {
				if (input.existingPrimaryKeyConstraintId && input.allPrimaryKeyFieldIds) {
					const remainingFieldIds = input.allPrimaryKeyFieldIds.filter((id) => id !== input.id);
					if (remainingFieldIds.length > 0) {
						try {
							await updatePkMutation.mutateAsync({
								id: input.existingPrimaryKeyConstraintId, primaryKeyConstraintPatch: { fieldIds: asFieldIds(remainingFieldIds) },
							});
						} catch (error) {
							errors.push(`Failed to update primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
						}
					} else {
						try {
							await deletePkMutation.mutateAsync({ id: input.existingPrimaryKeyConstraintId });
						} catch (error) {
							errors.push(`Failed to delete primary key constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
						}
					}
				}
			}

			// Step 3: Handle unique constraint changes
			const hasUnique = input.field.constraints.unique;
			const hadUnique = !!input.existingUniqueConstraintId;

			if (hasUnique && !hadUnique) {
				try {
					await createUniqueMutation.mutateAsync({
						tableId: input.tableId,
						databaseId: input.databaseId,
						fieldIds: asFieldIds([input.id]),
						name: `${input.tableName}_${input.field.name}_key`,
						type: 'u',
					});
				} catch (error) {
					errors.push(`Failed to create unique constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
				}
			} else if (!hasUnique && hadUnique && input.existingUniqueConstraintId) {
				try {
					await deleteUniqueMutation.mutateAsync({ id: input.existingUniqueConstraintId });
				} catch (error) {
					errors.push(`Failed to delete unique constraint: ${error instanceof Error ? error.message : 'Unknown error'}`);
				}
			}

			if (errors.length > 0) {
				console.warn('Field updated with constraint errors:', errors.join('; '));
			}

			return updatedField;
		},
		onSuccess: async (_result, variables) => {
			await invalidateDatabaseEntities(queryClient, variables.databaseId ?? currentDatabase?.databaseId);
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to update field:', error);
		},
	});
}

export function useDeleteField() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase } = useSchemaBuilderSelectors();
	const deleteFieldMutation = useDeleteFieldMutation({ selection: { fields: { id: true } } });
	const updatePkMutation = useUpdatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const deletePkMutation = useDeletePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const deleteUniqueMutation = useDeleteUniqueConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: DeleteFieldData): Promise<string> => {
			// Step 1: Handle primary key constraint
			if (input.wasPartOfPrimaryKey && input.primaryKeyConstraintId) {
				if (input.allPrimaryKeyFieldIds && input.allPrimaryKeyFieldIds.length > 1) {
					const remainingFieldIds = input.allPrimaryKeyFieldIds.filter((id) => id !== input.id);
					await updatePkMutation.mutateAsync({
						id: input.primaryKeyConstraintId, primaryKeyConstraintPatch: { fieldIds: asFieldIds(remainingFieldIds) },
					});
				} else {
					await deletePkMutation.mutateAsync({ id: input.primaryKeyConstraintId });
				}
			}

			// Step 2: Handle unique constraint
			if (input.uniqueConstraintId) {
				await deleteUniqueMutation.mutateAsync({ id: input.uniqueConstraintId });
			}

			// Step 3: Delete the field
			await deleteFieldMutation.mutateAsync({ id: input.id });

			return input.id;
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId);
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to delete field:', error);
		},
	});
}

export function useUpdateFieldOrder() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase } = useSchemaBuilderSelectors();
	const updateFieldMutation = useUpdateFieldMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (fieldUpdates: FieldOrderUpdate[]) => {
			const updatePromises = fieldUpdates.map((update) =>
				updateFieldMutation.mutateAsync({
					id: update.id, fieldPatch: { fieldOrder: update.fieldOrder },
				}),
			);

			await Promise.all(updatePromises);
			return fieldUpdates;
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId);
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to update field order:', error);
		},
	});
}

'use client';

import { useCallback, useEffect, useMemo, useState, useTransition } from 'react';
import { Loader2 } from 'lucide-react';

import type { CardComponent } from '@/components/ui/stack';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useCreateIndex, useUpdateIndex } from '../../lib/gql/hooks/schema-builder/use-index-mutations';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { MultiSelect } from '@/components/ui/multi-select';
import { ResponsiveDiagram } from '@/components/ui/responsive-diagram';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { toast } from '@/components/ui/toast';

import type { IndexDefinition, IndexType } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { INDEX_TYPE_LABELS } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { IndexDiagram } from './index-diagram';

const FIELD_SUMMARY_LIMIT = 4;

const indexTypeOptions = (Object.keys(INDEX_TYPE_LABELS) as IndexType[]).map((value) => ({
	value,
	label: value === 'btree' ? `${INDEX_TYPE_LABELS[value]} (default)` : INDEX_TYPE_LABELS[value],
}));

function normalizeIndexType(type: string | undefined | null): IndexType {
	const raw = type?.toLowerCase() as IndexType | undefined;
	return raw && raw in INDEX_TYPE_LABELS ? raw : 'btree';
}

function generateIndexName(tableName: string, existingIndexes: IndexDefinition[]): string {
	let counter = 1;
	let candidateName = `${tableName}_index_${counter}`;

	while (existingIndexes.some((idx) => idx.name === candidateName)) {
		counter++;
		candidateName = `${tableName}_index_${counter}`;
	}

	return candidateName;
}

export type IndexCardProps = {
	editingIndex: IndexDefinition | null;
};

export const IndexCard: CardComponent<IndexCardProps> = ({ editingIndex: initialEditingIndex, card }) => {
	const { currentTable } = useSchemaBuilderSelectors();

	const createIndexMutation = useCreateIndex();
	const updateIndexMutation = useUpdateIndex();

	// useTransition for non-blocking state updates during mount
	const [isPendingTransition, startTransition] = useTransition();

	const indexes = currentTable?.indexes || [];

	// Lazy state initialization - compute initial state once, avoid useEffect re-renders
	const [editingIndex, setEditingIndex] = useState<IndexDefinition | null>(() => {
		if (initialEditingIndex) {
			return {
				...initialEditingIndex,
				fields: [...initialEditingIndex.fields],
				type: normalizeIndexType(initialEditingIndex.type),
			};
		}
		return null; // Will be set when currentTable is available
	});

	const [originalIndex, setOriginalIndex] = useState<IndexDefinition | null>(() => {
		if (initialEditingIndex) {
			return {
				...initialEditingIndex,
				fields: [...initialEditingIndex.fields],
				type: normalizeIndexType(initialEditingIndex.type),
			};
		}
		return null;
	});

	// Compute field options with useMemo
	const fieldOptions = useMemo(
		() =>
			currentTable?.fields.map((field) => ({
				label: field.name,
				value: field.id,
			})) || [],
		[currentTable?.fields],
	);

	const fieldNameMap = useMemo(() => {
		const map: Record<string, string> = {};
		currentTable?.fields.forEach((field) => {
			map[field.id] = field.name;
		});
		return map;
	}, [currentTable?.fields]);

	// Only run effect for NEW index creation (not editing)
	// Use startTransition for non-blocking state update
	useEffect(() => {
		if (!initialEditingIndex && currentTable && !editingIndex) {
			startTransition(() => {
				const generatedName = generateIndexName(currentTable.name, indexes);
				setEditingIndex({
					id: `idx-${Date.now()}`,
					name: generatedName,
					fields: [],
					unique: false,
					type: 'btree',
				});
			});
		}
	}, [initialEditingIndex, currentTable, indexes, editingIndex]);

	const handleSaveIndex = useCallback(async () => {
		if (!editingIndex || editingIndex.fields.length === 0 || !currentTable) return;

		const trimmedName = editingIndex.name?.trim() ?? '';
		if (!trimmedName) return;

		const isExisting = indexes.some((index) => index.id === editingIndex.id);

		try {
			if (isExisting) {
				await updateIndexMutation.mutateAsync({
					id: editingIndex.id,
					name: trimmedName,
					fieldIds: editingIndex.fields,
					isUnique: editingIndex.type === 'btree' ? editingIndex.unique : false,
					accessMethod: editingIndex.type,
				});
				toast.success({
					message: 'Index updated',
					description: `Index "${trimmedName}" has been updated`,
				});
			} else {
				await createIndexMutation.mutateAsync({
					tableId: currentTable.id,
					name: trimmedName,
					fieldIds: editingIndex.fields,
					isUnique: editingIndex.type === 'btree' ? editingIndex.unique : false,
					accessMethod: editingIndex.type,
				});
				toast.success({
					message: 'Index created',
					description: `Index "${trimmedName}" has been created`,
				});
			}
			card.close();
		} catch (error) {
			toast.error({
				message: isExisting ? 'Failed to update index' : 'Failed to create index',
				description: error instanceof Error ? error.message : 'An error occurred',
			});
		}
	}, [editingIndex, currentTable, indexes, updateIndexMutation, createIndexMutation, card]);

	// Memoize form change handlers
	const handleNameChange = useCallback(
		(event: React.ChangeEvent<HTMLInputElement>) => {
			setEditingIndex((prev) => (prev ? { ...prev, name: event.target.value } : null));
		},
		[],
	);

	const handleFieldsChange = useCallback((values: string[]) => {
		setEditingIndex((prev) => (prev ? { ...prev, fields: values } : null));
	}, []);

	const handleTypeChange = useCallback((value: string) => {
		setEditingIndex((prev) =>
			prev
				? {
						...prev,
						type: value as IndexType,
						unique: value === 'btree' ? prev.unique : false,
					}
				: null,
		);
	}, []);

	const handleUniqueChange = useCallback((checked: boolean) => {
		setEditingIndex((prev) => (prev ? { ...prev, unique: checked } : null));
	}, []);

	const handleClose = useCallback(() => {
		card.close();
	}, [card]);

	// Shallow comparison instead of JSON.stringify for better performance
	const hasChanges = useMemo(() => {
		if (originalIndex === null) return true;
		if (!editingIndex) return false;
		return (
			editingIndex.name !== originalIndex.name ||
			editingIndex.type !== originalIndex.type ||
			editingIndex.unique !== originalIndex.unique ||
			editingIndex.fields.length !== originalIndex.fields.length ||
			editingIndex.fields.some((f, i) => f !== originalIndex.fields[i])
		);
	}, [editingIndex, originalIndex]);

	if (!currentTable) return null;

	const isEditMode = initialEditingIndex !== null;
	const selectedIndexType = editingIndex?.type ?? 'btree';
	const selectedFieldNames = editingIndex?.fields.map((id) => fieldNameMap[id] || id) || [];

	const canSave =
		editingIndex && editingIndex.fields.length > 0 && (editingIndex.name?.trim().length ?? 0) > 0 && hasChanges;

	const isPending = createIndexMutation.isPending || updateIndexMutation.isPending;

	return (
		<div className='flex h-full flex-col'>
			<ScrollArea className='min-h-0 flex-1'>
				<div className='space-y-6 p-6'>
					{/* Diagram Section */}
					<ResponsiveDiagram className='py-8'>
						<IndexDiagram
							tableName={currentTable.name}
							indexName={editingIndex?.name}
							fields={selectedFieldNames}
							indexType={selectedIndexType}
							isUnique={editingIndex?.unique ?? false}
						/>
					</ResponsiveDiagram>

					{/* Form Section */}
					{editingIndex && (
						<div className='space-y-4'>
							<div className='space-y-2'>
								<Label className='block' htmlFor='index-name'>
									Index name
								</Label>
								<Input
									id='index-name'
									value={editingIndex.name}
									onChange={handleNameChange}
									placeholder='e.g. table_index_1'
								/>
							</div>

							<div className='space-y-2'>
								<Label className='block'>Fields</Label>
								<MultiSelect
									options={fieldOptions}
									defaultValue={editingIndex.fields}
									onValueChange={handleFieldsChange}
									placeholder='Select fields'
									dropdownMaxHeight='300px'
									maxCount={FIELD_SUMMARY_LIMIT}
								/>
							</div>

							<div className='space-y-2'>
								<Label className='block'>Index type</Label>
								<Select value={selectedIndexType} onValueChange={handleTypeChange}>
									<SelectTrigger>
										<SelectValue placeholder='Select index type' />
									</SelectTrigger>
									<SelectContent>
										{indexTypeOptions.map((option) => (
											<SelectItem key={option.value} value={option.value}>
												{option.label}
											</SelectItem>
										))}
									</SelectContent>
								</Select>
							</div>

							{selectedIndexType === 'btree' && (
								<div className='flex items-center justify-between'>
									<Label htmlFor='index-unique'>Unique</Label>
									<Switch
										id='index-unique'
										checked={editingIndex.unique ?? false}
										onCheckedChange={handleUniqueChange}
									/>
								</div>
							)}
						</div>
					)}
				</div>
			</ScrollArea>

			<div className='flex justify-end gap-2 border-t p-4'>
				<Button variant='outline' disabled={isPending} onClick={handleClose}>
					Cancel
				</Button>
				<Button onClick={handleSaveIndex} disabled={!canSave || isPending}>
					{isPending && <Loader2 className='h-4 w-4 animate-spin' />}
					{isPending ? 'Saving...' : isEditMode ? 'Update index' : 'Create index'}
				</Button>
			</div>
		</div>
	);
};

import { Database, DatabaseZap } from 'lucide-react';

import { cn } from '@/components/schema-builder/lib/utils';

import type { IndexType } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { INDEX_TYPE_LABELS } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';

interface IndexDiagramProps {
	tableName: string;
	indexName?: string;
	fields: string[];
	indexType: IndexType;
	isUnique: boolean;
}

type ColorTheme = {
	primary: string;
	light: string;
	border: string;
	connector: string;
	connectorLight: string;
};

const THEME: ColorTheme = {
	primary: '#6366F1',
	light: '#E0E7FF',
	border: '#A5B4FC',
	connector: '#6366F1',
	connectorLight: '#C7D2FE',
};

const MAX_NAME_WIDTH = 120;

function truncateName(name: string, maxWidth: number): string {
	const avgCharWidth = 7;
	const maxChars = Math.floor(maxWidth / avgCharWidth);
	if (name.length <= maxChars) return name;
	return name.slice(0, maxChars - 1) + '…';
}

function TableFieldsNode({ tableName, fields, theme }: { tableName: string; fields: string[]; theme: ColorTheme }) {
	const displayFields = fields.length > 0 ? fields : ['field'];
	const fieldsLabel = displayFields.join(', ');
	const sizeClasses = 'h-14 w-14';

	return (
		<div className='flex flex-col items-center gap-1.5'>
			<div className='relative'>
				<>
					<div
						className={cn('absolute -top-1.5 -left-2 rounded-full border-2 bg-white', sizeClasses)}
						style={{ borderColor: theme.border }}
					/>
					<div
						className={cn('absolute -top-0.5 -left-1 rounded-full border-2 bg-white', sizeClasses)}
						style={{ borderColor: theme.border }}
					/>
				</>
				<div
					className={cn('relative flex items-center justify-center rounded-full border-2 shadow-sm', sizeClasses)}
					style={{ borderColor: theme.border, backgroundColor: theme.light }}
				>
					<Database className='size-6' style={{ color: theme.primary }} />
				</div>
			</div>
			<div className='flex flex-col items-center gap-0.5'>
				<span
					className='truncate text-sm font-medium text-gray-600 dark:text-gray-300'
					style={{ maxWidth: MAX_NAME_WIDTH }}
					title={tableName}
				>
					{truncateName(tableName || 'Table', MAX_NAME_WIDTH)}
				</span>
				<span
					className='truncate text-xs text-gray-600 dark:text-gray-400'
					style={{ maxWidth: MAX_NAME_WIDTH }}
					title={fieldsLabel}
				>
					{truncateName(fieldsLabel, MAX_NAME_WIDTH)}
				</span>
			</div>
		</div>
	);
}

function IndexNode({
	indexName,
	typeLabel,
	theme,
	isUnique,
}: {
	indexName: string;
	typeLabel: string;
	theme: ColorTheme;
	isUnique: boolean;
}) {
	return (
		<div className='flex flex-col items-center gap-2'>
			<div className='relative'>
				<div
					className='flex flex-col items-center gap-1 rounded-lg border-2 bg-white px-3 py-2'
					style={{ borderColor: theme.border, backgroundColor: theme.light }}
				>
					<DatabaseZap className='size-6' style={{ color: theme.primary }} />
					<span
						className='max-w-[100px] truncate text-center text-xs font-medium'
						style={{ color: theme.primary }}
						title={typeLabel}
					>
						{typeLabel}
					</span>
				</div>
				{isUnique && (
					<div
						className='absolute -right-2 -bottom-2 flex h-6 w-6 items-center justify-center rounded-full border-2
							border-white shadow-sm'
						style={{ backgroundColor: theme.primary }}
					>
						<span className='text-[10px] font-bold text-white'>U</span>
					</div>
				)}
			</div>
			<span className='max-w-[100px] truncate text-center text-sm text-gray-600 dark:text-gray-300' title={indexName}>
				{truncateName(indexName || 'Index', 100)}
			</span>
		</div>
	);
}

function ArrowConnector({ theme, label }: { theme: ColorTheme; label: string }) {
	return (
		<div className='relative flex flex-col items-center justify-center'>
			<div
				className='absolute -top-2 left-1/2 -translate-x-1/2 rounded border px-1.5 py-px text-[10px] leading-tight
					font-medium whitespace-nowrap'
				style={{
					borderColor: theme.primary,
					backgroundColor: theme.light,
					color: theme.primary,
				}}
			>
				{label}
			</div>
			<svg width={90} height='40' viewBox='0 0 90 40' fill='none'>
				<circle cx='6' cy='20' r='4' fill={theme.connector} />
				<line x1='10' y1='20' x2='74' y2='20' stroke={theme.connectorLight} strokeWidth='2.5' strokeLinecap='round' />
				<polygon points='84,20 76,15 76,25' fill={theme.connector} />
			</svg>
		</div>
	);
}

export function IndexDiagram({ tableName, indexName, fields, indexType, isUnique }: IndexDiagramProps) {
	const theme = THEME;
	const safeIndexType = indexType && INDEX_TYPE_LABELS[indexType] ? indexType : 'btree';
	const typeLabel = INDEX_TYPE_LABELS[safeIndexType];

	return (
		<div className='flex items-center justify-center gap-3'>
			<IndexNode indexName={indexName || 'Index'} typeLabel={typeLabel} theme={theme} isUnique={isUnique} />
			<ArrowConnector theme={theme} label='indexes' />
			<TableFieldsNode tableName={tableName} fields={fields} theme={theme} />
		</div>
	);
}

