'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { useCardStack } from '@/components/ui/stack';
import { toast } from '@/components/ui/toast';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { ListTree, Plus } from 'lucide-react';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useDeleteIndex } from '../../../lib/gql/hooks/schema-builder/use-index-mutations';
import type { IndexDefinition } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { INDEX_TYPE_LABELS } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { CARD_WIDTHS } from '@/components/schema-builder/schema/schema-builder-core/lib/stack/card-widths';
import { handleActivationKeyDown } from '@/components/schema-builder/schema/schema-builder-core/lib/keyboard-activation';
import { cn } from '@/components/schema-builder/lib/utils';

import { DeleteConfirmDialog } from '@/components/schema-builder/schema/schema-builder-core/components/table-editor/delete-confirm-dialog';
import {
	CardDeleteButton,
	EditorView,
	editorCardClass,
	InlineCode,
	KindBadge,
	linkedChipClass,
	NoTableSelectedState,
} from '@/components/schema-builder/schema/schema-builder-core/components/table-editor/editor-view';
import { IndexCard } from '../index-card';
import { IndexEmptyState } from './index-empty-state';

const FIELD_SUMMARY_LIMIT = 4;

/** Index columns by name, in index order; ids no longer on the table stay visible as-is. */
function indexColumnNames(fieldIds: string[], tableFields: { id: string; name: string }[]) {
	return fieldIds.map((fieldId) => tableFields.find((field) => field.id === fieldId)?.name || fieldId);
}

export function IndexesView() {
	const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);
	const [isDeleting, setIsDeleting] = useState(false);

	const stack = useCardStack();
	const { currentTable } = useSchemaBuilderSelectors();
	const deleteIndexMutation = useDeleteIndex();

	// No table selected state
	if (!currentTable) {
		return <NoTableSelectedState icon={ListTree} subject='indexes' />;
	}

	const indexes = currentTable.indexes || [];
	const hasIndexes = indexes.length > 0;

	const handleOpenCreate = () => {
		stack.push({
			id: 'index-new',
			title: 'Create Index',
			Component: IndexCard,
			props: { editingIndex: null },
			width: CARD_WIDTHS.medium,
		});
	};

	const handleOpenEdit = (index: IndexDefinition) => {
		stack.push({
			id: `index-${index.id}`,
			title: 'Edit Index',
			Component: IndexCard,
			props: { editingIndex: index },
			width: CARD_WIDTHS.medium,
		});
	};

	const handleDeleteRequest = (indexId: string, indexName: string) => {
		setDeleteTarget({ id: indexId, name: indexName });
	};

	const handleDeleteConfirm = async () => {
		if (!deleteTarget) return;
		setIsDeleting(true);
		try {
			await deleteIndexMutation.mutateAsync({ id: deleteTarget.id });
			toast.success({ message: 'Index deleted' });
			setDeleteTarget(null);
		} catch (error) {
			toast.error({
				message: 'Failed to delete index',
				description: error instanceof Error ? error.message : 'An error occurred',
			});
		} finally {
			setIsDeleting(false);
		}
	};

	return (
		<>
			{!hasIndexes ? (
				<div className='flex min-h-0 flex-1 flex-col overflow-auto p-6'>
					<IndexEmptyState onCreateClick={handleOpenCreate} tableName={currentTable.name} />
				</div>
			) : (
				<EditorView
					actions={
						<Button onClick={handleOpenCreate} size='sm'>
							<Plus aria-hidden='true' data-icon='inline-start' />
							Add index
						</Button>
					}
					description={
						<>
							{indexes.length} index{indexes.length !== 1 ? 'es' : ''} on <InlineCode>{currentTable.name}</InlineCode>
						</>
					}
					title='Indexes'
				>
					<ul className='flex flex-col gap-2'>
						{indexes.map((index) => {
							const fieldNameList = indexColumnNames(index.fields, currentTable.fields);
							const ordered = fieldNameList.length > 1;
							return (
								<li key={index.id}>
									<div
										className={editorCardClass}
										onClick={() => handleOpenEdit(index)}
										onKeyDown={(event) => handleActivationKeyDown(event, () => handleOpenEdit(index))}
										role='button'
										tabIndex={0}
									>
										<div className='flex items-center gap-2'>
											<ListTree aria-hidden='true' className='text-muted-foreground size-3.5 shrink-0' />
											<p className='text-foreground min-w-0 truncate text-[13px] font-medium'>{index.name || 'Unnamed index'}</p>
											<KindBadge className='bg-blue-500/10 text-blue-700 dark:text-blue-300'>
												{INDEX_TYPE_LABELS[index.type ?? 'btree'] ?? index.type ?? 'B-tree'}
											</KindBadge>
											{index.unique ? (
												<KindBadge className='bg-emerald-500/10 text-emerald-700 dark:text-emerald-300'>Unique</KindBadge>
											) : null}
											<span className='ml-auto' />
											<CardDeleteButton label='Delete index' onDelete={() => handleDeleteRequest(index.id, index.name || 'this index')} />
										</div>

										<div className='mt-2.5 flex flex-wrap items-center gap-1.5'>
											{fieldNameList.length > 0 ? (
												<>
													{fieldNameList.slice(0, FIELD_SUMMARY_LIMIT).map((name, position) => (
														<span className={cn(linkedChipClass('idle'), 'gap-1.5')} key={name}>
															{ordered ? (
																<span aria-hidden='true' className='text-subtle-foreground tabular-nums'>
																	{position + 1}
																</span>
															) : null}
															<span className='text-foreground/85'>{name}</span>
														</span>
													))}
													{fieldNameList.length > FIELD_SUMMARY_LIMIT && (
														<Tooltip>
															<TooltipTrigger asChild>
																<span className='text-muted-foreground px-1 text-xs'>
																	+{fieldNameList.length - FIELD_SUMMARY_LIMIT} more
																</span>
															</TooltipTrigger>
															<TooltipContent className='max-w-xs'>{fieldNameList.join(', ')}</TooltipContent>
														</Tooltip>
													)}
												</>
											) : (
												<span className='text-muted-foreground text-xs'>No fields</span>
											)}
										</div>
									</div>
								</li>
							);
						})}
					</ul>
				</EditorView>
			)}

			<DeleteConfirmDialog
				entityType='Index'
				entityName={deleteTarget?.name ?? null}
				open={!!deleteTarget}
				onOpenChange={() => setDeleteTarget(null)}
				onConfirm={handleDeleteConfirm}
				isPending={isDeleting}
			/>
		</>
	);
}

/**
 * Hook for managing indexes
 * Tier 4 wrapper: adds cache invalidation and table selection
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';

import { asFieldIds } from '@/components/schema-builder/schema/schema-builder-core/lib/data';

import {
	useCreateIndexMutation,
	useDeleteIndexMutation,
	useUpdateIndexMutation,
} from '@/components/schema-builder/compat/schema-builder-sdk';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';

export interface CreateIndexInput {
	tableId: string;
	name: string;
	fieldIds: string[];
	isUnique?: boolean | null;
	accessMethod?: string | null;
}

export interface UpdateIndexInput {
	id: string;
	name?: string | null;
	fieldIds?: string[] | null;
	isUnique?: boolean | null;
	accessMethod?: string | null;
}

export interface DeleteIndexInput {
	id: string;
}

export function useCreateIndex() {
	const queryClient = useQueryClient();
	const { selectTable, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const createIndexMutation = useCreateIndexMutation({ selection: { fields: { id: true, name: true } } });

	return useMutation({
		mutationFn: async (input: CreateIndexInput) => {
			const databaseId = currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId;
			if (!databaseId) {
				throw new Error('Database ID not found');
			}

			const result = await createIndexMutation.mutateAsync({
				databaseId,
				tableId: input.tableId,
				name: input.name,
				fieldIds: asFieldIds(input.fieldIds),
				isUnique: input.isUnique ?? false,
				accessMethod: input.accessMethod || 'btree',
			});

			const createdIndex = result.createIndex?.index;
			if (!createdIndex?.id) {
				throw new Error('Failed to create index');
			}
			return { id: createdIndex.id, name: createdIndex.name ?? '' };
		},
		onSuccess: async (_createdIndex, variables) => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);

			// Re-select the table to ensure UI updates
			selectTable(variables.tableId);
		},
		onError: (error) => {
			console.error('Failed to create index:', error);
		},
	});
}

export function useUpdateIndex() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const updateIndexMutation = useUpdateIndexMutation({ selection: { fields: { id: true, name: true } } });

	return useMutation({
		mutationFn: async (input: UpdateIndexInput) => {
			const patch: Record<string, unknown> = {};
			if (input.name !== undefined) patch.name = input.name;
			if (input.fieldIds !== undefined) patch.fieldIds = input.fieldIds;
			if (input.isUnique !== undefined) patch.isUnique = input.isUnique;
			if (input.accessMethod !== undefined) patch.accessMethod = input.accessMethod;

			const result = await updateIndexMutation.mutateAsync({ id: input.id, indexPatch: patch });

			const updatedIndex = result.updateIndex?.index;
			if (!updatedIndex?.id) {
				throw new Error('Failed to update index');
			}
			return { id: updatedIndex.id, name: updatedIndex.name ?? '' };
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);

			// Re-select the current table to ensure UI updates
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to update index:', error);
		},
	});
}

export function useDeleteIndex() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const deleteIndexMutation = useDeleteIndexMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: DeleteIndexInput) => {
			await deleteIndexMutation.mutateAsync({ id: input.id });

			return { id: input.id };
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);

			// Re-select the current table to ensure UI updates
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to delete index:', error);
		},
	});
}

