import { showErrorToast, showSuccessToast } from '@/components/ui/toast';
import { useDeletePolicyMutation, useUpdatePolicyMutation } from '@/components/schema-builder/compat/schema-builder-sdk';
import { Loader2Icon, Pencil, Plus, Search, Trash2 } from 'lucide-react';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import type { DatabasePolicy } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/policies/use-database-policies';
import { mapConditionNodeToAst } from '@/components/schema-builder/schema/schema-builder-core/lib/policies/ast-helpers';
import { mapAstToConditionNode } from '@/components/schema-builder/schema/schema-builder-core/lib/policies/rls-parser';
import { CompositePolicyBuilder, type CompositePolicyData } from '../../policies/composite-policy-builder';
import { injectSchemaFields } from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-config';
import { PolicyConfigForm } from '../../policies/policy-config-form';
import { PolicyDiagramByKey } from '../../policies/policy-diagram';
