export const CreateTableCard: CardComponent<CreateTableCardProps> = ({
	mode = 'create-table',
	tableId,
	tableName: propTableName,
	preSelectedOperation,
	onTableCreated,
	onPoliciesCreated,
	card,
}) => {
	const isAddPoliciesMode = mode === 'add-policies';

	// Form state
	const [tableNameInput, setTableNameInput] = useState(propTableName ?? '');
	const [tableNameTouched, setTableNameTouched] = useState(false);
	const [selectedModel, setSelectedModel] = useState<string | null>(null);
	const [wizardStep, setWizardStep] = useState<WizardStep>('select');
	const [knowMoreCardId, setKnowMoreCardId] = useState<CardId | null>(null);
	const tableNameInputRef = useRef<HTMLInputElement | null>(null);

	// Track if defaults have been initialized with policyType defaults
	const [defaultsInitialized, setDefaultsInitialized] = useState(false);

	// Track scroll position to show/hide shadow on sticky table name
	const [isScrolled, setIsScrolled] = useState(false);

	const scrollAreaRef = useCallback((node: HTMLDivElement | null) => {
		if (!node) return;
		const viewport = node.querySelector<HTMLElement>('[data-slot="scroll-area-viewport"]');
		if (!viewport) return;

		const handleScroll = () => setIsScrolled(viewport.scrollTop > 0);
		const removeScrollListener = () => viewport.removeEventListener('scroll', handleScroll);
		handleScroll();
		viewport.addEventListener('scroll', handleScroll, { passive: true });
		return removeScrollListener;
	}, []);

	// In add-policies mode, use the prop tableName; otherwise use state
	const effectiveTableName = isAddPoliciesMode ? (propTableName ?? '') : tableNameInput;

	useEffect(() => {
		if (wizardStep !== 'select' || isAddPoliciesMode || typeof window.matchMedia !== 'function') return;
		if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
		tableNameInputRef.current?.focus({ preventScroll: true });
	}, [isAddPoliciesMode, wizardStep]);

	const stack = useCardStack();

	const { currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const databaseId = currentDatabase?.databaseId ?? '';
	const schemaId = currentDatabase?.schemaId ?? '';

	const createTableMutation = useCreateTable();
	const { policyTypes, error: policyTypesError } = usePolicyTypes();
	const { createTableWithPolicies, isCreating } = useCreateTableWithPolicies();

	// CRUD policy state management - if preSelectedOperation is set, only enable that operation
	const { defaults, operations, updateDefaults, getEnabledOperations } = useCrudPolicyState(
		undefined,
		preSelectedOperation ? [preSelectedOperation] : undefined,
	);

	// Get selected policy type
	const selectedPolicyType = useMemo(
		() => (selectedModel ? policyTypes.find((pt) => pt.name === selectedModel) : null),
		[selectedModel, policyTypes],
	);

	const isCompositePolicy = selectedModel === 'AuthzComposite';

	// Initialize defaults.policyData with default values when policyType loads
	useEffect(() => {
		if (selectedPolicyType && !defaultsInitialized) {
			// For composite policies, initialize with tree structure containing one default condition
			const defaultPolicyData = isCompositePolicy
				? createEmptyCompositePolicyData('AuthzDirectOwner', getDefaultFormValues(policyTypes[0] ?? selectedPolicyType))
				: getDefaultFormValues(selectedPolicyType);
			updateDefaults({ policyData: defaultPolicyData });
			setDefaultsInitialized(true);
		}
	}, [selectedPolicyType, policyTypes, defaultsInitialized, updateDefaults, isCompositePolicy]);

	// Reset defaults when selection changes
	useEffect(() => {
		setDefaultsInitialized(false);
	}, [selectedModel]);

	const existingTableNames = useMemo(
		() => new Set((currentSchema?.tables || []).map((t) => t.name.toLowerCase())),
		[currentSchema?.tables],
	);

	const tableNameError = useMemo(() => {
		// In add-policies mode, table name is already valid (comes from existing table)
		if (isAddPoliciesMode) return null;

		const trimmed = tableNameInput.trim();
		if (!trimmed) return 'Table name is required';
		if (existingTableNames.has(trimmed.toLowerCase())) return 'Table name already exists';
		if (!/^[a-z_][a-z0-9_]*$/i.test(trimmed)) return 'Use letters, numbers, and underscores only';
		return null;
	}, [tableNameInput, existingTableNames, isAddPoliciesMode]);

	const isTableNameValid = tableNameError === null;
	// In add-policies mode, can proceed if a non-blank model is selected
	// In create-table mode, need valid table name and a selected model
	const canProceed = isAddPoliciesMode
		? selectedModel !== null && selectedModel !== 'blank'
		: isTableNameValid && selectedModel !== null;

	// Composite validity reported by CompositePolicyBuilder via onValidChange callback
	const [compositeValid, setCompositeValid] = useState(false);
	const hasValidCompositeConditions = !isCompositePolicy || compositeValid;

	// Create table with policies
	const handleCreateWithPolicies = useCallback(async () => {
		if (!selectedPolicyType || !databaseId || !schemaId) return;

		const enabledOps = getEnabledOperations();
		if (enabledOps.length === 0) return;

		// Validate composite policy has at least one condition
		if (isCompositePolicy && !hasValidCompositeConditions) return;

		// Prepare operations with injected schema fields in policyData (only enabled ones)
		const preparedOperations = { ...operations };
		for (const op of enabledOps) {
			preparedOperations[op] = {
				...operations[op],
				policyData: injectSchemaFields(operations[op].policyData, schemaId, selectedPolicyType.name),
			};
		}

		// Build table module data from defaults policyData (field name customizations)
		const nodeData = buildNodeData(defaults.policyData, selectedPolicyType);

		// Extract field name overrides for 'needs-fields' category policies
		const fieldNameOverrides: Record<string, string | string[]> = {};
		if (selectedPolicyType.category === 'needs-fields') {
			const fieldsToCreate = getFieldsRequiringColumns(selectedPolicyType.name);
			for (const field of fieldsToCreate) {
				const customName = defaults.policyData[field.key];
				if (Array.isArray(customName) && customName.length > 0) {
					fieldNameOverrides[field.key] = customName;
				} else if (typeof customName === 'string' && customName.trim()) {
					fieldNameOverrides[field.key] = customName;
				}
			}
		}

		// For composite policies, convert tree structure to AST format
		const compositeData = defaults.policyData as CompositePolicyData;
		const enrichedTree = isCompositePolicy ? injectSchemaFieldsIntoCompositeTree(compositeData, schemaId) : undefined;
		const sharedPolicyData = isCompositePolicy
			? (mapConditionNodeToAst(enrichedTree!) ?? {})
			: injectSchemaFields(defaults.policyData, schemaId, selectedPolicyType.name);

		try {
			const result = await createTableWithPolicies({
				databaseId,
				schemaId,
				tableId: isAddPoliciesMode ? tableId : undefined,
				tableName: effectiveTableName.trim(),
				policyType: selectedPolicyType.name,
				dataNodeType: selectedPolicyType.dataNodeType,
				nodeData,
				sharedPolicyData,
				operations: preparedOperations,
				enabledOperations: enabledOps,
				fieldNameOverrides,
				compositeTree: enrichedTree,
			});

			if (isAddPoliciesMode) {
				showSuccessToast({
					message: 'Policies created successfully!',
					description: `${enabledOps.length} policies have been added to "${effectiveTableName}".`,
				});
				onPoliciesCreated?.();
			} else {
				showSuccessToast({
					message: 'Table created successfully!',
					description: `Table "${result.tableName}" with ${enabledOps.length} policies has been created.`,
				});
				onTableCreated?.({ id: result.tableId, name: result.tableName });
			}

			// Reset form state and close
			setTableNameInput('');
			setTableNameTouched(false);
			setSelectedModel(null);
			setWizardStep('select');
			card.close();
		} catch (error) {
			showErrorToast({
				message: isAddPoliciesMode ? 'Failed to create policies' : 'Failed to create table',
				description: error instanceof Error ? error.message : 'An unexpected error occurred.',
			});
		}
	}, [
		selectedPolicyType,
		databaseId,
		schemaId,
		getEnabledOperations,
		isCompositePolicy,
		hasValidCompositeConditions,
		operations,
		defaults.policyData,
		createTableWithPolicies,
		isAddPoliciesMode,
		tableId,
		effectiveTableName,
		onPoliciesCreated,
		onTableCreated,
		card,
	]);

	// Handle Next button click - always go to config step
	const handleNext = useCallback(() => {
		if (!selectedModel || selectedModel === 'blank') return;

		// Close Know More card if open
		if (knowMoreCardId && stack.has(knowMoreCardId)) {
			stack.dismiss(knowMoreCardId, { cascade: false });
			setKnowMoreCardId(null);
		}

		// Always show config step (even for policies with no config, they see policy info)
		setWizardStep('config');
	}, [selectedModel, knowMoreCardId, stack]);

	// Update Know More card when selection changes
	useEffect(() => {
		if (!knowMoreCardId) return;
		if (!stack.has(knowMoreCardId)) {
			setKnowMoreCardId(null);
			return;
		}

		// If blank is selected or no selection, close Know More
		if (!selectedModel || selectedModel === 'blank') {
			stack.dismiss(knowMoreCardId, { cascade: false });
			setKnowMoreCardId(null);
			return;
		}

		// Find the policy type for the current selection
		if (selectedPolicyType) {
			stack.updateProps<PolicyKnowMoreCardProps>(knowMoreCardId, {
				policyType: selectedPolicyType,
				onApply: handleNext,
			});
		}
	}, [knowMoreCardId, selectedModel, stack, selectedPolicyType, handleNext]);

	// Handle Know More card
	const handleKnowMore = (policyType: MergedPolicyType) => {
		// Select this policy type
		setSelectedModel(policyType.name);

		// If Know More card already open, just update it (handled by useEffect)
		if (knowMoreCardId && stack.has(knowMoreCardId)) {
			return;
		}

		// Push Know More card
		const pushedId = card.push({
			id: `know-more-${policyType.name}`,
			title: 'Policy Details',
			Component: PolicyKnowMoreCard,
			props: {
				policyType,
				onApply: handleNext, // handleNext will create directly or show config step
			},
			onClose: () => {
				setKnowMoreCardId(null);
			},
			width: 420,
		});

		setKnowMoreCardId(pushedId);
	};

	// Handle blank table creation directly (only in create-table mode)
	const handleCreateBlankTable = async () => {
		if (!isTableNameValid || !databaseId || !schemaId || isAddPoliciesMode) return;

		try {
			const result = await createTableMutation.mutateAsync({
				name: tableNameInput.trim(),
				databaseId,
				schemaId,
				useRls: true,
			});

			showSuccessToast({
				message: 'Table created successfully!',
				description: `Table "${result.name}" has been created with RLS enabled.`,
			});

			onTableCreated?.(result);
			// Reset form state before closing
			setTableNameInput('');
			setTableNameTouched(false);
			setSelectedModel(null);
			card.close();
		} catch (error) {
			showErrorToast({
				message: 'Failed to create table',
				description: error instanceof Error ? error.message : 'An unexpected error occurred.',
			});
		}
	};

	const handleSubmit = () => {
		if (selectedModel === 'blank' && !isAddPoliciesMode) {
			handleCreateBlankTable();
		} else {
			handleNext();
		}
	};

	const handleBack = () => {
		setWizardStep('select');
	};

	const isLoading = createTableMutation.isPending || isCreating;

	// Determine button text and disabled state based on wizard step
	const getButtonConfig = () => {
		if (wizardStep === 'config') {
			return {
				text: isAddPoliciesMode ? 'Create Policy' : 'Create Table',
				disabled: isLoading || (isCompositePolicy && !hasValidCompositeConditions),
				action: handleCreateWithPolicies,
			};
		}
		// Select step
		if (selectedModel === 'blank' && !isAddPoliciesMode) {
			return {
				text: 'Create Table',
				disabled: !canProceed || isLoading,
				action: handleSubmit,
			};
		}
		return {
			text: 'Next',
			disabled: !canProceed || isLoading,
			action: handleSubmit,
		};
	};

	const buttonConfig = getButtonConfig();

	return (
		<div className='flex h-full flex-col'>
			{/* Stepper - always visible, centered */}
			<div className='flex justify-center border-b px-6 py-4'>
				<Stepper value={wizardStep === 'select' ? 1 : 2} className='inline-flex !w-auto items-start'>
					<StepperItem step={1}>
						<div className='flex flex-col items-center gap-1'>
							<StepperIndicator />
							<StepperTitle className='text-xs whitespace-nowrap'>Select Policy</StepperTitle>
						</div>
					</StepperItem>
					{/* Connector line - vertically centered with indicators (size-6 = 24px, center at 12px) */}
					<div className='bg-border -mx-1 mt-[11px] h-px w-20 shrink-0' />
					<StepperItem step={2}>
						<div className='flex flex-col items-center gap-1'>
							<StepperIndicator />
							<StepperTitle className='text-xs whitespace-nowrap'>Configure Policy</StepperTitle>
						</div>
					</StepperItem>
				</Stepper>
			</div>

			{/* Table Name Input - sticky above scroll area, only in create-table mode */}
			{wizardStep === 'select' && !isAddPoliciesMode && (
				<div className={cn('bg-card relative z-10 px-6 pt-6 pb-4 transition-shadow', isScrolled && 'shadow-md')}>
					<Field
						label='Table Name'
						required
						htmlFor='table-name'
						error={tableNameTouched ? (tableNameError ?? undefined) : undefined}
					>
						<Input
							id='table-name'
							data-testid='table-name-input'
							ref={tableNameInputRef}
							value={tableNameInput}
							onChange={(e) => setTableNameInput(e.target.value)}
							onBlur={() => setTableNameTouched(true)}
							placeholder='e.g., posts, comments, orders'
							autoComplete='off'
							className={cn('font-mono', tableNameTouched && tableNameError && 'border-destructive')}
						/>
					</Field>
				</div>
			)}

			<ScrollArea ref={scrollAreaRef} className='min-h-0 flex-1'>
				{wizardStep === 'select' ? (
					<div className='space-y-6 p-6 pt-2'>
						{/* Access Model Selection */}
						<div className='space-y-3'>
							<p className='text-muted-foreground text-xs font-semibold tracking-wide uppercase'>Select Access Model</p>

							{/* Show error only if no fallback data available */}
							{policyTypesError && policyTypes.length === 0 && (
								<div className='rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-950/30'>
									<p className='text-sm text-red-600 dark:text-red-400'>Failed to load policy types</p>
								</div>
							)}

							{/* Always show policy types (fallback data provides immediate availability) */}
							<div className='grid min-w-0 grid-cols-[minmax(0,1fr)] gap-3 sm:grid-cols-2'>
								{policyTypes.map((policyType) => (
									<PolicyTypeCard
										key={policyType.name}
										policyType={policyType}
										tableName={effectiveTableName.trim()}
										isSelected={selectedModel === policyType.name}
										onSelect={() => setSelectedModel(policyType.name)}
										onKnowMore={() => handleKnowMore(policyType)}
									/>
								))}
								{/* Blank table option - only in create-table mode */}
								{!isAddPoliciesMode && (
									<BlankTableCard isSelected={selectedModel === 'blank'} onSelect={() => setSelectedModel('blank')} />
								)}
							</div>
						</div>
					</div>
				) : (
					<div className='p-6'>
						{selectedPolicyType && (
							<PolicyConfigContent
								policyType={selectedPolicyType}
								policyTypes={policyTypes}
								tableName={effectiveTableName.trim()}
								defaults={defaults}
								updateDefaults={updateDefaults}
								isCreating={isCreating}
								onCompositeValidChange={setCompositeValid}
							/>
						)}
					</div>
				)}
			</ScrollArea>

			<div className='flex justify-end gap-2 border-t p-4'>
				{wizardStep === 'config' ? (
					<>
						<Button variant='outline' onClick={handleBack} disabled={isLoading}>
							Back
						</Button>
						<Button onClick={buttonConfig.action} disabled={buttonConfig.disabled}>
							{isLoading && <Loader2Icon className='mr-2 h-4 w-4 animate-spin' />}
							{isLoading ? 'Creating...' : buttonConfig.text}
						</Button>
					</>
				) : (
					<>
						<Button variant='outline' onClick={() => card.close()} disabled={isLoading}>
							Cancel
						</Button>
						<Button onClick={buttonConfig.action} disabled={buttonConfig.disabled}>
							{isLoading && <Loader2Icon className='mr-2 h-4 w-4 animate-spin' />}
							{isLoading ? 'Creating...' : buttonConfig.text}
						</Button>
					</>
				)}
			</div>
		</div>
	);
};

/**
 * Hook for fetching app and membership capabilities
 * Tier 4 wrapper: Uses SDK hooks + cache invalidation
 */
import { useQuery } from '@tanstack/react-query';
import {
	schemaBuilderQueryKey,
	useAdminSdkClient,
	useSchemaBuilderRuntime,
} from '@/components/schema-builder/compat/block-config';

/**
 * `permission` is an ordinary capability an operator can grant; `level` is compiled
 * into the same bitstring by the trust ladder and is not operator-managed.
 */
export type CapabilityKind = 'permission' | 'level';

export interface CapabilityNode {
	bitnum: number | null;
	bitstr: string | null;
	description: string | null;
	id: string;
	kind: CapabilityKind;
	name: string;
}

export type AppCapability = CapabilityNode;
export type MembershipCapability = CapabilityNode;

export const capabilitiesQueryKeys = {
	all: ['capabilities'] as const,
};

export interface UseCapabilitiesOptions {
	enabled?: boolean;
}

function toCapabilityKind(kind: string | null | undefined): CapabilityKind {
	return kind === 'level' ? 'level' : 'permission';
}

export function useCapabilities(options: UseCapabilitiesOptions = {}) {
	const isEnabled = options.enabled !== false;
	const { scope } = useSchemaBuilderRuntime();
	const { fetchAppCapabilitiesQuery, fetchOrgCapabilitiesQuery } = useAdminSdkClient();

	return useQuery<{ appCapabilities: AppCapability[]; membershipCapabilities: MembershipCapability[] }>({
		queryKey: schemaBuilderQueryKey(scope, 'policies', 'capabilities'),
		queryFn: async () => {
			// Fetch both capability types in parallel using SDK fetch functions
			const [appResult, orgResult] = await Promise.all([
				fetchAppCapabilitiesQuery({ selection: { fields: { id: true, name: true, bitnum: true, bitstr: true, description: true, kind: true }, orderBy: ['NAME_ASC'] } }),
				fetchOrgCapabilitiesQuery({ selection: { fields: { id: true, name: true, bitnum: true, bitstr: true, description: true, kind: true }, orderBy: ['NAME_ASC'] } }),
			]);

			const appCapabilities: AppCapability[] = (appResult.appCapabilities?.nodes ?? []).map((node) => ({
				id: node.id ?? '',
				name: node.name ?? '',
				bitnum: node.bitnum ?? null,
				bitstr: node.bitstr ?? null,
				description: node.description ?? null,
				kind: toCapabilityKind(node.kind),
			}));

			const membershipCapabilities: MembershipCapability[] = (orgResult.orgCapabilities?.nodes ?? []).map((node) => ({
				id: node.id ?? '',
				name: node.name ?? '',
				bitnum: node.bitnum ?? null,
				bitstr: node.bitstr ?? null,
				description: node.description ?? null,
				kind: toCapabilityKind(node.kind),
			}));

			return {
				appCapabilities,
				membershipCapabilities,
			};
		},
		enabled: isEnabled,
		staleTime: 5 * 60 * 1000,
		refetchOnMount: isEnabled,
		refetchOnWindowFocus: false,
		refetchOnReconnect: false,
	});
}

/**
 * Hook for creating fields for policies
 * Tier 4 wrapper: uses SDK + transform + custom cache invalidation
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCreateFieldMutation } from '@/components/schema-builder/compat/schema-builder-sdk';
import { fieldTypeToTypeName, toFieldType } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/transformers/field-type-mapper';
import { databasePoliciesQueryKeys } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/policies/use-database-policies';

export type PolicyFieldType = 'uuid' | 'uuid[]' | 'timestamptz' | 'boolean';

export interface CreatePolicyFieldInput {
	name: string;
	tableId: string;
	databaseId: string;
	fieldType: PolicyFieldType;
}

export function useCreatePolicyField() {
	const queryClient = useQueryClient();
	const createFieldMutation = useCreateFieldMutation({ selection: { fields: { id: true, name: true, type: true } } });

	return useMutation({
		mutationFn: async (input: CreatePolicyFieldInput) => {
			const result = await createFieldMutation.mutateAsync({
				name: input.name,
				tableId: input.tableId,
				databaseId: input.databaseId,
				// type is a structured JSONB object in the metaschema now.
				type: toFieldType(input.fieldType) as unknown as Record<string, unknown>,
				isRequired: false,
			});

			const createdField = result.createField?.field;
			if (!createdField?.id) {
				throw new Error('Failed to create field');
			}

			return { id: createdField.id, name: createdField.name ?? '', type: fieldTypeToTypeName(createdField.type) };
		},
		onSuccess: async (_createdField, variables) => {
			await queryClient.invalidateQueries({
				queryKey: databasePoliciesQueryKeys.byDatabase(variables.databaseId),
			});
		},
	});
}

/**
 * Hook for creating a table
 * Tier 4 wrapper: adds auto-grant capabilities and table selection
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCreateTableMutation } from '@/components/schema-builder/compat/schema-builder-sdk';
import type { CreateTableInput } from '@/components/schema-builder/compat/schema-builder-sdk';

import { stripEmpty } from '@/components/schema-builder/schema/schema-builder-core/lib/data';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useCreateTableGrant } from './use-table-grants';

export interface CreateTableData {
	name: string;
	schemaId: string;
	databaseId: string;
	description?: string | null;
	label?: string | null;
	smartTags?: Record<string, unknown> | null;
	useRls?: boolean | null;
}

// Return type with non-nullable id for consumer safety
export interface CreatedTable {
	id: string;
	name: string;
	databaseId: string | null;
	schemaId: string | null;
	label: string | null;
	description: string | null;
}

export function useCreateTable() {
	const queryClient = useQueryClient();
	const { selectTable } = useSchemaBuilderSelectors();
	const { mutateAsync: createGrant } = useCreateTableGrant();
	const createTableMutation = useCreateTableMutation({ selection: { fields: { id: true, name: true, databaseId: true, schemaId: true, label: true, description: true } } });

	return useMutation({
		mutationFn: async (input: CreateTableData): Promise<CreatedTable> => {
			// Step 1: Create the table using SDK
			// inheritsId is required in generated types but optional at GraphQL level
			const result = await createTableMutation.mutateAsync({
				name: input.name,
				schemaId: input.schemaId,
				databaseId: input.databaseId,
				description: stripEmpty(input.description),
				label: stripEmpty(input.label),
				smartTags: stripEmpty(input.smartTags),
				useRls: stripEmpty(input.useRls),
			} as CreateTableInput['table']);

			const table = result.createTable?.table;
			if (!table?.id || !table?.name) {
				throw new Error('Failed to create table');
			}

			// Step 2: Auto-grant basic capabilities to make table immediately usable
			// Default strategy: Grant all CRUD operations to authenticated users (no RLS)
			// This ensures the table is accessible via the application GraphQL endpoint
			if (input.databaseId && table.name) {
				try {
					await createGrant({
						databaseId: input.databaseId,
						tableName: table.name,
						privileges: ['select', 'insert', 'update', 'delete'],
						roleName: 'authenticated',
					});
				} catch (error) {
					// Log warning but don't fail table creation
					console.warn(
						`⚠️ Table created successfully but failed to grant capabilities: ${error instanceof Error ? error.message : 'Unknown error'}`,
					);
					console.warn(`You may need to manually grant capabilities for table: ${table.name}`);
				}
			}

			// Return with guaranteed non-null id/name after validation
			return {
				id: table.id,
				name: table.name,
				databaseId: table.databaseId ?? null,
				schemaId: table.schemaId ?? null,
				label: table.label ?? null,
				description: table.description ?? null,
			};
		},
		onSuccess: async (createdTable, variables) => {
			await invalidateDatabaseEntities(queryClient, variables?.databaseId);

			if (createdTable?.id && createdTable?.name) {
				selectTable(createdTable.id, createdTable.name);
			}
		},
		onError: (error) => {
			console.error(error);
		},
	});
}

/**
 * Hook for managing table grants (capabilities)
 * Tier 4 wrapper: orchestrates table lookup + grant creation using SDK hooks
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';

import {
	useCreateTableGrantMutation,
} from '@/components/schema-builder/compat/schema-builder-sdk';
import { useSchemaBuilderSdkClient } from '@/components/schema-builder/compat/block-config';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';

// ============================================================================
// Types
// ============================================================================

export interface CreateTableGrantInput {
	databaseId: string;
	tableName: string;
	privileges: string[]; // ['select', 'insert', 'update', 'delete']
	fieldNames?: string[]; // Optional: for field-level grants
	roleName?: string; // Default: 'authenticated'
}

interface TableWithFields {
	id: string;
	name: string;
	useRls: boolean;
	fields: Array<{
		id: string;
		name: string;
	}>;
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Fetches table metadata including fields by database ID and table name.
 * Required for grant operations to get table ID and field IDs.
 * Uses SDK hooks via composition.
 */
async function getTableByName(
	databaseId: string,
	tableName: string,
	client: Pick<ReturnType<typeof useSchemaBuilderSdkClient>, 'fetchFieldsQuery' | 'fetchTablesQuery'>,
): Promise<TableWithFields | null> {
	try {
		// Step 1: Fetch table by database ID and name
		const tableResult = await client.fetchTablesQuery({
			selection: {
				fields: { id: true, name: true, useRls: true },
				where: { databaseId: { equalTo: databaseId }, name: { equalTo: tableName } },
				first: 1,
			},
		});
		const table = tableResult?.tables?.nodes?.[0];
		if (!table?.id) {
			return null;
		}

		// Step 2: Fetch fields for this table
		const fieldsResult = await client.fetchFieldsQuery({
			selection: {
				fields: { id: true, name: true },
				where: { tableId: { equalTo: table.id } },
			},
		});
		const fields = fieldsResult?.fields?.nodes ?? [];

		return {
			id: table.id,
			name: table.name ?? tableName,
			useRls: table.useRls ?? false,
			fields: fields.map((f) => ({
				id: f.id ?? '',
				name: f.name ?? '',
			})).filter((f) => f.id && f.name),
		};
	} catch (error) {
		console.error(`Failed to fetch table ${tableName}:`, error);
		return null;
	}
}

/**
 * Resolves field names to field IDs using table metadata.
 */
function resolveFieldIds(table: TableWithFields, fieldNames: string[]): string[] {
	const fieldIds: string[] = [];
	for (const fieldName of fieldNames) {
		const field = table.fields.find((f) => f.name === fieldName);
		if (field) {
			fieldIds.push(field.id);
		} else {
			console.warn(`Field ${fieldName} not found in table ${table.name}, skipping from grant`);
		}
	}
	return fieldIds;
}

// ============================================================================
// Hooks
// ============================================================================

/**
 * Hook for creating table grants (capabilities).
 * Supports both table-level grants (all fields) and field-level grants (specific fields).
 *
 * @example
 * // Table-level grant (all fields)
 * createGrant({
 *   databaseId: 'xxx',
 *   tableName: 'products',
 *   privileges: ['select', 'delete']
 * })
 *
 * @example
 * // Field-level grant (specific fields only)
 * createGrant({
 *   databaseId: 'xxx',
 *   tableName: 'products',
 *   privileges: ['insert'],
 *   fieldNames: ['name', 'description', 'price']
 * })
 */
export function useCreateTableGrant() {
	const queryClient = useQueryClient();
	const sdkClient = useSchemaBuilderSdkClient();
	const createGrantMutation = useCreateTableGrantMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: CreateTableGrantInput) => {
			const { databaseId, tableName, privileges, fieldNames, roleName = 'authenticated' } = input;

			// Step 1: Fetch table metadata
			const table = await getTableByName(databaseId, tableName, sdkClient);
			if (!table) {
				throw new Error(`Table ${tableName} not found`);
			}

			// Step 2: Resolve field names to field IDs (if specified)
			let fieldIds: string[] | undefined;
			if (fieldNames && fieldNames.length > 0) {
				fieldIds = resolveFieldIds(table, fieldNames);
				if (fieldIds.length === 0) {
					throw new Error(`No valid fields found for grant on table ${tableName}`);
				}
			}

			// Step 3: Create a grant for each privilege
			const results = [];
			for (const privilege of privileges) {
				try {
					const grantInput: Record<string, unknown> = {
						tableId: table.id,
						privilege,
						granteeName: roleName,
						...(fieldIds && fieldIds.length > 0 && { fieldIds }),
					};

					const result = await createGrantMutation.mutateAsync(
						grantInput as any,
					);
					results.push(result);
				} catch (error: any) {
					// Check if it's a duplicate error (grant already exists)
					const isDuplicate =
						error?.message?.includes('already exists') ||
						error?.message?.includes('duplicate key') ||
						error?.message?.includes('unique constraint') ||
						error?.message?.includes('unique violation');

					if (isDuplicate) {
						// Grant already exists; continue with next privilege
						continue;
					}

					// Re-throw non-duplicate errors
					throw new Error(`Failed to create ${privilege} grant on ${tableName}: ${error.message}`);
				}
			}

			return results;
		},
		onSuccess: async (_result, variables: CreateTableGrantInput) => {
			await invalidateDatabaseEntities(queryClient, variables.databaseId);
		},
		onError: (error) => {
			console.error('Failed to create table grant:', error);
		},
	});
}

/**
 * Hook for creating multiple table grants in batch.
 * Useful when setting up a new table with standard capabilities.
 *
 * @example
 * batchCreateGrants({
 *   databaseId: 'xxx',
 *   tableName: 'products',
 *   grants: [
 *     { privileges: ['select', 'delete'] }, // All fields
 *     { privileges: ['insert'], fieldNames: ['name', 'price'] }, // Specific fields
 *     { privileges: ['update'], fieldNames: ['name', 'description'] },
 *   ]
 * })
 */
export function useBatchCreateTableGrants() {
	const { mutateAsync: createGrant } = useCreateTableGrant();

	return useMutation({
		mutationFn: async (input: {
			databaseId: string;
			tableName: string;
			grants: Array<{
				privileges: string[];
				fieldNames?: string[];
				roleName?: string;
			}>;
		}) => {
			const { databaseId, tableName, grants } = input;

			// Execute grants sequentially to maintain order
			const results = [];
			for (const grant of grants) {
				try {
					const result = await createGrant({
						databaseId,
						tableName,
						...grant,
					});
					results.push(result);
				} catch (error) {
					console.error(`Failed to create grant for ${tableName}:`, error);
					// Continue with remaining grants even if one fails
				}
			}

			return results;
		},
		onError: (error) => {
			console.error('Failed to create batch grants:', error);
		},
	});
}

