import {
	connectorWidthForLabel,
	fanConnectorWidth,
	nodeWidth,
	SvgConnector,
	SvgDiagramNode,
	SvgFanConnector,
	SvgTopLabel,
	topLabelBoxWidth,
	CENTER_Y,
	NODE_TOTAL_HEIGHT,
} from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-diagram/svg-primitives';
import type { ColorTheme } from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-diagram/diagram-themes';
import { DATABASE_ICON, TABLE2_ICON } from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-diagram/svg-icons';
