export function RelationshipsView() {
	const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);
	const [isDeleting, setIsDeleting] = useState(false);

	const stack = useCardStack();
	const { currentTable, currentSchema, currentDatabase } = useSchemaBuilderSelectors();
	const deleteForeignKeyMutation = useDeleteForeignKey();

	const tables = currentSchema?.tables || [];
	const databaseId = currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId ?? '';

	const { data: provisionsData } = useRelationProvisionsQuery({
		selection: {
			fields: {
				id: true,
				relationType: true,
				sourceTableId: true,
				targetTableId: true,
				outFieldId: true,
				outJunctionTableId: true,
				exposeInApi: true,
			},
			where: databaseId ? { databaseId: { equalTo: databaseId } } : undefined,
		},
		enabled: !!databaseId,
	});

	const provisions = useMemo<RelationProvisionInfo[]>(() => {
		const nodes = provisionsData?.relationProvisions?.nodes;
		if (!nodes) return [];
		return nodes.map((n) => ({
			id: n.id,
			relationType: n.relationType ?? null,
			sourceTableId: n.sourceTableId ?? null,
			targetTableId: n.targetTableId ?? null,
			outFieldId: n.outFieldId ?? null,
			outJunctionTableId: n.outJunctionTableId ?? null,
			exposeInApi: n.exposeInApi ?? null,
		}));
	}, [provisionsData]);

	const relationships = useMemo<TableRelationship[]>(
		() => getTableRelationships(currentTable, tables, provisions),
		[currentTable, tables, provisions],
	);

	const handleOpenCreate = () => {
		if (!currentTable) return;
		stack.push({
			id: 'relationship-new',
			title: 'Create Relationship',
			Component: RelationshipCard,
			props: {
				editingRelationship: null,
				sourceTable: currentTable,
			},
			width: 540,
		});
	};

	const handleOpenEdit = (rel: TableRelationship) => {
		const sourceTable = rel.sourceTable ?? currentTable;
		if (!sourceTable) return;
		stack.push({
			id: `relationship-edit-${rel.constraint.id}`,
			title: 'Edit Relationship',
			Component: RelationshipCard,
			props: {
				editingRelationship: rel,
				sourceTable,
			},
			width: 540,
		});
	};

	const handleDeleteRequest = (constraintId: string, constraintName: string) => {
		setDeleteTarget({ id: constraintId, name: constraintName });
	};

	const handleDeleteConfirm = async () => {
		if (!deleteTarget) return;
		setIsDeleting(true);
		try {
			await deleteForeignKeyMutation.mutateAsync({ id: deleteTarget.id });
			toast.success({ message: 'Relationship deleted' });
			setDeleteTarget(null);
		} catch (error) {
			toast.error({
				message: 'Failed to delete relationship',
				description: error instanceof Error ? error.message : 'An error occurred',
			});
		} finally {
			setIsDeleting(false);
		}
	};

	// No table selected state
	if (!currentTable) {
		return <NoTableSelectedState icon={Link2} subject='relationships' />;
	}

	const hasRelationships = relationships.length > 0;

	return (
		<>
			{!hasRelationships ? (
				<div className='flex min-h-0 flex-1 flex-col overflow-auto p-6'>
					<RelationshipEmptyState onCreateClick={handleOpenCreate} tableName={currentTable.name} />
				</div>
			) : (
				<EditorView
					actions={
						<Button onClick={handleOpenCreate} size='sm'>
							<Link2 aria-hidden='true' data-icon='inline-start' />
							Add relationship
						</Button>
					}
					data-chat-component='relationships-view'
					data-chat-relationship-count={String(relationships.length)}
					description={
						<>
							{relationships.length} connection{relationships.length !== 1 ? 's' : ''} for <InlineCode>{currentTable.name}</InlineCode>
						</>
					}
					title='Relationships'
				>
					<ul className='flex flex-col gap-2'>
						{relationships.map((rel) => (
							<RelationshipRow
								key={rel.constraint.id}
								onDelete={() => handleDeleteRequest(rel.constraint.id, rel.constraint.name || 'this relationship')}
								onOpen={() => handleOpenEdit(rel)}
								relationship={rel}
								tables={tables}
							/>
						))}
					</ul>
				</EditorView>
			)}

			<DeleteConfirmDialog
				entityType='Relationship'
				entityName={deleteTarget?.name ?? null}
				open={!!deleteTarget}
				onOpenChange={() => setDeleteTarget(null)}
				onConfirm={handleDeleteConfirm}
				isPending={isDeleting}
			/>
		</>
	);
}

type LinkEnd = 'source' | 'junction' | 'target';

/** Which end of a connection a chip is: the hovered one, a lit counterpart, or at rest. */
function chipState(hovered: LinkEnd | null, end: LinkEnd) {
	if (hovered === null) return 'idle' as const;
	return hovered === end ? ('source' as const) : ('linked' as const);
}

function TableChip({
	table,
	field,
	fieldClass,
	end,
	hovered,
	onHover,
	muted = false,
}: {
	table: string;
	field?: string;
	fieldClass: string;
	end: LinkEnd;
	hovered: LinkEnd | null;
	onHover: (end: LinkEnd | null) => void;
	muted?: boolean;
}) {
	const state = chipState(hovered, end);
	return (
		<span
			className={cn(linkedChipClass(state), muted && state === 'idle' && 'bg-transparent ring-0 outline-1 -outline-offset-1 outline-dashed outline-foreground/20')}
			onPointerEnter={() => onHover(end)}
			onPointerLeave={() => onHover(null)}
		>
			<span className={cn('truncate', state === 'linked' ? 'text-primary' : muted ? 'text-muted-foreground' : 'text-foreground')}>
				{table}
			</span>
			{field ? (
				<>
					<span className='text-muted-foreground'>.</span>
					<span className={cn('truncate', fieldClass)}>{field}</span>
				</>
			) : null}
		</span>
	);
}

/**
 * One foreign key as a card: its name and type, the joined ends as chips,
 * and the delete rule. Pointing at one end lights the other end (and the
 * connector) in the Constructive blue, so the pair reads at a glance.
 */
function RelationshipRow({
	relationship: rel,
	tables,
	onOpen,
	onDelete: onDeleteRequest,
}: {
	relationship: TableRelationship;
	tables: TableDefinition[];
	onOpen: () => void;
	onDelete: () => void;
}) {
	const [hovered, setHovered] = useState<LinkEnd | null>(null);
	const style = RELATIONSHIP_STYLES[rel.relationshipType];
	const isM2M = Boolean(rel.withTableName);
	const connectorClass = cn('shrink-0', hovered ? 'text-primary' : style.text);
	const onDelete = (
		<>
			On delete <span className='text-foreground/80'>{ForeignKeyActionLabels[rel.constraint.onDelete ?? ForeignKeyActions.NO_ACTION]}</span>
		</>
	);

	// Many-to-many cards show the far table and the junction's two keys.
	let junctionTargetFieldName: string | undefined;
	let targetPkFieldName: string | undefined;
	if (isM2M && rel.targetTable) {
		const junction = rel.targetTable;
		const actualTarget = tables.find((t) => t.name === rel.withTableName);
		const junctionFk = actualTarget
			? (junction.constraints || []).find(
					(c): c is ForeignKeyConstraint => c.type === 'foreign_key' && c.referencedTable === actualTarget.id,
				)
			: undefined;
		if (actualTarget && junctionFk) {
			junctionTargetFieldName = junction.fields.find((f) => f.id === junctionFk.fields[0])?.name;
			targetPkFieldName = actualTarget.fields.find((f) => f.id === junctionFk.referencedFields?.[0])?.name;
		}
	}

	return (
		<li>
			<div
				className={editorCardClass}
				data-testid='relationship-row'
				onClick={onOpen}
				onKeyDown={(event) => handleActivationKeyDown(event, onOpen)}
				role='button'
				tabIndex={0}
			>
				<div className='flex items-center gap-2'>
					<Link2 aria-hidden='true' className='text-muted-foreground size-3.5 shrink-0' />
					<p className='text-foreground min-w-0 truncate text-[13px] font-medium'>{rel.constraint.name}</p>
					<KindBadge className={style.badge}>{style.label}</KindBadge>
					<span className='text-muted-foreground ml-auto hidden shrink-0 text-xs sm:inline'>{onDelete}</span>
					<CardDeleteButton label='Delete relationship' onDelete={onDeleteRequest} />
				</div>

				<div className='mt-2.5 flex min-w-0 flex-wrap items-center gap-1.5'>
					<TableChip
						end='source'
						field={rel.sourceFieldName || '?'}
						fieldClass={style.text}
						hovered={hovered}
						onHover={setHovered}
						table={rel.sourceTable?.name || '?'}
					/>
					<span className={connectorClass}>
						<MiniConnector type={isM2M ? 'many-to-many' : rel.relationshipType} />
					</span>
					{isM2M ? (
						<>
							<TableChip
								end='junction'
								fieldClass={style.text}
								hovered={hovered}
								muted
								onHover={setHovered}
								table={rel.targetTable?.name || '?'}
							/>
							<span className={connectorClass}>
								<MiniConnector type='many-to-many' />
							</span>
							<TableChip
								end='target'
								field={targetPkFieldName || 'id'}
								fieldClass={style.text}
								hovered={hovered}
								onHover={setHovered}
								table={rel.withTableName ?? '?'}
							/>
						</>
					) : (
						<TableChip
							end='target'
							field={rel.targetFieldName || '?'}
							fieldClass={style.text}
							hovered={hovered}
							onHover={setHovered}
							table={rel.targetTable?.name || '?'}
						/>
					)}
				</div>

				{isM2M ? (
					<p className='text-muted-foreground mt-2 flex items-center gap-1 text-[11px]'>
						via
						<span className='bg-muted/70 rounded px-1 font-mono'>{rel.targetFieldName || '?'}</span>
						and
						<span className='bg-muted/70 rounded px-1 font-mono'>{junctionTargetFieldName || '?'}</span>
					</p>
				) : null}
				<p className='text-muted-foreground mt-2 text-xs sm:hidden'>{onDelete}</p>
			</div>
		</li>
	);
}

/**
 * Hook for atomic relationship creation via relation_provision
 * Tier 4 wrapper: single mutation replaces multi-step FK/M2M creation
 */
import { useCreateRelationProvisionMutation } from '@/components/schema-builder/compat/modules-sdk';
import { useMutation, useQueryClient } from '@tanstack/react-query';

import { RelationBelongsTo, RelationHasMany, RelationHasOne, RelationManyToMany } from 'node-type-registry';

import type { ForeignKeyAction, RelationshipType } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { buildNodeData, getDataNodeForPolicy, sanitizePolicyData } from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-config';
import { getDefaultFormValues } from '@/components/schema-builder/schema/schema-builder-policies/components/policies/policy-hooks';
import type { MergedPolicyType } from '@/components/schema-builder/schema/schema-builder-core/components/policies/policy-types';
import { buildGrants, buildPolicyEntry } from '@/components/schema-builder/schema/schema-builder-core/lib/policies/provision-helpers';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';

const RELATION_TYPE_MAP: Record<RelationshipType, string> = {
	'one-to-one': RelationHasOne.name,
	'belongs-to': RelationBelongsTo.name,
	'one-to-many': RelationHasMany.name,
	'many-to-many': RelationManyToMany.name,
} as const;

export interface RelationProvisionInput {
	relationshipType: RelationshipType;
	sourceTableId: string;
	targetTableId: string;
	/** 'c'=CASCADE, 'r'=RESTRICT, 'n'=SET NULL. Required for FK types; M2M always cascades. */
	deleteAction?: ForeignKeyAction;
	/** FK column name (auto-derived from target table name if omitted) */
	fieldName?: string;
	/** Whether FK field is NOT NULL (default: true) */
	isRequired?: boolean;
	/** Junction table name for M2M (auto-derived if omitted) */
	junctionTableName?: string;
	/** Use composite PK on junction table (M2M only) */
	useCompositeKey?: boolean;
	/** Source FK name override (M2M only) */
	sourceFieldName?: string;
	/** Target FK name override (M2M only) */
	targetFieldName?: string;
	/** Policy type for junction table (M2M only, default: AuthzAllowAll) */
	policyType?: string;
	/** Policy config data (M2M only) */
	policyData?: Record<string, unknown>;
	/** Resolved policy type object (M2M only, used to derive data nodes) */
	policyTypeObj?: MergedPolicyType;
	/** Whether to expose this M2M relation in the GraphQL API */
	exposeInApi?: boolean;
}

export interface RelationProvisionResult {
	outFieldId: string | null;
	outJunctionTableId: string | null;
	outSourceFieldId: string | null;
	outTargetFieldId: string | null;
}

export function useRelationProvision(options?: { skipTableSelect?: boolean }) {
	const queryClient = useQueryClient();
	const { selectTable, currentDatabase, currentSchema } = useSchemaBuilderSelectors();

	const createProvisionMutation = useCreateRelationProvisionMutation({
		selection: {
			fields: {
				id: true,
				outFieldId: true,
				outJunctionTableId: true,
				outSourceFieldId: true,
				outTargetFieldId: true,
			},
		},
	});

	return useMutation<RelationProvisionResult, Error, RelationProvisionInput>({
		mutationFn: async (input) => {
			const databaseId = currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId;
			if (!databaseId) throw new Error('Database ID not found');

			const relationType = RELATION_TYPE_MAP[input.relationshipType];
			if (!relationType) throw new Error(`Unsupported relationship type: ${input.relationshipType}`);

			const isManyToMany = input.relationshipType === 'many-to-many';

			// Build nodes array for M2M junction table provisioning
			let derivedNodes: Record<string, unknown>[] | undefined;
			let resolvedPolicyData = input.policyData ?? {};
			if (isManyToMany) {
				const policyName = input.policyType || 'AuthzAllowAll';
				const dataNode = getDataNodeForPolicy(policyName);

				// Ensure policyData has defaults from policy type config
				if (input.policyTypeObj) {
					const defaults = getDefaultFormValues(input.policyTypeObj);
					resolvedPolicyData = { ...defaults, ...resolvedPolicyData };
					resolvedPolicyData = sanitizePolicyData(resolvedPolicyData);
				}

				const nodes: Record<string, unknown>[] = [];

				// Add DataId for UUID PK unless using composite key
				if (!input.useCompositeKey) {
					nodes.push({ $type: 'DataId' });
				}

				if (dataNode) {
					const baseNodeData = input.policyTypeObj ? buildNodeData(resolvedPolicyData, input.policyTypeObj) : {};
					nodes.push({ $type: dataNode, ...(Object.keys(baseNodeData).length > 0 ? { data: baseNodeData } : {}) });
				}

				if (nodes.length > 0) {
					derivedNodes = nodes;
				}
			}

			const result = await createProvisionMutation.mutateAsync({
				databaseId,
				relationType,
				sourceTableId: input.sourceTableId,
				targetTableId: input.targetTableId,
				...(input.deleteAction && { deleteAction: input.deleteAction }),
				...(input.fieldName && { fieldName: input.fieldName }),
				...(input.isRequired !== undefined && { isRequired: input.isRequired }),
				...(input.junctionTableName && { junctionTableName: input.junctionTableName }),
				...(input.useCompositeKey !== undefined && { useCompositeKey: input.useCompositeKey }),
				...(input.sourceFieldName && { sourceFieldName: input.sourceFieldName }),
				...(input.targetFieldName && { targetFieldName: input.targetFieldName }),
				...(derivedNodes && { nodes: derivedNodes as unknown as Record<string, unknown> }),
				...(input.exposeInApi !== undefined && { exposeInApi: input.exposeInApi }),
				// M2M: junction table gets grants + a single policy
				...(isManyToMany && {
					grants: buildGrants() as unknown as Record<string, unknown>,
					policies: [
						buildPolicyEntry(input.policyType || 'AuthzAllowAll', {
							permissive: true,
							...(Object.keys(resolvedPolicyData).length > 0 && { data: resolvedPolicyData }),
						}),
					] as unknown as Record<string, unknown>,
				}),
			});

			const provision = result.createRelationProvision?.relationProvision;
			if (!provision) throw new Error('Failed to create relation provision');

			return {
				outFieldId: provision.outFieldId ?? null,
				outJunctionTableId: provision.outJunctionTableId ?? null,
				outSourceFieldId: provision.outSourceFieldId ?? null,
				outTargetFieldId: provision.outTargetFieldId ?? null,
			};
		},
		onSuccess: async (_result, input) => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);
			if (!options?.skipTableSelect) {
				selectTable(input.sourceTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to provision relation:', error);
		},
	});
}

/**
 * Hook for managing foreign key relationships
 * Tier 4 wrapper: orchestrates FK + M2M relationship creation
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';

import type { ForeignKeyAction, RelationshipType } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';
import { ForeignKeyActions, RelationshipTypes } from '@/components/schema-builder/schema/schema-builder-core/lib/schema';

import { asFieldIds } from '@/components/schema-builder/schema/schema-builder-core/lib/data';

// SDK hooks for foreign key mutations
import {
	useCreateFieldMutation,
	useCreateForeignKeyConstraintMutation,
	useCreatePrimaryKeyConstraintMutation,
	useCreateTableMutation,
	useCreateUniqueConstraintMutation,
	useDeleteForeignKeyConstraintMutation,
	useUpdateForeignKeyConstraintMutation,
} from '@/components/schema-builder/compat/schema-builder-sdk';
import type { CreateTableInput } from '@/components/schema-builder/compat/schema-builder-sdk';

// SDK hooks for M2M junction table creation

// SDK hook for unique constraints (used for 1:1 and M2M enforcement)

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { toFieldDefault, toFieldType } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/transformers/field-type-mapper';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { useCreateTableGrant } from '@/components/schema-builder/schema/schema-builder-policies/lib/gql/hooks/schema-builder/use-table-grants';

// Input types (replacing generated imports)
export interface ForeignKeyConstraintInput {
	tableId: string;
	fieldIds: string[];
	refTableId: string;
	refFieldIds: string[];
	name?: string | null;
	deleteAction?: ForeignKeyAction | null;
	updateAction?: ForeignKeyAction | null;
	databaseId?: string;
	type?: string;
	smartTags?: Record<string, unknown> | null;
}

export interface ForeignKeyConstraintPatch {
	name?: string | null;
	fieldIds?: string[] | null;
	refTableId?: string | null;
	refFieldIds?: string[] | null;
	deleteAction?: ForeignKeyAction | null;
	updateAction?: ForeignKeyAction | null;
}

export type CreateForeignKeyInput = Required<
	Pick<ForeignKeyConstraintInput, 'tableId' | 'fieldIds' | 'refTableId' | 'refFieldIds'>
> &
	Pick<ForeignKeyConstraintInput, 'name' | 'deleteAction' | 'updateAction'> & {
		/** Relationship type - used to enforce 1:1 with unique constraint */
		relationshipType?: RelationshipType;
	};

export type UpdateForeignKeyInput = { id: string } & Partial<
	Pick<ForeignKeyConstraintPatch, 'name' | 'fieldIds' | 'refTableId' | 'refFieldIds' | 'deleteAction' | 'updateAction'>
>;

export interface DeleteForeignKeyInput {
	id: string;
}

export function useCreateForeignKey() {
	const queryClient = useQueryClient();
	const { selectTable, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const createFkMutation = useCreateForeignKeyConstraintMutation({ selection: { fields: { id: true, name: true } } });
	const createUniqueMutation = useCreateUniqueConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: CreateForeignKeyInput) => {
			const databaseId = currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId;
			if (!databaseId) {
				throw new Error('Database ID not found');
			}

			// Step 1: Create unique constraint on the referenced field (required by PostgreSQL for FK)
			// This ensures the referenced field can be used as a FK target
			const refUniqueConstraintName = `${input.refTableId}_${input.refFieldIds.join('_')}_ref_unique`.slice(0, 63);
			try {
				await createUniqueMutation.mutateAsync({
					tableId: input.refTableId,
					databaseId,
					fieldIds: asFieldIds(input.refFieldIds),
					name: refUniqueConstraintName,
					type: 'u',
				});
			} catch (error) {
				// Ignore if unique constraint already exists (e.g., field is already PK or has unique)
				const errorMessage = error instanceof Error ? error.message : '';
				if (!errorMessage.includes('already exists') && !errorMessage.includes('duplicate')) {
					throw error;
				}
			}

			// Step 2: Create the FK constraint with relationship type stored in smartTags
			const result = await createFkMutation.mutateAsync({
				databaseId,
				tableId: input.tableId,
				fieldIds: asFieldIds(input.fieldIds),
				refTableId: input.refTableId,
				refFieldIds: asFieldIds(input.refFieldIds),
				name: input.name ?? undefined,
				deleteAction: input.deleteAction ?? ('a' as ForeignKeyAction),
				updateAction: input.updateAction ?? ('a' as ForeignKeyAction),
				type: 'f',
				smartTags: input.relationshipType ? ({ relationshipType: input.relationshipType } as Record<string, unknown>) : undefined,
			});

			const createdFk = result.createForeignKeyConstraint?.foreignKeyConstraint;
			if (!createdFk?.id) {
				throw new Error('Failed to create foreign key constraint');
			}

			// Step 3: For one-to-one relationships, add unique constraint on FK field to enforce 1:1
			if (input.relationshipType === RelationshipTypes.ONE_TO_ONE) {
				const fkName = input.name || createdFk.name || 'fk';
				const uniqueName = fkName.replace(/_fkey\d*$/, '_unique');
				await createUniqueMutation.mutateAsync({
					tableId: input.tableId,
					databaseId,
					fieldIds: asFieldIds(input.fieldIds),
					name: uniqueName,
					type: 'u',
				});
			}

			return { id: createdFk.id, name: createdFk.name ?? '' };
		},
		onSuccess: async (_createdForeignKey, variables) => {
			// Invalidate queries - selectors will derive new state automatically
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);
			// Re-select the table to ensure UI updates
			selectTable(variables.tableId);
		},
		onError: (error) => {
			console.error('Failed to create foreign key constraint:', error);
		},
	});
}

export function useUpdateForeignKey() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const updateFkMutation = useUpdateForeignKeyConstraintMutation({ selection: { fields: { id: true, name: true } } });

	return useMutation({
		mutationFn: async (input: UpdateForeignKeyInput) => {
			const patch: Record<string, unknown> = {};
			if (input.name !== undefined) patch.name = input.name;
			if (input.fieldIds !== undefined) patch.fieldIds = input.fieldIds;
			if (input.refTableId !== undefined) patch.refTableId = input.refTableId;
			if (input.refFieldIds !== undefined) patch.refFieldIds = input.refFieldIds;
			if (input.deleteAction !== undefined) patch.deleteAction = input.deleteAction;
			if (input.updateAction !== undefined) patch.updateAction = input.updateAction;

			const result = await updateFkMutation.mutateAsync({ id: input.id, foreignKeyConstraintPatch: patch });

			const updatedFk = result.updateForeignKeyConstraint?.foreignKeyConstraint;
			if (!updatedFk?.id) {
				throw new Error('Failed to update foreign key constraint');
			}
			return { id: updatedFk.id, name: updatedFk.name ?? '' };
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);

			// Re-select the current table to ensure UI updates
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to update foreign key constraint:', error);
		},
	});
}

export function useDeleteForeignKey() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const deleteFkMutation = useDeleteForeignKeyConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: DeleteForeignKeyInput) => {
			await deleteFkMutation.mutateAsync({ id: input.id });

			return { id: input.id };
		},
		onSuccess: async () => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);

			// Re-select the current table to ensure UI updates
			if (selectedTableId) {
				selectTable(selectedTableId);
			}
		},
		onError: (error) => {
			console.error('Failed to delete foreign key constraint:', error);
		},
	});
}

// === Many-to-Many Relationship ===

export interface CreateManyToManyInput {
	/** First table ID */
	tableAId: string;
	/** Second table ID */
	tableBId: string;
	/** First table name (for FK field naming) */
	tableAName: string;
	/** Second table name (for FK field naming) */
	tableBName: string;
	/** Junction table name */
	junctionTableName: string;
	/** Primary key field ID of table A */
	tableAPrimaryKeyFieldId: string;
	/** Primary key field ID of table B */
	tableBPrimaryKeyFieldId: string;
	/** FK action on delete (default: CASCADE) */
	deleteAction?: ForeignKeyAction;
	/** FK action on update (default: NO_ACTION) */
	updateAction?: ForeignKeyAction;
}

/**
 * Creates a many-to-many relationship by:
 * 1. Creating a junction table
 * 2. Creating an id field with primary key
 * 3. Creating two FK fields pointing to both related tables
 * 4. Creating two FK constraints
 * 5. Creating a composite unique constraint on (a_id, b_id) to prevent duplicates
 */
export function useCreateManyToMany() {
	const queryClient = useQueryClient();
	const { selectTable, currentDatabase, currentSchema } = useSchemaBuilderSelectors();
	const { mutateAsync: createGrant } = useCreateTableGrant();
	const createTableMutation = useCreateTableMutation({ selection: { fields: { id: true, name: true } } });
	const createFieldMutation = useCreateFieldMutation({ selection: { fields: { id: true } } });
	const createPkMutation = useCreatePrimaryKeyConstraintMutation({ selection: { fields: { id: true } } });
	const createFkMutation = useCreateForeignKeyConstraintMutation({ selection: { fields: { id: true } } });
	const createUniqueMutation = useCreateUniqueConstraintMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: CreateManyToManyInput) => {
			const databaseId = currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId;
			const schemaId = currentDatabase?.schemaId ?? currentSchema?.metadata?.schemaId;
			if (!databaseId || !schemaId) {
				throw new Error('Database ID or Schema ID not found');
			}

			const deleteAction = input.deleteAction ?? ForeignKeyActions.CASCADE;
			const updateAction = input.updateAction ?? ForeignKeyActions.NO_ACTION;

			// Step 1: Create the junction table
			// inheritsId is required in generated types but optional at GraphQL level
			const tableResult = await createTableMutation.mutateAsync({
				name: input.junctionTableName,
				databaseId,
				schemaId,
			} as CreateTableInput['table']);

			const junctionTable = tableResult.createTable?.table;
			if (!junctionTable?.id || !junctionTable?.name) {
				throw new Error('Failed to create junction table');
			}
			const junctionTableId = junctionTable.id;
			const junctionTableName = junctionTable.name;

			// Steps 2–6: All DDL on the junction table is serialized to avoid
			// PostgreSQL "tuple concurrently updated" errors. Concurrent DDL
			// statements on the same table modify the same pg_class catalog row,
			// which PostgreSQL rejects under MVCC.

			// Step 2: Create id field
			const idFieldResult = await createFieldMutation.mutateAsync({
				name: 'id',
				// type/defaultValue are structured JSONB objects in the metaschema now.
				type: toFieldType('uuid') as unknown as Record<string, unknown>,
				tableId: junctionTableId,
				databaseId,
				isRequired: true,
				defaultValue: toFieldDefault('uuidv7()') as unknown as Record<string, unknown>,
			});

			const idField = idFieldResult.createField?.field;
			if (!idField?.id) {
				throw new Error('Failed to create id field');
			}
			const idFieldId = idField.id;

			// Step 3: Create PK constraint on id field
			await createPkMutation.mutateAsync({
				tableId: junctionTableId,
				databaseId,
				fieldIds: asFieldIds([idFieldId]),
				name: `${input.junctionTableName}_pkey`,
				type: 'p',
			});

			// Step 4: Create FK fields sequentially
			const fieldAName = `${input.tableAName}_id`;
			const fieldBName = `${input.tableBName}_id`;

			const fieldAResult = await createFieldMutation.mutateAsync({
				name: fieldAName,
				// type is a structured JSONB object in the metaschema now.
				type: toFieldType('uuid') as unknown as Record<string, unknown>,
				tableId: junctionTableId,
				databaseId,
				isRequired: true,
			});

			const fieldA = fieldAResult.createField?.field;
			if (!fieldA?.id) {
				throw new Error('Failed to create FK field for table A');
			}
			const fieldAId = fieldA.id;

			const fieldBResult = await createFieldMutation.mutateAsync({
				name: fieldBName,
				// type is a structured JSONB object in the metaschema now.
				type: toFieldType('uuid') as unknown as Record<string, unknown>,
				tableId: junctionTableId,
				databaseId,
				isRequired: true,
			});

			const fieldB = fieldBResult.createField?.field;
			if (!fieldB?.id) {
				throw new Error('Failed to create FK field for table B');
			}
			const fieldBId = fieldB.id;

			// Step 5: Create FK constraints sequentially
			await createFkMutation.mutateAsync({
				databaseId,
				tableId: junctionTableId,
				fieldIds: asFieldIds([fieldAId]),
				refTableId: input.tableAId,
				refFieldIds: asFieldIds([input.tableAPrimaryKeyFieldId]),
				name: `${input.junctionTableName}_${input.tableAName}_fkey`,
				deleteAction,
				updateAction,
				type: 'f',
			});

			await createFkMutation.mutateAsync({
				databaseId,
				tableId: junctionTableId,
				fieldIds: asFieldIds([fieldBId]),
				refTableId: input.tableBId,
				refFieldIds: asFieldIds([input.tableBPrimaryKeyFieldId]),
				name: `${input.junctionTableName}_${input.tableBName}_fkey`,
				deleteAction,
				updateAction,
				type: 'f',
			});

			// Step 6: Create composite unique constraint on (a_id, b_id) to prevent duplicate pairs
			await createUniqueMutation.mutateAsync({
				tableId: junctionTableId,
				databaseId,
				fieldIds: asFieldIds([fieldAId, fieldBId]),
				name: `${input.junctionTableName}_pair_unique`,
				type: 'u',
			});

			// Step 7: Grant capabilities (non-fatal, after all DDL is complete)
			await createGrant({
				databaseId,
				tableName: junctionTableName,
				privileges: ['select', 'insert', 'update', 'delete'],
				roleName: 'authenticated',
			}).catch((error) => {
				console.warn(`Failed to grant capabilities for junction table: ${error instanceof Error ? error.message : 'Unknown error'}`);
			});

			return {
				junctionTableId,
				junctionTableName,
			};
		},
		onSuccess: async (result) => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId ?? currentSchema?.metadata?.databaseId);
			// Select the newly created junction table
			if (result?.junctionTableId && result?.junctionTableName) {
				selectTable(result.junctionTableId, result.junctionTableName);
			}
		},
		onError: (error) => {
			console.error('Failed to create many-to-many relationship:', error);
		},
	});
}

