export type RenameTableCardProps = {
	tableId: string;
	tableName: string;
	onTableRenamed?: (table: { id: string; name: string }) => void;
};

export const RenameTableCard: CardComponent<RenameTableCardProps> = ({
	tableId,
	tableName,
	onTableRenamed,
	card,
}) => {
	const [newName, setNewName] = useState(tableName);
	const updateTableMutation = useUpdateTable();
	const { currentSchema } = useSchemaBuilderSelectors();

	const existingTableNames = useMemo(
		() =>
			new Set(
				(currentSchema?.tables || [])
					.filter((table) => table.id !== tableId)
					.map((table) => table.name.toLowerCase()),
			),
		[currentSchema?.tables, tableId],
	);

	const trimmedName = newName.trim();
	const isDuplicate = trimmedName && existingTableNames.has(trimmedName.toLowerCase());
	const isUnchanged = trimmedName === tableName;
	const isValidName = trimmedName && !isDuplicate && !isUnchanged;

	const handleSubmit = async (e: React.FormEvent) => {
		e.preventDefault();

		if (!trimmedName) {
			showErrorToast({
				message: 'Table name is required',
				description: 'Please enter a name for the table.',
			});
			return;
		}

		if (isDuplicate) {
			showErrorToast({
				message: 'Name already exists',
				description: 'A table with this name already exists.',
			});
			return;
		}

		try {
			await updateTableMutation.mutateAsync({
				id: tableId,
				name: trimmedName,
			});

			showSuccessToast({
				message: 'Table renamed',
				description: `Table renamed to "${trimmedName}"`,
			});

			if (onTableRenamed) {
				onTableRenamed({ id: tableId, name: trimmedName });
			}

			card.close();
		} catch (error) {
			console.error('Failed to rename table:', error);
			showErrorToast({
				message: 'Failed to rename table',
				description: error instanceof Error ? error.message : 'An unexpected error occurred.',
			});
		}
	};

	return (
		<div className='flex h-full flex-col'>
			<form id='rename-table-form' onSubmit={handleSubmit} className='space-y-4 p-6'>
				<div className='grid gap-2'>
					<Label htmlFor='name'>Table Name</Label>
					<Input
						id='name'
						placeholder='table_name'
						value={newName}
						onChange={(e) => setNewName(e.target.value)}
						required
						autoComplete='off'
						autoFocus
						className={isDuplicate ? 'border-destructive' : ''}
					/>
					{isDuplicate && <p className='text-destructive text-xs'>A table with this name already exists</p>}
				</div>
			</form>

			<div className='mt-auto flex justify-end gap-2 border-t p-4'>
				<Button type='button' variant='outline' disabled={updateTableMutation.isPending} onClick={() => card.close()}>
					Cancel
				</Button>
				<Button type='submit' form='rename-table-form' disabled={updateTableMutation.isPending || !isValidName}>
					{updateTableMutation.isPending && <Loader2Icon className='mr-2 h-4 w-4 animate-spin' />}
					{updateTableMutation.isPending ? 'Renaming...' : 'Rename'}
				</Button>
			</div>
		</div>
	);
};

/**
 * Hook for deleting a table
 * Tier 4 wrapper: adds table selection handling after deletion
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useDeleteTableMutation } from '@/components/schema-builder/compat/schema-builder-sdk';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';

export interface DeleteTableInput {
	id: string;
}

export function useDeleteTable() {
	const queryClient = useQueryClient();
	const { currentSchema, selectedTableId, selectTable, selectedSchemaKey, currentDatabase } = useSchemaBuilderSelectors();
	const deleteTableMutation = useDeleteTableMutation({ selection: { fields: { id: true } } });

	return useMutation({
		mutationFn: async (input: DeleteTableInput): Promise<string> => {
			await deleteTableMutation.mutateAsync({
				id: input.id,
			});

			return input.id;
		},
		onSuccess: async (deletedId, variables) => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId);

			const isSelectedTable = selectedTableId === deletedId;

			let newSelectedTable: { id: string; name: string } | null = null;

			if (isSelectedTable && selectedSchemaKey) {
				const currentTables = currentSchema?.tables || [];

				if (currentTables.length > 1) {
					const deletedTableIndex = currentTables.findIndex((table) => table.id === deletedId);
					const remainingTables = currentTables.filter((table) => table.id !== deletedId);

					if (deletedTableIndex < remainingTables.length) {
						// Select the table that will be at the same index after deletion
						newSelectedTable = remainingTables[deletedTableIndex];
					} else {
						// Deleted table was the last one, select the previous table
						newSelectedTable = remainingTables[remainingTables.length - 1];
					}
				}
			}

			if (newSelectedTable) {
				selectTable(newSelectedTable.id, newSelectedTable.name);
			} else if (isSelectedTable) {
				selectTable(null);
			}
		},
		onError: (error) => {
			console.error('Failed to delete table:', error);
		},
	});
}

/**
 * Hook for updating a table
 * Tier 4 wrapper: adds table re-selection after update
 */
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useUpdateTableMutation } from '@/components/schema-builder/compat/schema-builder-sdk';

import { invalidateDatabaseEntities } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/modules/invalidate-database-entities';
import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';

export interface UpdateTableInput {
	id: string;
	name?: string;
	label?: string | null;
	description?: string | null;
	smartTags?: Record<string, unknown> | null;
}

export interface UpdatedTable {
	id: string;
	name: string;
}

export function useUpdateTable() {
	const queryClient = useQueryClient();
	const { selectTable, selectedTableId, currentDatabase } = useSchemaBuilderSelectors();
	const updateTableMutation = useUpdateTableMutation({ selection: { fields: { id: true, name: true } } });

	return useMutation({
		mutationFn: async (input: UpdateTableInput): Promise<UpdatedTable> => {
			const { id, ...patchFields } = input;

			const result = await updateTableMutation.mutateAsync({
				id,
				tablePatch: patchFields,
			});

			const table = result.updateTable?.table;
			if (!table?.id || !table?.name) {
				throw new Error('Failed to update table');
			}

			return { id: table.id, name: table.name };
		},
		onSuccess: async (updatedTable) => {
			await invalidateDatabaseEntities(queryClient, currentDatabase?.databaseId);

			// Re-select the updated table and update URL if this was the selected table
			if (updatedTable.id && updatedTable.name && selectedTableId === updatedTable.id) {
				selectTable(updatedTable.id, updatedTable.name);
			}
		},
		onError: (error) => {
			console.error('Failed to update table:', error);
		},
	});
}

