			<div className='flex min-w-0 flex-1 items-center gap-2 overflow-hidden'>
				{leftPanelVisible ? null : (
					<TooltipIconButton className='hidden sm:grid' label='Show table sidebar' onClick={() => setLeftPanelVisible(true)}>
						<PanelLeft aria-hidden='true' className='size-3.5' />
					</TooltipIconButton>
				)}

				<Tabs className='min-w-0 flex-1 gap-0' value={activeTab} onValueChange={setActiveTab}>
					<TabsList
						className={cn(
							'bg-muted/70 h-auto max-w-full justify-start overflow-x-auto rounded-lg p-0.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden',
							'[&>[data-slot=tabs-indicator]]:bg-card [&>[data-slot=tabs-indicator]]:rounded-[6px] [&>[data-slot=tabs-indicator]]:shadow-card dark:[&>[data-slot=tabs-indicator]]:bg-foreground/10',
						)}
					>
						{BUILT_IN_TABS.map(({ value, label, icon: Icon }) => (
							<TabsTrigger className={TRIGGER} key={value} value={value}>
								<Icon aria-hidden='true' />
								<span className={cn(value !== activeTab && 'max-md:sr-only')}>{label}</span>
							</TabsTrigger>
						))}
						{tabs.filter((tab) => !tab.hidden).map((tab) => (
							<TabsTrigger className={TRIGGER} key={tab.id} value={tab.id} onMouseEnter={() => void tab.preload?.()}>
								{tab.label}
							</TabsTrigger>
						))}
					</TabsList>
				</Tabs>
			</div>

			{hasSystemTablesInCurrentSchema && (
				<button
					type='button'
					aria-label={showSystemTablesInSidebar ? 'Hide system tables' : 'Show system tables'}
					aria-pressed={showSystemTablesInSidebar}
					className={cn(
						'hidden h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2 text-[13px] sm:inline-flex',
						showSystemTablesInSidebar
							? 'bg-overlay-hover text-foreground'
							: 'text-muted-foreground hover:bg-overlay-hover hover:text-foreground',
						pressClass,
						focusRingClass,
					)}
					onClick={() => setShowSystemTablesInSidebar(!showSystemTablesInSidebar)}
				>
					{showSystemTablesInSidebar ? <Eye aria-hidden='true' className='size-3.5' /> : <EyeOff aria-hidden='true' className='size-3.5' />}
					System tables
				</button>
			)}
		</div>
	);
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { TooltipProvider } from '@/components/ui/tooltip';

import { useSchemaBuilderSelectors } from '@/components/schema-builder/schema/schema-builder-core/lib/gql/hooks/schema-builder/use-schema-builder-selectors';
import { NoDatabasesEmptyState } from '@/components/schema-builder/schema/schema-builder-core/components/databases';
import { ContentFadeIn, SchemaBuilderSkeleton } from '@/components/schema-builder/schema/schema-builder-core/components/skeletons';
import { TableEditor } from '@/components/schema-builder/schema/schema-builder-fields/components/table-editor/table-editor';
import { RelationshipsView } from '@/components/schema-builder/schema/schema-builder-relationships/components/table-editor/relationships';
import { IndexesView } from '@/components/schema-builder/schema/schema-builder-indexes/components/table-editor/indexes';
import { PoliciesView } from '@/components/schema-builder/schema/schema-builder-policies/components/table-editor/policies';
import { SchemaBuilderHeader } from '../schema-builder-header';

import { ClientOnly } from '../client-only';
import {
	SchemaBuilderMobileNavigation,
	SchemaBuilderSidebar,
} from '@/components/schema-builder/schema/schema-builder-tables/components/schemas/schema-builder-sidebar';
import { SchemaStateDisplay } from '@/components/schema-builder/schema/schema-builder-core/components/schemas/schema-state-display';
import {
	useSchemaBuilderRuntime,
	useSchemaBuilderRuntimeStore,
} from '@/components/schema-builder/compat/block-config';

export function SchemasRoute({ emptyState }: { emptyState?: ReactNode } = {}) {
	const [leftPanelVisible, setLeftPanelVisible] = useState(true);
	const activeTab = useSchemaBuilderRuntimeStore((state) => state.activeTab);
	const showSystemTablesInSidebar = useSchemaBuilderRuntimeStore(
		(state) => state.preferences.showSystemTablesInSidebar,
	);
	const { colorMode, scope, tabs = [], setActiveTab, setPreferences } = useSchemaBuilderRuntime();
	const setShowSystemTablesInSidebar = (show: boolean) =>
		setPreferences((preferences) => ({ ...preferences, showSystemTablesInSidebar: show }));

	const {
		availableSchemas,
		currentSchema,
		currentTable,
		selectTable,
		isLoading,
		error: remoteSchemasError,
		refetch,
	} = useSchemaBuilderSelectors();

	const hasSystemTablesInCurrentSchema = useMemo(() => {
		const tables = currentSchema?.tables ?? [];
		if (tables.length === 0) return false;

		const hasCategoryData = tables.some((table) => table.category !== undefined);
		if (!hasCategoryData) return false;

		return tables.some((table) => table.category !== 'APP');
	}, [currentSchema?.tables]);

	useEffect(() => {
		if (!currentSchema || currentTable) return;

		const firstAppTable = currentSchema.tables.find((table) => table.category === 'APP');
		if (firstAppTable) {
			selectTable(firstAppTable.id, firstAppTable.name);
		}
	}, [currentSchema, currentTable, selectTable]);

	const databaseSchemas = availableSchemas.filter((s) => s.source === 'database');
	const hasDatabases = databaseSchemas.length > 0;
	const showSkeleton = isLoading && !hasDatabases;
	const extensionTab = tabs.find((tab) => tab.id === activeTab);

	const loadingFallback = (
		<div className='bg-background text-foreground flex h-full flex-col overflow-hidden'>
			<SchemaBuilderSkeleton />
		</div>
	);

	return (
		<ClientOnly fallback={loadingFallback}>
			<TooltipProvider>
				<div
					data-chat-component='schemas-route'
					data-chat-active-tab={activeTab}
					className='bg-background text-foreground flex h-full flex-col overflow-hidden'
				>
					{remoteSchemasError && (
						<SchemaStateDisplay
							config={{
								type: 'error',
								message: remoteSchemasError.message,
								error: remoteSchemasError,
								onRetry: refetch,
							}}
						/>
					)}

					{showSkeleton && !remoteSchemasError && <SchemaBuilderSkeleton />}

					{!remoteSchemasError && !showSkeleton && !hasDatabases && (emptyState ?? <NoDatabasesEmptyState />)}

					{!remoteSchemasError && !showSkeleton && hasDatabases && (
						<ContentFadeIn className='flex min-h-0 min-w-0 flex-1'>
							{leftPanelVisible && (
								<SchemaBuilderSidebar onHide={() => setLeftPanelVisible(false)} showSystemTables={showSystemTablesInSidebar} />
							)}

							<div className='flex min-h-0 min-w-0 flex-1 flex-col'>
								<SchemaBuilderMobileNavigation
									hasSystemTables={hasSystemTablesInCurrentSchema}
									onShowSystemTablesChange={setShowSystemTablesInSidebar}
									showSystemTables={showSystemTablesInSidebar}
								/>
								<SchemaBuilderHeader
									leftPanelVisible={leftPanelVisible}
									setLeftPanelVisible={setLeftPanelVisible}
									activeTab={activeTab}
									setActiveTab={setActiveTab}
									showSystemTablesInSidebar={showSystemTablesInSidebar}
									setShowSystemTablesInSidebar={setShowSystemTablesInSidebar}
									hasSystemTablesInCurrentSchema={hasSystemTablesInCurrentSchema}
									tabs={tabs}
								/>

								<div className='flex min-h-0 flex-1 flex-col overflow-hidden'>
									{activeTab === 'editor' && <TableEditor />}

									{activeTab === 'relationships' && <RelationshipsView />}

									{activeTab === 'indexes' && <IndexesView />}

									{activeTab === 'security' && <PoliciesView />}

									{extensionTab?.render({ scope, colorMode, selectedTableId: currentTable?.id ?? null })}
								</div>
							</div>
						</ContentFadeIn>
					)}
				</div>
			</TooltipProvider>
		</ClientOnly>
	);
}

export { SchemaBuilderSidebar } from '../schema/schema-builder-tables/components/schemas/schema-builder-sidebar';
export { useDeleteTable } from '../schema/schema-builder-tables/lib/gql/hooks/schema-builder/use-delete-table';
